// Registre global des audios "mutables au retournement du téléphone" (cf.
// _installUniversalFlipToMute plus bas, tout en bas du fichier). Déclaré ICI,
// tout en haut, car plusieurs IIFE plus bas (SalatNabi, alerte vocale iqama,
// takbir) doivent s'y enregistrer AU MOMENT de leur propre exécution (leur
// <audio> est parfois un élément DÉTACHÉ du DOM, capturé uniquement via
// fermeture — un simple document.getElementById() ne le retrouverait pas).
// Chaque entrée est une fonction () => HTMLAudioElement|null, appelée
// PARESSEUSEMENT au moment du flip (pas à l'enregistrement) pour toujours
// cibler l'élément audio courant, y compris s'il est recréé entre-temps.
window._ucFlipMuteRegistry = [];
function _ucRegisterFlipMuteTarget(getAudioFn) {
    window._ucFlipMuteRegistry.push(getAudioFn);
}
/*
 * Mapping des déclenchements des items "light programming"
 * --------------------------------------------------------
 *
 * NOTE:
 * - Les `lightCfgBtn_*` dans l'UI ne déclenchent pas directement le fetch.
 * - Ces boutons servent à éditer l'URL stockée dans `JS_CUSTOM[...]`.
 * - Le fetch réel part via `_ucHttpCall(url, item.key)` dans les handlers runtime.
 *
 * Détail item par item :
 *
 * 1) lightCfgBtn_ampliIntOn
 *    - key: `ampliIntOn`
 *    - trigger: `beforeIqama`
 *    - source runtime: `UC_EVT.COUNTDOWN_TICK`
 *    - moment exact: au premier tick où `e.remainingSeconds <= ucLightAmpliIntOnDelay`
 *    - conditions: `ucLightAmpliIntOnEnabled == 1` et `ucLightAmpliIntOffEnabled == 1`
 *
 * 2) lightCfgBtn_ampliIntOff
 *    - key: `ampliIntOff`
 *    - trigger: `afterBlackHide`
 *    - source runtime: `UC_EVT.BLACK_HIDE`
 *    - moment exact: à la fermeture du rideau noir, puis après `ucLightAmpliIntOffDelay`
 *
 * 3) lightCfgBtn_ampliExtOn
 *    - key: `ampliExtOn`
 *    - trigger: `beforeAzan`
 *    - source runtime: pas de `UC_EVT` direct
 *    - appelé depuis `applyNextPrayerHighlight()` -> `_applyLightTriggers(remainingMinutes)`
 *    - moment exact: quand `remainingMinutes <= ucLightAmpliExtOnDelay / 60`
 *    - conditions: `ucLightAmpliExtOnEnabled == 1` et `ucLightAmpliExtOffEnabled == 1`
 *
 * 4) lightCfgBtn_ampliExtOff
 *    - key: `ampliExtOff`
 *    - trigger: `afterAzanHide`
 *    - source runtime: `UC_EVT.AZAN_HIDE`
 *    - moment exact: à la fermeture de la fenêtre adhan, puis après délai
 *    - délai normal: `ucLightAmpliExtOffDelay`
 *    - délai vendredi: `ucLightAmpliExtOffDelayJomoa` si `_lastAzanPrayer === 'JOMOA'`
 *
 * 5) lightCfgBtn_minaretOn
 *    - key: `minaretOn`
 *    - trigger: `afterAzanShow`
 *    - source runtime: `UC_EVT.AZAN_SHOW`
 *    - moment exact: juste après affichage de la fenêtre adhan, uniquement si `e.prayer === 'MGRB'`
 *    - délai: `ucLightMinaretOnDelay`
 *    - conditions: `ucLightMinaretOnEnabled == 1` et `ucLightMinaretOffEnabled == 1`
 *
 * 6) lightCfgBtn_minaretOff
 *    - key: `minaretOff`
 *    - trigger: `afterAzanShow`
 *    - source runtime: `UC_EVT.AZAN_SHOW`
 *    - moment exact: juste après affichage de la fenêtre adhan, uniquement si `e.prayer === 'FAJR'`
 *    - délai: `ucLightMinaretOffDelay`
 *    - conditions: `ucLightMinaretOffEnabled == 1` et `ucLightMinaretOnEnabled == 1`
 *
 * 7) (strobingOn / strobingOff supprimés du config)
 *    Le strobing est exclusivement géré par iqamaZeroMinaretBlinkCb et
 *    iqamaZeroMihrabBlinkCb, déclenchés à remainingSeconds = 0 (UC_EVT.IQAMA_TIME).
 *    Aucun strobe ne se déclenche pendant le compte à rebours.
 *
 * 8) lightCfgBtn_mihrabOn
 *    - key: `mihrabOn`
 *    - trigger: `afterAzanHide`
 *    - source runtime: `UC_EVT.AZAN_HIDE`
 *    - moment exact: à la fermeture de la fenêtre adhan, puis après `ucLightMihrabOnDelay`
 *    - conditions: `ucLightMihrabOnEnabled == 1`, `ucLightMihrabOffEnabled == 1`
 *    - filtre prière: masque `ucLightMihrabOnPrayers`
 *
 * 10) lightCfgBtn_mihrabOff
 *    - key: `mihrabOff`
 *    - trigger: `afterBlackHide`
 *    - source runtime: `UC_EVT.BLACK_HIDE`
 *    - moment exact: à la fermeture du rideau noir, puis après `ucLightMihrabOffDelay`
 *    - condition: `ucLightMihrabOffEnabled == 1`
 *
 * 11) lightCfgBtn_rollerOpen
 *    - key: `rollerOpen`
 *    - trigger: `beforeIqama`
 *    - source runtime: `UC_EVT.COUNTDOWN_TICK`
 *    - moment exact: au premier tick où `e.remainingSeconds <= ucLightRollerOpenDelay`
 *    - conditions: `ucLightRollerOpenEnabled == 1` et `ucLightRollerCloseEnabled == 1`
 *
 * 12) lightCfgBtn_rollerClose
 *    - key: `rollerClose`
 *    - trigger: `afterBlackHide`
 *    - source runtime: `UC_EVT.BLACK_HIDE`
 *    - moment exact: à la fermeture du rideau noir, puis après `ucLightRollerCloseDelay`
 *    - condition: `ucLightRollerCloseEnabled == 1`
 *
 * Résumé des sources runtime :
 * - `beforeAzan`     -> pas de `UC_EVT` direct, passe par `applyNextPrayerHighlight()`
 * - `afterAzanShow`  -> `UC_EVT.AZAN_SHOW`
 * - `afterAzanHide`  -> `UC_EVT.AZAN_HIDE`
 * - `beforeIqama`    -> `UC_EVT.COUNTDOWN_TICK`
 * - `strobePair`     -> pas de `UC_EVT` direct, piloté par `_runStrobe(...)`
 * - `afterBlackHide` -> `UC_EVT.BLACK_HIDE`
 */



// ── VERSION CUSTOM (override sans toucher aux fichiers std) ───────────────
// Seul CUSTOM_APP_VERSION à modifier pour changer la version affichée partout
// dans l'app (onglet navigateur, écran principal, "À propos", menu latéral) —
// cf. release/instapk.ps1 "setversion" pour la mettre à jour automatiquement
// ici ET dans app/build.gradle (versionName/versionCode) en une seule commande.
var CUSTOM_APP_VERSION = '12.07';
document.title = 'TAWKIT.NET ' + CUSTOM_APP_VERSION; //Titre onglet navigateur

if (typeof appVersionString !== 'undefined') { // Affichage de la version dans l'app (en bas à droite) et dans la page "À propos"
    appVersionString = appVersionString.replace('9.63', CUSTOM_APP_VERSION);

    // Page principale (versionDisplayId en mode vertical, tawkitNameDisplayHorizontal
    // en mode horizontal) : numéro de version seul, sans mention supplémentaire —
    // c'est l'écran vu en continu, pas l'endroit pour une précision de build.
    ['versionDisplayId', 'tawkitNameDisplayHorizontal'].forEach(function(id) {
        const el = document.getElementById(id);
        if (el) el.innerHTML = el.innerHTML.replace('9.63', CUSTOM_APP_VERSION);
    });

    // Hors page principale (menu latéral, page "À propos") : précise qu'il
    // s'agit d'une version spécifique (build personnalisé pour cette mosquée,
    // cf. spec/mosquee.js), pas juste le numéro de version générique.
    var SPECIFIC_VERSION_NOTE = ' (نسخة خاصة)';
    var _applySpecificVersionNote = function() {
        ['aboutAppTitle', 'menuVersionDisplay'].forEach(function(id) {
            var el = document.getElementById(id);
            if (el && el.innerHTML.indexOf(SPECIFIC_VERSION_NOTE) === -1) {
                el.innerHTML = el.innerHTML.replace('9.63', CUSTOM_APP_VERSION) + SPECIFIC_VERSION_NOTE;
            }
        });
    };
    _applySpecificVersionNote();

    // `aboutAppTitleElement`/`menuVersionDisplayElement` sont réécrits à partir
    // de `appVersionString` brut à chaque recalcul des horaires
    // (calculateAndDisplayTimesFunction → updateMosqueAndDateDisplayFunction
    // pour aboutAppTitle, + affectation directe de menuVersionDisplay dans
    // calculateAndDisplayTimesFunction lui-même) — la mention ci-dessus serait
    // donc effacée au prochain tick sans ce monkey-patch (même pattern que
    // _patchJomoaDisplay() plus bas : appeler l'original puis ré-appliquer).
    if (typeof calculateAndDisplayTimesFunction === 'function') {
        var _origCalcDisplay = calculateAndDisplayTimesFunction;
        window.calculateAndDisplayTimesFunction = function() {
            _origCalcDisplay.apply(this, arguments);
            _applySpecificVersionNote();
        };
    }

    // Filet de sécurité : certains appels internes à m2body.js peuvent avoir
    // capturé une référence à calculateAndDisplayTimesFunction AVANT le
    // monkey-patch ci-dessus (custom.js s'exécute en dernier, cf. CLAUDE.md
    // ordre de chargement) et l'invoquer directement au tout premier rendu
    // après un reload — la mention est alors absente un court instant, avant
    // qu'un tick suivant (correctement patché) ne la rétablisse (constaté :
    // "TAWKIT.NET 10.1A" sans la mention juste après reload, correct dès
    // qu'on ré-inspecte l'élément quelques instants plus tard). Un
    // MutationObserver réagit à TOUT changement de contenu, quelle qu'en soit
    // la cause exacte, garantissant la mention dès le tout premier rendu.
    if (typeof MutationObserver === 'function') {
        ['aboutAppTitle', 'menuVersionDisplay'].forEach(function(id) {
            var el = document.getElementById(id);
            if (!el) return;
            var mo = new MutationObserver(function() { _applySpecificVersionNote(); });
            mo.observe(el, { characterData: true, childList: true, subtree: true });
        });
    }
}
