// ── PATCH jomoaTimeDisplayHorizontal ─────────────────────────────────────────
// Problème : la variable interne `jomoaFixedTime` (let dans m2body.js) n'est
// mise à jour depuis JS_DATA.ucJomoaFixedTime QUE les vendredis (if isFriday).
// Les autres jours, updateMosqueAndDateDisplayFunction() l'affiche comme 'AUTO',
// ce qui donne '0AUTO' (convertTo12HourFormat préfixe '0' si length < 5 en 24h).
// Solution : wrapper la fonction pour corriger l'élément à chaque appel,
// en lisant directement JS_DATA.ucJomoaFixedTime (toujours à jour).
(function _patchJomoaDisplay() {
    if (typeof updateMosqueAndDateDisplayFunction !== 'function') return;
    var _orig = updateMosqueAndDateDisplayFunction;
    window.updateMosqueAndDateDisplayFunction = function() {
        _orig();
        var _jt = JS_DATA.ucJomoaFixedTime;
        // Corriger uniquement si la valeur fixe est définie (pas AUTO ni vide)
        if (!_jt || _jt === 'AUTO' || _jt === '') return;
        var _el = document.getElementById('jomoaTimeDisplayHorizontal');
        if (!_el) return;
        if (typeof convertTo12HourFormat !== 'function' ||
            typeof convertToArabicDigitsFunction !== 'function') return;
        _el.innerHTML = convertToArabicDigitsFunction(convertTo12HourFormat(_jt));
    };
    console.log('[CFG] patch jomoaTimeDisplayHorizontal installé');
})();
