// ── Aya aléatoire : masque le message de diagnostic interne du core ──────────
// Bug source (m2body.js, displayRandomAyaFunction, core, non modifiable) :
// après 20 tentatives infructueuses pour choisir une aya aléatoire valide
// (longueur compatible avec l'écran, période spéciale, etc.), le core écrit
// littéralement "error _RECURSIONS : ayats-XX" dans #ayaTextDisplayVertical/
// Horizontal — un texte de diagnostic interne, jamais loggé nulle part (d'où
// l'absence totale de trace console), qui reste affiché à l'utilisateur
// jusqu'au prochain appel (déclenché seulement au démarrage puis une fois par
// minute, à la seconde '08' — d'où le délai avant correction observé).
// On ne peut pas patcher la fonction elle-même sans dupliquer toute sa
// logique de sélection/filtrage : on observe donc le DOM et, si ce texte
// apparaît, on restaure la dernière aya valide affichée puis on relance un
// essai quasi immédiat au lieu d'attendre la minute suivante.
(function _fixAyaRecursionErrorFlash() {
    var vEl = document.getElementById('ayaTextDisplayVertical');
    var hEl = document.getElementById('ayaTextDisplayHorizontal');
    if (!vEl && !hEl) return;

    var ERROR_MARKER   = 'error _RECURSIONS';
    var _lastGoodHtml  = { ayaTextDisplayVertical: '', ayaTextDisplayHorizontal: '' };
    var _retryScheduled = false;

    function _checkAndFix(el) {
        // subtree:true + characterData:true peuvent rapporter un noeud texte
        // (mutation en place, pas via innerHTML=) : on ne traite que les
        // éléments eux-mêmes, avec leur propriété innerHTML.
        if (el && el.nodeType !== 1) el = el.parentElement;
        if (!el || typeof el.innerHTML !== 'string') return;
        if (el.innerHTML.indexOf(ERROR_MARKER) === -1) {
            _lastGoodHtml[el.id] = el.innerHTML;
            return;
        }
        _L('AYA', 'RESCUE', { el: el.id, reason: 'recursion_cap_hit' });
        el.innerHTML = _lastGoodHtml[el.id] || '';
        if (!_retryScheduled) {
            _retryScheduled = true;
            setTimeout(function() {
                _retryScheduled = false;
                if (typeof window.displayRandomAyaFunction === 'function') window.displayRandomAyaFunction();
            }, 400);
        }
    }

    var _ayaObserver = new MutationObserver(function(mutations) {
        mutations.forEach(function(m) { _checkAndFix(m.target); });
    });
    [vEl, hEl].forEach(function(el) {
        if (el) _ayaObserver.observe(el, { childList: true, characterData: true, subtree: true });
    });
})();
