// ── AZKAR (page "doaa" après azan) : anti-débordement en mode vertical ───────
// Bug source (m2body.js, displayNextAzkarFunction) : la taille de police est
// calculée uniquement à partir du nombre de caractères du bloc
// (calculateFontSizeFunction), sans tenir compte du nombre de lignes (<br>)
// qu'il contient. Un bloc avec beaucoup de lignes courtes (ex. le 1er bloc de
// JS_GLOBAL_AZKAR_VR : 6 courtes phrases) obtient donc une police proche du
// maximum (10.4vw en vertical, le plus grand des deux réglages) alors que sur
// 6 lignes cumulées ça déborde largement de #azkarTextWrapperVertical
// (haut:0, height:100% dans une zone qui ne fait que 78% de l'écran) — le
// texte déborde alors par-dessus l'horloge/les horaires affichés autour,
// donnant l'impression que tout est "mélangé" au milieu de l'écran.
// Correctif : après chaque mise à jour du texte, on réduit la police par
// petits paliers jusqu'à ce que le contenu tienne réellement dans sa zone.
(function _fixAzkarOverflowVertical() {
    if (typeof window.displayNextAzkarFunction !== 'function') {
        console.warn('[AZKAR] displayNextAzkarFunction introuvable -- patch annulé');
        return;
    }

    var _origDisplayNextAzkar = window.displayNextAzkarFunction;
    window.displayNextAzkarFunction = function() {
        _origDisplayNextAzkar.apply(this, arguments);
        // Court délai : laisse le layout se stabiliser (scrollHeight fiable
        // seulement après le reflow qui suit l'injection du texte/de la police).
        setTimeout(_ucShrinkAzkarTextToFit, 30);
    };

    function _ucShrinkAzkarTextToFit() {
        var el   = document.getElementById('azkarTextDisplayVertical');
        var wrap = document.getElementById('azkarTextWrapperVertical');
        if (!el || !wrap || !el.textContent) return;

        var currentSize = parseFloat(window.getComputedStyle(el).fontSize);
        if (!currentSize) return;

        var guard = 0;
        while (el.scrollHeight > wrap.clientHeight && currentSize > 10 && guard < 40) {
            currentSize -= 1;
            el.style.fontSize = currentSize + 'px';
            guard++;
        }
    }

    console.log('[AZKAR] patch anti-débordement (vertical) installé');
})();
