// ── QR CODE — UNIQUE QR ───────────────────────────────────────────────────────
// Affichage d'un QR code unique basé sur spec/images/qrmosquee.png.
// Piloté par JS_DATA.ucQrFlag.
// ─────────────────────────────────────────────────────────────────────────────
(function _patchQrFlag() {
    if (typeof updatePsFlagVisibilityFunction !== 'function') {
        console.warn('[QR] updatePsFlagVisibilityFunction introuvable -- patch annule');
        return;
    }

    var _SRC = 'spec/images/qrmosquee.png';

    // -- Helpers visuels -------------------------------------------------------
    function _applyLayoutClass(isQr) {
        var vc = document.getElementById('mainVerticalContainer');
        var hc = document.getElementById('mainHorizontalContainer');
        if (vc) vc.classList.toggle('uc-qr-active', isQr);
        if (hc) hc.classList.toggle('uc-qr-active', isQr);
    }

    function _setImgSrc(id, src, visible) {
        var el = document.getElementById(id);
        if (!el) return;
        if (src) el.src = src;
        el.style.visibility = visible ? 'visible' : 'hidden';
    }

    function _applyQrVisibility() {
        if (typeof JS_DATA.ucQrFlag === 'undefined') JS_DATA.ucQrFlag = 0;
        var isQr = (JS_DATA.ucQrFlag == 1);
        var cb = document.getElementById('qrFlagCheckbox');
        if (cb) cb.checked = isQr;
        _applyLayoutClass(isQr);

        // qrFlagImageVertical retiré définitivement : remplacé par psFlagImageVertical
        // + le lien de menu (cf. section "QR CODE — modale d'agrandissement" plus bas).
        // Toujours masqué, quelle que soit ucQrFlag. qrFlagImageHorizontal (mode
        // horizontal) conserve son comportement d'origine, inchangé.
        _setImgSrc('qrFlagImageVertical',   _SRC, false);
        _setImgSrc('qrFlagImageHorizontal', _SRC, isQr);

        _L('QR', 'VISIBILITY', { isQr: isQr });
    }

    // -- Toggle ----------------------------------------------------------------
    window.toggleQrFlagFunction = function() {
        JS_DATA.ucQrFlag = +(JS_DATA.ucQrFlag != 1);
        saveSettingsToStorageFunction();
        _applyQrVisibility();
    };

    var _origFn = updatePsFlagVisibilityFunction;
    window.updatePsFlagVisibilityFunction = function() { _origFn(); _applyQrVisibility(); };

    // -- Lancement ------------------------------------------------------------
    updatePsFlagVisibilityFunction();

    window.addEventListener('load', function() {
        setTimeout(_applyQrVisibility, 250);
        setTimeout(_applyQrVisibility, 1500);
    });

    _L('QR', 'INIT', { mode: 'static_png', src: _SRC });
})();
