// ── QR CODE — modale d'agrandissement — UNIQUE point d'entrée : psFlagImageVertical ──
// qrFlagImageVertical et qrFlagCheckbox sont retirés de l'usage (cf. plus haut :
// qrFlagImageVertical forcé masqué en permanence dans _applyQrVisibility ;
// qrFlagCheckbox masqué ci-dessous). Seuls restent :
//   - #psFlagImageVertical : simple clic/tap = ouvre la modale (JAMAIS de
//     rafraîchissement) ; double clic/tap = restartApplicationFunction().
//     Ne touche pas #psFlagImageHorizontal.
//   - Un lien de menu (#ucQrCodeMenuLink, injecté après la section "onboarding
//     tour" plus bas, pour s'insérer juste après #ucTourRelaunchLink) qui ouvre
//     exactement la même modale.
// Aucun lien avec customSpeakerIcon / customQuranIcon ni positionCustomIcons() :
// aucun impact sur leur positionnement.
(function injectQrCodeModal() {

    var QR_SRC = 'spec/images/qrmosquee.png';

    var overlay = document.createElement('div');
    overlay.id = 'qrCodeOverlay';
    overlay.className = 'qcHidden';
    overlay.onclick = function (e) { if (e.target === overlay) closeQrCodeModal(); };

    overlay.innerHTML =
        '<div id="qrCodeModal">' +
            '<div id="qrCodeHeader">' +
                '<div id="qrCodeTitle">رمز QR الخاص بالمسجد</div>' +
                '<div id="qrCodeClose">&#10006;</div>' +
            '</div>' +
            '<div id="qrCodeBody">' +
                '<img id="qrCodeImageBig" alt="QR" src="' + QR_SRC + '">' +
                '<div id="qrCodeMosqueName"></div>' +
                '<div id="qrCodeHint">وجّه كاميرا هاتفك نحو الرمز لمسحه</div>' +
            '</div>' +
        '</div>';

    document.documentElement.appendChild(overlay);

    var _qcCloseBtn = document.getElementById('qrCodeClose');
    if (_qcCloseBtn) _qcCloseBtn.addEventListener('click', function (e) {
        e.preventDefault(); e.stopPropagation();
        closeQrCodeModal();
    });

    // Clic sur l'en-tête de la modale (hors bouton fermer, qui stoppe déjà sa
    // propagation) -> affiche la console de debug. debugConsoleOverlay a un
    // z-index inférieur (99999999) à qrCodeOverlay (999999999) : sans masquer
    // cette modale au préalable, la console resterait invisible derrière.
    // N'affecte aucun autre déclencheur existant de la console
    // (cityCodeDisplay.../qrFlagImage... restent inchangés).
    var _qcHeader = document.getElementById('qrCodeHeader');
    if (_qcHeader) {
        _qcHeader.style.cursor = 'pointer';
        _qcHeader.addEventListener('click', function (e) {
            e.stopPropagation();
            overlay.classList.add('qcHidden');
            if (typeof window._toggleDebugConsole === 'function') window._toggleDebugConsole();
        });
    }

    function openQrCodeModal() {
        var nameEl = document.getElementById('qrCodeMosqueName');
        if (nameEl) nameEl.textContent = (typeof MOSQUE_CONFIG !== 'undefined' && MOSQUE_CONFIG.MOSQUE_NAME) || '';
        overlay.classList.remove('qcHidden');
        if (typeof window._pushBack === 'function') window._pushBack();
        _L('QRMODAL', 'FIRE', { action: 'open' });
    }

    function closeQrCodeModal() {
        overlay.classList.add('qcHidden');
        if (typeof window._popBack === 'function') window._popBack();
        _L('QRMODAL', 'FIRE', { action: 'close' });
    }

    window.openQrCodeModal  = openQrCodeModal;
    window.closeQrCodeModal = closeQrCodeModal;

    // -- #psFlagImageVertical : SEUL déclencheur icône restant. Simple clic/tap
    //    = ouvre la modale, sans condition d'orientation (le simple clic ne doit
    //    JAMAIS déclencher de rafraîchissement). Appui long (maintien >= 600 ms)
    //    = restartApplicationFunction(). Distinction gérée nous-mêmes (timer
    //    démarré au press, annulé si relâché avant le délai ou si le doigt/la
    //    souris bouge) plutôt que via un évènement natif — ainsi le même code
    //    fonctionne identiquement au doigt et à la souris.
    //    Ne touche pas #psFlagImageHorizontal.
    function _bindPsFlagVerticalOverride() {
        var el = document.getElementById('psFlagImageVertical');
        if (!el) return false;

        // CRITIQUE : index.html définit onclick="restartApplicationFunction();" en
        // attribut inline. On le neutralise : le clic simple ne doit jamais
        // rafraîchir, seul l'appui long doit le faire desormais.
        el.onclick = null;

        var LONG_PRESS_DELAY = 600;
        var _psPressTimer = null;
        var _psLongPressFired = false;

        function _psSingleTap() { openQrCodeModal(); }
        function _psLongPress() {
            _psLongPressFired = true;
            if (typeof restartApplicationFunction === 'function') restartApplicationFunction();
        }
        function _psStartPress() {
            _psLongPressFired = false;
            if (_psPressTimer) clearTimeout(_psPressTimer);
            _psPressTimer = setTimeout(_psLongPress, LONG_PRESS_DELAY);
        }
        function _psEndPress(triggerTapIfShort) {
            if (_psPressTimer) { clearTimeout(_psPressTimer); _psPressTimer = null; }
            if (triggerTapIfShort && !_psLongPressFired) _psSingleTap();
        }
        function _psCancelPress() {
            if (_psPressTimer) { clearTimeout(_psPressTimer); _psPressTimer = null; }
        }

        // Touch (Android / GeckoView) : preventDefault() bloque le click
        // synthétique que le navigateur émettrait sinon en plus.
        el.addEventListener('touchstart', function (e) {
            e.preventDefault();
            _psStartPress();
        }, { passive: false });
        el.addEventListener('touchend', function (e) {
            e.preventDefault();
            _psEndPress(true);
        }, { passive: false });
        el.addEventListener('touchmove', function () { _psCancelPress(); }, { passive: true });
        el.addEventListener('touchcancel', function () { _psCancelPress(); });

        // Souris (desktop) : même logique press/release que le tactile.
        el.addEventListener('mousedown', _psStartPress);
        el.addEventListener('mouseup', function () { _psEndPress(true); });
        el.addEventListener('mouseleave', function () { _psCancelPress(); });
        el.addEventListener('contextmenu', function (e) { e.preventDefault(); });

        return true;
    }
    if (!_bindPsFlagVerticalOverride()) {
        document.addEventListener('DOMContentLoaded', function () {
            if (!_bindPsFlagVerticalOverride()) setTimeout(_bindPsFlagVerticalOverride, 300);
        });
    }

    // -- Masque l'ancienne case #qrFlagCheckbox (+ sa ligne) : remplacée
    //    fonctionnellement par le lien de menu #ucQrCodeMenuLink (injecté plus
    //    bas, après la section "onboarding tour"). index.html n'étant pas
    //    modifiable, on masque la ligne existante plutôt que de la supprimer.
    function _hideOldQrCheckboxRow() {
        var cb = document.getElementById('qrFlagCheckbox');
        if (!cb) return false;
        var row = cb.closest ? cb.closest('div') : cb.parentElement;
        if (row) row.style.display = 'none';
        return true;
    }
    if (!_hideOldQrCheckboxRow()) {
        document.addEventListener('DOMContentLoaded', function () {
            if (!_hideOldQrCheckboxRow()) setTimeout(_hideOldQrCheckboxRow, 300);
        });
    }

    _L('CUSTOM', 'INIT', { item: 'qrCodeModal' });

})();
