// Miroir "QP" (onglet ⚙ الإعدادات de quranPlayerModal, cf. injectQuranPlayerModal) :
// mêmes fonctions toggle/edit globales des deux côtés (elles ne dépendent pas
// de l'élément qui a déclenché l'appel), donc il suffit de recopier l'état
// affiché (checked / innerHTML) vers l'ID suffixé "QP" quand il existe dans le
// DOM. Pas de collision possible : les deux jeux d'IDs sont distincts.
function _qpSyncMirrorEl(origId) {
    const orig = document.getElementById(origId);
    const mir  = document.getElementById(origId + 'QP');
    if (!orig || !mir) return;
    if (orig.tagName === 'INPUT' && orig.type === 'checkbox') {
        mir.checked = orig.checked;
    } else {
        mir.innerHTML = orig.innerHTML;
    }
}

