// Plus de plancher à 10s ni de repli sur une valeur par défaut : 0 est une
// valeur valide et signifiante (= désactivé). Saisie et affichage en
// minutes ; stockage en secondes en interne (JS_CUSTOM[cfg.setting]),
// inchangé pour ne pas toucher aux comparaisons de seuils existantes
// (_getAutoStartDelaySeconds toujours utilisée par le countdown).
function editStartQuranBeforeAzanDelayFunction(prayerKey) {
    if (!isInputDialogOpen) {
        _sqaEditPrayerKey = prayerKey || _sqaEditPrayerKey || 'FAJR';
        const lang = _quranAutoStartLang();
        const nameMap = L_QURAN_PRAYER_NAMES[_sqaEditPrayerKey];
        const name = (nameMap && nameMap[lang]) || _sqaEditPrayerKey;
        const titleFn = L_QURAN_EDIT_DIALOG[lang] || L_QURAN_EDIT_DIALOG.EN;
        inputDialogValue  = '';
        isInputDialogOpen = false;
        openInputDialogFunction(titleFn(name), _getAutoStartDelayMinutes(_sqaEditPrayerKey), 'editStartQuranBeforeAzanDelayFunction()', true);
        return;
    }

    const cfg = _quranAutoStartConfig[_sqaEditPrayerKey] || _quranAutoStartConfig.FAJR;
    let minutes = parseInt(inputDialogValue, 10);
    if (isNaN(minutes) || minutes < 0) minutes = 0;

    JS_CUSTOM[cfg.setting] = minutes * 60;
    saveCustomSettingsFunction();
    refreshStartQuranBeforeAzanButtonsUI();
    _sqaFired = false;
}

