            (item.delaySetting    ? "<span class='clickableWhiteClass' id='lightCfgDelayBtn_"     + item.key + "' title='" + _delayHelp  + "' data-help='" + _delayHelp  + "' style='white-space:nowrap;' onclick=\"editLightProgrammingDelayFunction('"     + item.key + "');\"></span>" : "") +
            (item.jomaDelaySetting? "<span class='clickableWhiteClass' id='lightCfgJomaDelayBtn_" + item.key + "' title='" + _jomaHelp   + "' data-help='" + _jomaHelp   + "' style='white-space:nowrap;' onclick=\"editLightProgrammingJomaDelayFunction('" + item.key + "');\"></span>" : "") +
            (item.extraSetting    ? "<span class='clickableWhiteClass' id='lightCfgExtraBtn_"     + item.key + "' title='" + _extraHelp  + "' data-help='" + _extraHelp  + "' style='white-space:nowrap;' onclick=\"editLightProgrammingExtraFunction('"     + item.key + "');\"></span>" : "") +
            "<span class='clickableWhiteClass' id='lightCfgBtn_" + item.key + "' title='" + _urlHelp + "' data-help='" + _urlHelp + "' style='flex:1;min-width:18em;text-align:left;direction:ltr;' onclick=\"editLightProgrammingUrlFunction('" + item.key + "');\"></span>" +
            "<span style='cursor:pointer;font-size:0.8em;padding:1px 7px;border:1px solid #446;border-radius:4px;color:#8cf;user-select:none;flex-shrink:0;' title='اختبار الرابط' onclick=\"ucTestLightBtnFunction('" + item.key + "');\">▶</span>";
        container.appendChild(row);

