/* ── Tooltip tactile (Android) pour les boutons data-help ─────────────────
   • Desktop  : le `title` natif suffit (hover souris).
   • Android  : pas de hover → long-press 500 ms affiche un tooltip flottant.
   Le même tooltip sert tous les conteneurs qui ont des éléments [data-help]. */
function _initLightTooltips() {
    /* Créer (une seule fois) le div tooltip flottant */
    var tip = document.getElementById('_ucLightTip');
    if (!tip) {
        tip = document.createElement('div');
        tip.id = '_ucLightTip';
        tip.style.cssText =
            'position:fixed;background:rgba(20,20,20,.93);color:#eee;' +
            'padding:7px 12px;border-radius:8px;font-size:.82em;' +
            'direction:rtl;text-align:center;z-index:99999;' +
            'pointer-events:none;max-width:80vw;display:none;' +
            'box-shadow:0 2px 8px rgba(0,0,0,.5);';
        document.body.appendChild(tip);
    }

    var _tipTimer = null;

    function _showTip(text, touchEvt) {
        clearTimeout(_tipTimer);
        _tipTimer = setTimeout(function () {
            tip.textContent = text;
            tip.style.display = 'block';
            var touch = touchEvt.touches ? touchEvt.touches[0] : touchEvt;
            var x = Math.max(8, Math.min(touch.clientX - 60, window.innerWidth - 240));
            var y = touch.clientY - 70;
            if (y < 8) y = touch.clientY + 36;
            tip.style.left = x + 'px';
            tip.style.top  = y + 'px';
        }, 500);
    }

    function _hideTip() {
        clearTimeout(_tipTimer);
        tip.style.display = 'none';
    }

    /* Brancher sur le conteneur principal (délégation d'événements) */
    var container = document.getElementById('lightProgrammingContentContainer');
    if (!container) return;

    /* Supprimer les anciens listeners en clonant le nœud */
    var fresh = container.cloneNode(false);
    while (container.firstChild) fresh.appendChild(container.firstChild);
    container.parentNode.replaceChild(fresh, container);
    container = fresh;

    container.addEventListener('touchstart', function (evt) {
        var el = evt.target.closest ? evt.target.closest('[data-help]')
                                    : (evt.target.getAttribute('data-help') ? evt.target : null);
        if (el) _showTip(el.getAttribute('data-help'), evt);
    }, { passive: true });

    container.addEventListener('touchend',  _hideTip, { passive: true });
    container.addEventListener('touchmove', _hideTip, { passive: true });
}

function refreshLightProgrammingUI() {
    _lightProgramConfig.forEach(function(item) {
        const cb            = document.getElementById('lightCfgCb_' + item.key);
        const btn           = document.getElementById('lightCfgBtn_' + item.key);
        const delayBtn      = document.getElementById('lightCfgDelayBtn_' + item.key);
        const jomaDelayBtn  = document.getElementById('lightCfgJomaDelayBtn_' + item.key);
        const extraBtn      = document.getElementById('lightCfgExtraBtn_' + item.key);
        if (cb)            cb.checked            = (JS_CUSTOM[item.enabledSetting] == 1);
        if (btn)           btn.innerHTML         = '🔗 ' + (JS_CUSTOM[item.urlSetting] || '');
        if (delayBtn)      delayBtn.innerHTML      = '⏱ ' + ((parseInt(JS_CUSTOM[item.delaySetting], 10) || item.delayDefault || 0) + 's');
        if (jomaDelayBtn)  jomaDelayBtn.innerHTML  = '🕌 ' + ((parseInt(JS_CUSTOM[item.jomaDelaySetting], 10) || item.jomaDelayDefault || 0) + 's');
        if (extraBtn)      extraBtn.innerHTML      = '⌛ ' + ((parseInt(JS_CUSTOM[item.extraSetting], 10) || item.extraDefault || 0) + 's');

        // Filtre prières
        if (item.prayersMaskSetting) {
            const prayerRow = document.getElementById('lightCfgPrayerMask_' + item.key);
            if (prayerRow) {
                prayerRow.innerHTML = _buildLightPrayerMaskTableHtml(item);
            }
        }

        // Sélecteur de déclencheur — ré-affiche le tableau (case "✕" exclusive)
        if (item.triggerSetting) {
            var trig = JS_CUSTOM[item.triggerSetting] || item.trigger;
            var trigTableHost = document.getElementById('lightCfgTrigRow_' + item.key);
            if (trigTableHost) {
                trigTableHost.innerHTML = "<div style='color:#aaa;font-size:.85em;padding-bottom:2px;'>موعد التشغيل :</div>"
                    + _buildLightTriggerTableHtml(item);
            }
            // Mettre à jour le libellé du bouton délai selon le déclencheur actif
            var dBtn = document.getElementById('lightCfgDelayBtn_' + item.key);
            if (dBtn) {
                var _dHelp = (trig === 'beforeAzan')    ? 'تشغيل المحراب قبل الأذان بـ (ثواني)'
                           : (trig === 'beforeIqama')   ? 'تشغيل المحراب قبل الإقامة بـ (ثواني)'
                           : 'تشغيل المحراب بعد إغلاق نافذة الأذان بـ (ثواني)';
                dBtn.title = _dHelp;
                dBtn.setAttribute('data-help', _dHelp);
            }
        }
    });
}

function toggleLightPrayerMaskFunction(itemKey, prayerIdx) {
    const item = _lightProgramConfig.find(function(x) { return x.key === itemKey; });
    if (!item || !item.prayersMaskSetting) return;
    const chars = String(JS_CUSTOM[item.prayersMaskSetting] || '11111').split('');
    while (chars.length < 5) chars.push('1');
    chars[prayerIdx] = (chars[prayerIdx] === '1') ? '0' : '1';
    JS_CUSTOM[item.prayersMaskSetting] = chars.join('');
    saveCustomSettingsFunction();
    // Pas besoin de refreshLightProgrammingUI complet — juste re-render la ligne prières
    refreshLightProgrammingUI();
}

function toggleLightProgrammingItemFunction(itemKey) {
    const item = _lightProgramConfig.find(function(x) { return x.key === itemKey; });
    if (!item) return;
    JS_CUSTOM[item.enabledSetting] = +(JS_CUSTOM[item.enabledSetting] != 1);
    saveCustomSettingsFunction();
    refreshLightProgrammingUI();
}

function toggleLightItemTriggerFunction(itemKey, value) {
    const item = _lightProgramConfig.find(function(x) { return x.key === itemKey; });
    if (!item || !item.triggerSetting) return;
    // Radio behavior : l'autre case se décoche automatiquement via refreshLightProgrammingUI
    JS_CUSTOM[item.triggerSetting] = value;
    saveCustomSettingsFunction();
    refreshLightProgrammingUI();
}

function editLightProgrammingUrlFunction(itemKey) {
    if (!isInputDialogOpen) {
        const item = _lightProgramConfig.find(function(x) { return x.key === itemKey; });
        if (!item) return;
        _lightEditKey = itemKey;
        inputDialogValue = '';
        openInputDialogFunction(_lightT(item, 'title'), JS_CUSTOM[item.urlSetting] || '', "editLightProgrammingUrlFunction()", true);
        return;
    }

    const currentItem = _lightProgramConfig.find(function(x) { return x.key === _lightEditKey; });
    if (!currentItem) return;

    const val = String(inputDialogValue || '').trim();
    JS_CUSTOM[currentItem.urlSetting] = val;
    saveCustomSettingsFunction();
    refreshLightProgrammingUI();
}

function editLightProgrammingDelayFunction(itemKey) {
    if (!isInputDialogOpen) {
        const item = _lightProgramConfig.find(function(x) { return x.key === itemKey; });
        if (!item || !item.delaySetting) return;
        _lightDelayEditKey = itemKey;
        inputDialogValue = '';
        openInputDialogFunction(_lightT(item, 'delayTitle'), JS_CUSTOM[item.delaySetting] || item.delayDefault || 0, "editLightProgrammingDelayFunction()", true);
        return;
    }

    const currentItem = _lightProgramConfig.find(function(x) { return x.key === _lightDelayEditKey; });
    if (!currentItem || !currentItem.delaySetting) return;

    let val = parseInt(inputDialogValue, 10);
    if (isNaN(val) || val < 0) val = currentItem.delayDefault || 0;
    JS_CUSTOM[currentItem.delaySetting] = val;
    saveCustomSettingsFunction();
    refreshLightProgrammingUI();
}

function editLightProgrammingJomaDelayFunction(itemKey) {
    if (!isInputDialogOpen) {
        const item = _lightProgramConfig.find(function(x) { return x.key === itemKey; });
        if (!item || !item.jomaDelaySetting) return;
        _lightJomaDelayEditKey = itemKey;
        inputDialogValue = '';
        openInputDialogFunction(_lightT(item, 'jomaDelayTitle'), JS_CUSTOM[item.jomaDelaySetting] || item.jomaDelayDefault || 0, "editLightProgrammingJomaDelayFunction()", true);
        return;
    }

    const currentItem = _lightProgramConfig.find(function(x) { return x.key === _lightJomaDelayEditKey; });
    if (!currentItem || !currentItem.jomaDelaySetting) return;

    let val = parseInt(inputDialogValue, 10);
    if (isNaN(val) || val < 0) val = currentItem.jomaDelayDefault || 0;
    JS_CUSTOM[currentItem.jomaDelaySetting] = val;
    saveCustomSettingsFunction();
    refreshLightProgrammingUI();
}

function editLightProgrammingExtraFunction(itemKey) {
    if (!isInputDialogOpen) {
        const item = _lightProgramConfig.find(function(x) { return x.key === itemKey; });
        if (!item || !item.extraSetting) return;
        _lightExtraEditKey = itemKey;
        inputDialogValue = '';
        openInputDialogFunction(item.extraTitle || 'Duration (s)', JS_CUSTOM[item.extraSetting] || item.extraDefault || 0, "editLightProgrammingExtraFunction()", true);
        return;
    }

    const currentItem = _lightProgramConfig.find(function(x) { return x.key === _lightExtraEditKey; });
    if (!currentItem || !currentItem.extraSetting) return;

    let val = parseInt(inputDialogValue, 10);
    if (isNaN(val) || val < 0) val = currentItem.extraDefault || 0;
    JS_CUSTOM[currentItem.extraSetting] = val;
    saveCustomSettingsFunction();
    refreshLightProgrammingUI();
}

function toggleShowSpeakerIconFunction() {
    JS_CUSTOM.ucShowSpeakerIcon = +(!JS_CUSTOM.ucShowSpeakerIcon);
    saveCustomSettingsFunction();
    applyCustomIconsVisibility();
}

function toggleShowQuranIconFunction() {
    JS_CUSTOM.ucShowQuranIcon = +(!JS_CUSTOM.ucShowQuranIcon);
    saveCustomSettingsFunction();
    applyCustomIconsVisibility();
}

// ── SERVEUR HTTP CORAN ────────────────────────────────────────────────────

// Construit les lignes récitateurs dans un conteneur donné ; idSuffix distingue
// les IDs du miroir "QP" (onglet ⚙ الإعدادات de quranPlayerModal) de ceux de
// l'original (⚙ برمجة تلاوة القرآن) — mêmes handlers globaux des deux côtés
// (toggleReciterFunction/editReciterNameFunction/cycleReciterDirFunction ne
// dépendent que de l'index i, pas de l'élément qui a déclenché l'appel).
function _qpBuildRecitersInto(containerId, idSuffix) {
    const container = document.getElementById(containerId);
    if (!container) return;
    container.innerHTML = '';
    // Slots historiques uniquement : les récitateurs "device" (USB/téléchargés)
    // n'apparaissent pas ici (ils sont gérés dans la section Gestionnaire de
    // récitateurs — pas de dir/format éditable manuellement pour eux).
    JS_CUSTOM.ucReciters.slice(0, UC_RECITERS_STATIC_COUNT).forEach(function(reciter, i) {
        const row = document.createElement('div');
        row.style.cssText = 'display:flex;align-items:center;gap:6px;margin:3px 0;';
        row.innerHTML =
            "<input type='checkbox' id='reciter" + i + "EnabledCheckbox" + idSuffix + "' onchange='toggleReciterFunction(" + i + ");'>" +
            " <span class='clickableWhiteClass' id='reciter" + i + "NameButton" + idSuffix + "'" +
            "  style='min-width:7em;text-align:right;' onclick='editReciterNameFunction(" + i + ");'></span>" +
            " <span class='clickableWhiteClass' id='reciter" + i + "DirButton" + idSuffix + "'" +
            "  style='min-width:2.5em;text-align:center;' onclick='cycleReciterDirFunction(" + i + ");'></span>";
        container.appendChild(row);
    });
}

function initQuranRecitersUI() {
    _qpBuildRecitersInto('quranRecitersContainer', '');
    _qpBuildRecitersInto('quranRecitersContainerQP', 'QP');
}

// "Android box" = une mosquée est sélectionnée (config multi-mosquée
// appliquée, cf. _installMosqueSelector()) ; "Android mobile" = aucune
// mosquée sélectionnée (état MOSQUE_CONFIG._NO_MOSQUE_SELECTED).
function _isAndroidBoxMode() {
    return !!(window.MOSQUE_CONFIG && !window.MOSQUE_CONFIG._NO_MOSQUE_SELECTED);
}

function refreshQuranServerUI() {
    const serverCb  = document.getElementById('quranServerEnabledCheckbox');
    const urlBtn    = document.getElementById('quranServerUrlButton');
    const recitersC = document.getElementById('quranRecitersContainer');
    if (serverCb) serverCb.checked = (JS_CUSTOM.ucQuranServerEnabled == 1);
    if (urlBtn)   urlBtn.innerHTML  = JS_CUSTOM.ucQuranServerUrl || 'http://127.0.0.1';
    _qpSyncMirrorEl('quranServerEnabledCheckbox');
    _qpSyncMirrorEl('quranServerUrlButton');
    if (recitersC) {
        if (!_isAndroidBoxMode()) {
            // Android mobile (aucune mosquée sélectionnée) : bloc entièrement
            // masqué — seule reste visible la section "إدارة القرّاء" (USB/cloud).
            recitersC.style.display = 'none';
        } else {
            // Android box (mosquée sélectionnée) : comportement existant —
            // serveur décoché → masquer les 10 lignes récitateurs standard
            // (section réduite à la seule ligne de la checkbox serveur).
            // Serveur coché → les ré-afficher dans leur état courant.
            recitersC.style.display = (JS_CUSTOM.ucQuranServerEnabled == 1) ? '' : 'none';
        }
    }
    const recitersCQP = document.getElementById('quranRecitersContainerQP');
    if (recitersCQP) recitersCQP.style.display = recitersC ? recitersC.style.display : '';

    ['', 'QP'].forEach(function(idSuffix) {
        JS_CUSTOM.ucReciters.slice(0, UC_RECITERS_STATIC_COUNT).forEach(function(reciter, i) {
            const cb      = document.getElementById('reciter' + i + 'EnabledCheckbox' + idSuffix);
            const nameBtn = document.getElementById('reciter' + i + 'NameButton' + idSuffix);
            const dirBtn  = document.getElementById('reciter' + i + 'DirButton' + idSuffix);
            if (cb)      cb.checked       = (reciter.enabled == 1);
            if (nameBtn) nameBtn.innerHTML = reciter.name || JS_CUSTOM_DEFAULTS.ucReciters[i].name;
            if (dirBtn)  dirBtn.innerHTML  = reciter.dir;
        });
    });

    // Règle 1 : mettre à jour le titre du player si le modal est ouvert
    _refreshQPTitle();
    // Règle 2 : mettre à jour la liste des récitateurs si le modal est ouvert
    if (document.getElementById('quranPlayerOverlay') &&
        !document.getElementById('quranPlayerOverlay').classList.contains('qpHidden')) {
        _buildQPReciters();
    }
}

// ── Règle 1 : titre du player fixe — l'état du serveur est signalé
// uniquement par la couleur de qpServerStatusDot (cf. _refreshQPServerStatus),
// plus par un texte alarmant dans le titre lui-même. ──────────────────────
function _refreshQPTitle() {
    var titleEl = document.getElementById('quranPlayerTitle');
    if (titleEl) {
        titleEl.style.color = '';
        titleEl.textContent = 'استماع وقراءة القرآن';
    }
    _refreshQPServerStatus();
}

// ── Règle 3 : vider le cache audio quand le serveur est désactivé ─────────
function _clearQPCache() {
    try {
        localStorage.removeItem(_QP_STORAGE_KEY);
        localStorage.removeItem(_QP_STORAGE_SRC_KEY);
        localStorage.removeItem(_QP_STORAGE_TIME_KEY);
    } catch(e) {}
    _qpReciterIdx = -1;
    _qpSurahNum   = 0;
    _qpRestoring  = false;
    const audio = document.getElementById('quranAudioPlayer');
    if (audio) { audio.pause(); audio.src = ''; audio.load(); }
    _L('QP','STOP',{action:'cache_cleared',reason:'server_disabled'});
}

function toggleQuranServerEnabledFunction() {
    var wasEnabled = (JS_CUSTOM.ucQuranServerEnabled == 1);
    JS_CUSTOM.ucQuranServerEnabled = +(!wasEnabled);
    saveCustomSettingsFunction();
    // Règle 3 : vider le cache si on vient de désactiver le serveur
    if (wasEnabled) {
        _clearQPCache();
        _qpStopProbeLoop();          // stopper la boucle de re-probe si active
        _qpServerState = 'unknown';  // réinitialiser l'état pour le prochain allumage
    } else {
        // Vient d'être activé (ex: juste après un RESET) : le lecteur n'a
        // jamais été chargé au boot (serveur alors désactivé) -- le charger
        // maintenant sinon il reste grisé tant que l'utilisateur ne tape pas
        // lui-même un récitateur/une sourate (cf. _qpAutoLoadIfNeeded).
        _qpAutoLoadIfNeeded();
    }
    refreshQuranServerUI();
}

function editQuranServerUrlFunction() {
    if (!isInputDialogOpen) {
        inputDialogValue  = "";
        isInputDialogOpen = false;
        openInputDialogFunction(_dlgT('quranServerUrl'), JS_CUSTOM.ucQuranServerUrl, 'editQuranServerUrlFunction()', true);
        return;
    }
    const val = inputDialogValue.trim();
    if (val) JS_CUSTOM.ucQuranServerUrl = val;
    saveCustomSettingsFunction();
    refreshQuranServerUI();
}

function toggleReciterFunction(i) {
    var wasEnabled = (JS_CUSTOM.ucReciters[i].enabled == 1);
    JS_CUSTOM.ucReciters[i].enabled = +(!wasEnabled);
    saveCustomSettingsFunction();
    // Vient d'être activé : mêmes raisons que toggleQuranServerEnabledFunction
    // -- si le lecteur n'a jamais chargé (ex: RESET, aucun récitateur actif au
    // boot), le charger maintenant plutôt que de le laisser grisé.
    if (!wasEnabled) _qpAutoLoadIfNeeded();
    refreshQuranServerUI();
}

function editReciterNameFunction(i) {
    if (!isInputDialogOpen) {
        inputDialogValue  = "";
        isInputDialogOpen = false;
        openInputDialogFunction(_dlgT('reciterName') + ' ' + (i + 1), JS_CUSTOM.ucReciters[i].name, 'editReciterNameFunction(' + i + ')', true);
        return;
    }
    JS_CUSTOM.ucReciters[i].name = inputDialogValue.trim();
    saveCustomSettingsFunction();
    refreshQuranServerUI();
}

function cycleReciterDirFunction(i) {
    const dirs  = ['C1','C2','C3','C4','C5','C6','C7','C8','C9','C10'];
    const cur   = JS_CUSTOM.ucReciters[i].dir;
    const idx   = dirs.indexOf(cur);
    JS_CUSTOM.ucReciters[i].dir = dirs[(idx + 1) % dirs.length];
    saveCustomSettingsFunction();
    refreshQuranServerUI();
}

// NB : le bouton manuel de format par récitateur (mp3/ogg) a été retiré de l'UI —
// _buildQPUrl() essaie maintenant .ogg puis .mp3 automatiquement pour chaque
// sourate (voir le handler 'error' dans injectQuranPlayerModal). Le champ
// `format` reste dans JS_CUSTOM.ucReciters pour compat des anciennes configs
// stockées mais n'est plus lu ni modifiable depuis l'UI.

// ── GESTIONNAIRE DE RÉCITATEURS (USB / Cloud) ──────────────────────────────
// Récitateurs "device" : importés via SAF (clé USB) ou téléchargés depuis un
// catalogue en ligne (catalog.json — voir RECITERS_DEPLOYMENT.md). Toutes les
// interactions avec le natif Android sont "pull" (polling), pas de callback
// JS poussé depuis Kotlin — plus simple et robuste (pas de canal de retour
// à maintenir). window.AndroidMobile est absent hors APK (navigateur classique) :
// chaque appel est gardé par un typeof/truthiness check.
// (var UC_RECITER_CATALOG_URL / _rmImportPollTimer / _rmDownloadPollTimers /
//  _rmCatalog sont déclarées plus haut, avant injectTechOptionsUI — voir
//  commentaire à cet endroit.)

function initReciterManagerUI() {
    // Auto-correction : si une ancienne sauvegarde localStorage contient ''
    // (avant l'ajout du défaut) OU l'ancienne URL raw.githubusercontent.com
    // (défaut temporaire remplacé depuis par la version github.io), on la
    // remplace ici une fois pour toutes — sinon Object.assign(JS_CUSTOM_DEFAULTS,
    // _storedCustom) garde la valeur obsolète à vie.
    if (!JS_CUSTOM.ucReciterCatalogUrl ||
        JS_CUSTOM.ucReciterCatalogUrl === 'https://raw.githubusercontent.com/TAOUKITPRAYER/tawkit-reciters/main/catalog.json') {
        JS_CUSTOM.ucReciterCatalogUrl = UC_RECITER_CATALOG_DEFAULT_URL;
        saveCustomSettingsFunction();
    }
    UC_RECITER_CATALOG_URL = JS_CUSTOM.ucReciterCatalogUrl || UC_RECITER_CATALOG_DEFAULT_URL;
    var btn = document.getElementById('reciterCatalogUrlButton');
    if (btn) btn.innerHTML = UC_RECITER_CATALOG_URL || '(غير مضبوط)';
    _rmRenderInstalled();
    _rmRenderCatalog();
}

function editReciterCatalogUrlFunction() {
    if (!isInputDialogOpen) {
        inputDialogValue  = "";
        isInputDialogOpen = false;
        openInputDialogFunction(_dlgT('reciterCatalogUrl'), JS_CUSTOM.ucReciterCatalogUrl || UC_RECITER_CATALOG_DEFAULT_URL, 'editReciterCatalogUrlFunction()', true);
        return;
    }
    const val = inputDialogValue.trim();
    JS_CUSTOM.ucReciterCatalogUrl = val;
    saveCustomSettingsFunction();
    UC_RECITER_CATALOG_URL = val;
    const btn = document.getElementById('reciterCatalogUrlButton');
    if (btn) btn.innerHTML = val || '(غير مضبوط)';
}

// ── Récitateurs déjà installés localement (USB ou téléchargés) ────────────
// Rendue dans les deux conteneurs (original + miroir "QP" de l'onglet
// ⚙ الإعدادات de quranPlayerModal) — pas d'ID par ligne ici (le bouton حذف
// n'appelle que _rmRemoveReciter(dir), sans dépendre de l'élément déclencheur),
// donc une simple reconstruction des deux suffit, aucune collision possible.
function _rmRenderInstalled() {
    ['rmInstalledContainer', 'rmInstalledContainerQP'].forEach(function(containerId) {
        const container = document.getElementById(containerId);
        if (!container) return;
        const installed = JS_CUSTOM.ucReciters.filter(function(r) { return r.source === 'device'; });
        if (installed.length === 0) {
            container.innerHTML = "<div style='color:#888;font-size:.85em;'>لا يوجد قارئ محلي بعد</div>";
            return;
        }
        container.innerHTML = '';
        installed.forEach(function(r) {
            const row = document.createElement('div');
            row.style.cssText = 'display:flex;align-items:center;gap:6px;margin:2px 0;';
            row.innerHTML =
                "<span style='flex:1;'>" + r.name + " <span style='color:#888;font-size:.8em;'>(" + r.dir + ")</span></span>" +
                "<span class='clickableWhiteClass' onclick=\"_rmRemoveReciter('" + r.dir + "')\">حذف</span>";
            container.appendChild(row);
        });
    });
}

function _rmRemoveReciter(id) {
    if (!window.AndroidMobile || typeof window.AndroidMobile.removeReciter !== 'function') return;
    _L('RM','REMOVE_CLICK',{id:id});
    window.AndroidMobile.removeReciter(id);
    _syncDeviceReciters('remove_reciter');
    refreshQuranServerUI();
    _rmRenderInstalled();
    _rmRenderCatalog();
}

// ── Import depuis clé USB (SAF) ────────────────────────────────────────────
function _rmStartUsbImport() {
    const statusEl = document.getElementById('rmImportStatus');
    if (!window.AndroidMobile || typeof window.AndroidMobile.requestUsbImport !== 'function') {
        if (statusEl) statusEl.textContent = 'غير متاح خارج تطبيق أندرويد';
        _qpSyncMirrorEl('rmImportStatus');
        return;
    }
    window.AndroidMobile.requestUsbImport();
    if (statusEl) statusEl.textContent = 'في انتظار اختيار المجلد...';
    _qpSyncMirrorEl('rmImportStatus');
    if (_rmImportPollTimer) clearInterval(_rmImportPollTimer);
    _rmImportPollTimer = setInterval(_rmPollImportStatus, 800);
}

function _rmPollImportStatus() {
    if (!window.AndroidMobile || typeof window.AndroidMobile.getImportStatus !== 'function') return;
    var st;
    try { st = JSON.parse(window.AndroidMobile.getImportStatus() || '{}'); } catch(e) { return; }
    const el = document.getElementById('rmImportStatus');
    if (st.status === 'copying') {
        if (el) el.textContent = 'نسخ: ' + (st.message || '...');
        _qpSyncMirrorEl('rmImportStatus');
    } else if (st.status === 'done') {
        if (el) el.textContent = '✓ ' + (st.message || 'تم الاستيراد');
        _qpSyncMirrorEl('rmImportStatus');
        clearInterval(_rmImportPollTimer); _rmImportPollTimer = null;
        _L('RM','USB_IMPORT_DONE',{data:JSON.stringify(st)});
        _syncDeviceReciters('usb_import_done');
        refreshQuranServerUI();
        _rmRenderInstalled();
        _rmRenderCatalog();
    } else if (st.status === 'error') {
        if (el) el.textContent = '⚠ ' + (st.message || 'خطأ في الاستيراد');
        _qpSyncMirrorEl('rmImportStatus');
        _L('RM','USB_IMPORT_ERROR',{data:JSON.stringify(st)});
        clearInterval(_rmImportPollTimer); _rmImportPollTimer = null;
    }
}

// ── Catalogue en ligne (téléchargement cloud) ──────────────────────────────
// Format attendu du JSON distant : {"reciters":[{"id":"...","name":"...","url":"https://.../xxx.zip"}]}
// Conteneurs du catalogue (original + miroir "QP") existant réellement dans le DOM.
function _rmCatalogContainerIds() {
    return ['rmCatalogContainer', 'rmCatalogContainerQP'].filter(function(id) {
        return !!document.getElementById(id);
    });
}

function _rmLoadCatalog() {
    const containerIds = _rmCatalogContainerIds();
    if (!UC_RECITER_CATALOG_URL) {
        containerIds.forEach(function(id) {
            document.getElementById(id).innerHTML = "<div style='color:#888;font-size:.85em;'>لم يُضبط رابط الكتالوج أعلاه</div>";
        });
        return;
    }
    containerIds.forEach(function(id) {
        document.getElementById(id).innerHTML = "<div style='color:#888;font-size:.85em;'>تحميل...</div>";
    });
    fetch(UC_RECITER_CATALOG_URL, {cache:'no-store'})
        .then(function(res) { return res.json(); })
        .then(function(json) {
            _rmCatalog = Array.isArray(json.reciters) ? json.reciters : [];
            _rmRenderCatalog();
        })
        .catch(function(e) {
            containerIds.forEach(function(id) {
                document.getElementById(id).innerHTML = "<div style='color:#ff6b6b;font-size:.85em;'>تعذّر تحميل الكتالوج: " + e.message + "</div>";
            });
        });
}

// Construit le catalogue dans les deux conteneurs (original + miroir "QP") avec
// des IDs par ligne suffixés par conteneur (idSuffix) pour éviter toute
// collision — _rmRenderDownloadControls/_rmPollDownload/_rmCancelDownload
// resynchronisent ensuite les deux jeux d'IDs à chaque changement d'état via
// _qpSyncMirrorEl.
function _rmRenderCatalogInto(containerId, idSuffix) {
    const container = document.getElementById(containerId);
    if (!container) return;
    if (_rmCatalog.length === 0) {
        container.innerHTML = "<div style='color:#888;font-size:.85em;'>اضغط «تحديث قائمة التحميل»</div>";
        return;
    }
    const installedIds = JS_CUSTOM.ucReciters.filter(function(r){ return r.source === 'device'; }).map(function(r){ return r.dir; });
    container.innerHTML = '';
    _rmCatalog.forEach(function(item) {
        const id = item.id;
        const already = installedIds.indexOf(id) !== -1;
        const row = document.createElement('div');
        row.id = 'rmCatRow_' + id + idSuffix;
        row.className = 'rmCatRow';
        // Nom + contrôles regroupés dans le même bloc "carte" par lecteur
        // (au lieu d'un flex sur toute la largeur du conteneur, qui poussait
        // les boutons loin du nom dès que la modale est large) : le nom et
        // ses boutons restent visuellement collés l'un à l'autre quelle que
        // soit la largeur disponible. إلغاء est masqué par défaut : il n'a de
        // sens que pendant un téléchargement actif (affiché par
        // _rmRenderDownloadControls), ce qui évite qu'il colle en permanence
        // contre تحميل alors qu'il n'y a souvent rien à annuler.
        row.innerHTML =
            "<div class='rmCatName'>" + (item.name || id) + "</div>" +
            (already
                ? "<div class='rmCatControls'><span class='rmCatInstalledBadge'>✓ مثبّت</span></div>"
                : "<div class='rmCatControls'>" +
                      "<span id='rmCatBtn_" + id + idSuffix + "' class='rmCatBtn' onclick=\"_rmDownload('" + id + "')\">تحميل</span>" +
                      "<span id='rmCatCancelBtn_" + id + idSuffix + "' class='rmCatCancelBtn' style='display:none;' onclick=\"_rmCancelDownload('" + id + "')\">✕ إلغاء</span>" +
                      "<span id='rmCatProgress_" + id + idSuffix + "' class='rmCatProgress'></span>" +
                  "</div>");
        container.appendChild(row);
    });
}

function _rmRenderCatalog() {
    _rmRenderCatalogInto('rmCatalogContainer', '');
    _rmRenderCatalogInto('rmCatalogContainerQP', 'QP');
}

function _rmDownload(id) {
    const item = _rmCatalog.find(function(c) { return c.id === id; });
    if (!item || !window.AndroidMobile || typeof window.AndroidMobile.startReciterDownload !== 'function') {
        _L('RM','DL_ABORT',{id:id, reason:(!item ? 'not_in_catalog' : 'no_native_bridge')});
        return;
    }
    delete _rmPollLastStatus[id]; delete _rmPollLastLogTs[id];
    _L('RM','DL_START',{id:id, url:item.url});
    window.AndroidMobile.startReciterDownload(id, item.url);
    _rmSetDownloadActive(id, true);
    _rmRenderDownloadControls(id, 'downloading');
    _rmWatchDownload(id);
}

function _rmPauseDownload(id) {
    _L('RM','DL_PAUSE_CLICK',{id:id});
    if (window.AndroidMobile && typeof window.AndroidMobile.pauseDownload === 'function') window.AndroidMobile.pauseDownload(id);
    _rmSetDownloadActive(id, false);
}

function _rmResumeDownload(id) {
    const item = _rmCatalog.find(function(c) { return c.id === id; });
    if (!item || !window.AndroidMobile || typeof window.AndroidMobile.resumeDownload !== 'function') {
        _L('RM','DL_RESUME_ABORT',{id:id, reason:(!item ? 'not_in_catalog' : 'no_native_bridge')});
        return;
    }
    delete _rmPollLastStatus[id]; delete _rmPollLastLogTs[id];
    _L('RM','DL_RESUME',{id:id, url:item.url});
    window.AndroidMobile.resumeDownload(id, item.url);
    _rmSetDownloadActive(id, true);
    _rmWatchDownload(id);
}

function _rmCancelDownload(id) {
    _L('RM','DL_CANCEL_CLICK',{id:id});
    if (window.AndroidMobile && typeof window.AndroidMobile.cancelDownload === 'function') window.AndroidMobile.cancelDownload(id);
    if (_rmDownloadPollTimers[id]) { clearInterval(_rmDownloadPollTimers[id]); delete _rmDownloadPollTimers[id]; }
    _rmSetDownloadActive(id, false);
    const progEl = document.getElementById('rmCatProgress_' + id);
    if (progEl) progEl.textContent = '';
    _qpSyncMirrorEl('rmCatProgress_' + id);
    _rmRenderCatalog();
}

function _rmRenderDownloadControls(id, status) {
    const btn = document.getElementById('rmCatBtn_' + id);
    if (!btn) return;
    if (status === 'downloading') {
        btn.textContent = 'إيقاف';
        btn.setAttribute('onclick', "_rmPauseDownload('" + id + "')");
    } else if (status === 'paused') {
        btn.textContent = 'استئناف';
        btn.setAttribute('onclick', "_rmResumeDownload('" + id + "')");
    } else if (status === 'error') {
        // Le .part est conserve cote natif : _rmResumeDownload reprend bien depuis
        // l'octet atteint (Range), ce n'est pas un redemarrage a zero. Avant ce
        // correctif, le bouton restait bloque sur "إيقاف" (onclick _rmPauseDownload,
        // qui ne fait plus rien sur un worker deja termine) -> aucune reprise possible.
        btn.textContent = 'إعادة المحاولة';
        btn.setAttribute('onclick', "_rmResumeDownload('" + id + "')");
    }
    // إلغاء : masqué au repos (cf. _rmRenderCatalogInto), révélé dès qu'un
    // téléchargement est réellement suivi (downloading/paused/error — tous
    // les statuts passés à cette fonction correspondent à un état actif).
    const cancelBtn = document.getElementById('rmCatCancelBtn_' + id);
    if (cancelBtn) cancelBtn.style.display = '';

    // Miroir "QP" : même texte + même onclick (setAttribute recopié tel quel,
    // pas juste innerHTML, sinon le miroir garderait l'ancien handler).
    const mirBtn = document.getElementById('rmCatBtn_' + id + 'QP');
    if (mirBtn) {
        mirBtn.textContent = btn.textContent;
        mirBtn.setAttribute('onclick', btn.getAttribute('onclick'));
    }
    const mirCancelBtn = document.getElementById('rmCatCancelBtn_' + id + 'QP');
    if (mirCancelBtn) mirCancelBtn.style.display = '';
}

function _rmWatchDownload(id) {
    if (_rmDownloadPollTimers[id]) clearInterval(_rmDownloadPollTimers[id]);
    _rmDownloadPollTimers[id] = setInterval(function() { _rmPollDownload(id); }, 700);
}

function _rmPollDownload(id) {
    if (!window.AndroidMobile || typeof window.AndroidMobile.getDownloadProgress !== 'function') return;
    var raw = window.AndroidMobile.getDownloadProgress(id) || '{}';
    var p;
    try { p = JSON.parse(raw); } catch(e) {
        _L('RM','DL_POLL_PARSE_ERROR',{id:id, raw:String(raw).slice(0,200)});
        return;
    }
    const progEl     = document.getElementById('rmCatProgress_' + id);
    const prevStatus = _rmPollLastStatus[id];
    const now        = Date.now();

    // DIAGNOSTIC : log complet (JSON natif tel quel) à chaque changement
    // d'état, + un battement toutes les ~5s pendant "downloading" — permet
    // de repérer un arrêt silencieux (écran éteint / appli en arrière-plan)
    // sans attendre la fin du téléchargement, et de voir le détail renvoyé
    // par le natif (httpCode, contentEncoding, entryCount, hasMeta...).
    if (p.status !== prevStatus) {
        _L('RM','DL_STATUS',{id:id, from:(prevStatus || '(none)'), to:(p.status || '?'), data:JSON.stringify(p)});
        _rmPollLastStatus[id] = p.status;
        _rmPollLastLogTs[id]  = now;
    } else if (p.status === 'downloading' && (now - (_rmPollLastLogTs[id] || 0) > 5000)) {
        _L('RM','DL_PROGRESS',{id:id, data:JSON.stringify(p)});
        _rmPollLastLogTs[id] = now;
    }

    if (p.status === 'downloading' || p.status === 'extracting') {
        _rmRenderDownloadControls(id, 'downloading');
        if (progEl) {
            progEl.textContent = (p.status === 'extracting')
                ? 'فك الضغط...'
                : (p.percent >= 0 ? p.percent + '%' : Math.round((p.downloaded || 0) / 1048576) + ' MB');
        }
        _qpSyncMirrorEl('rmCatProgress_' + id);
    } else if (p.status === 'retrying') {
        // Coupure transitoire (timeout reseau, HTTP 5xx, flux tronque) : WorkManager
        // retente automatiquement apres un court backoff (cf. ReciterDownloadWorker
        // .MAX_RETRY_ATTEMPTS) — on garde le telechargement "actif" (timer de poll,
        // _rmActiveDownloads -> ecran allume) car ce n'est pas un echec definitif,
        // juste une pause courte avant reprise auto depuis le meme octet.
        _rmRenderDownloadControls(id, 'downloading');
        if (progEl) progEl.textContent = 'إعادة الاتصال...';
        _qpSyncMirrorEl('rmCatProgress_' + id);
    } else if (p.status === 'paused') {
        _rmRenderDownloadControls(id, 'paused');
        if (progEl) progEl.textContent = 'متوقف (' + Math.round((p.downloaded || 0) / 1048576) + ' MB)';
        _qpSyncMirrorEl('rmCatProgress_' + id);
        clearInterval(_rmDownloadPollTimers[id]); delete _rmDownloadPollTimers[id];
        _rmSetDownloadActive(id, false);
    } else if (p.status === 'done') {
        clearInterval(_rmDownloadPollTimers[id]); delete _rmDownloadPollTimers[id];
        _rmSetDownloadActive(id, false);
        if (progEl) progEl.textContent = '✓';
        _qpSyncMirrorEl('rmCatProgress_' + id);
        _syncDeviceReciters('download_done');
        refreshQuranServerUI();
        _rmRenderInstalled();
        _rmRenderCatalog();
    } else if (p.status === 'error') {
        // Avant correctif : le bouton n'etait jamais mis a jour ici, restait sur
        // "إيقاف" (pause) -> aucune reprise possible malgre le .part conserve.
        clearInterval(_rmDownloadPollTimers[id]); delete _rmDownloadPollTimers[id];
        _rmSetDownloadActive(id, false);
        _rmRenderDownloadControls(id, 'error');
        if (progEl) progEl.textContent = '⚠ ' + (p.message || 'خطأ');
        _qpSyncMirrorEl('rmCatProgress_' + id);
    }
}

// Exposition globale : ces fonctions sont appelées depuis des attributs
// onclick (statiques dans le HTML injecté, ou générés dynamiquement via
// innerHTML/setAttribute pour chaque ligne du catalogue/installés) — ces
// attributs s'exécutent dans le scope global, pas dans la closure de
// injectTechOptionsUI où elles sont définies. Sans ceci : "X is not defined".
window._rmStartUsbImport             = _rmStartUsbImport;
window._rmLoadCatalog                = _rmLoadCatalog;
window.editReciterCatalogUrlFunction = editReciterCatalogUrlFunction;
window._rmRemoveReciter              = _rmRemoveReciter;
window._rmDownload                   = _rmDownload;
window._rmPauseDownload              = _rmPauseDownload;
window._rmResumeDownload             = _rmResumeDownload;
window._rmCancelDownload             = _rmCancelDownload;

// Même cause, même remède : ces fonctions (section "serveur Coran" / liste
// des 10 récitateurs historiques, juste au-dessus) sont elles aussi appelées
// depuis des attributs onclick/onchange et n'avaient jamais été exposées —
// "toggleQuranServerEnabledFunction/editReciterNameFunction/... is not
// defined" au clic, alors que la fonction existe bien dans le fichier.
window.toggleShowSpeakerIconFunction    = toggleShowSpeakerIconFunction;
