// ── DÉCLENCHEMENT MANUEL DU COMPTE À REBOURS IQAMA ───────────────────────
// Remplace les onclick des azanTime... (HR + VR) par le déclenchement manuel
// du counter iqama. Détecte automatiquement le temps restant selon la prière.

(function patchAzanTimeClicks() {

    // Mapping : IDs des éléments → données de la prière
    // getTime   : getter lazy → toujours la valeur du jour courant
    // iqamaKey  : clé dans JS_DATA pour la durée iqama (en minutes)
    // durationKey: clé dans JS_DATA pour la durée de prière (0 = SHRQ/Doha)
    const prayerClickMap = [
        {
            ids: ['azanTimeFajrHorizontal', 'azanTimeFajrVertical'],
            getTime:     () => fajrTimeInMinutes,
            iqamaKey:    'ucIqamaFAJR',
            durationKey: 'ucPrayDurationFAJR'
        },
        {
            ids: ['azanTimeShrqHorizontal', 'azanTimeShrqVertical'],
            getTime:     () => shuruqTimeInMinutes,
            iqamaKey:    'ucIqamaSHRQ',
            durationKey: null                        // Doha → durée = 0
        },
        {
            ids: ['azanTimeDohrHorizontal', 'azanTimeDohrVertical'],
            getTime:     () => dohrTimeInMinutes,
            iqamaKey:    'ucIqamaDOHR',
            durationKey: 'ucPrayDurationDOHR'
        },
        {
            ids: ['azanTimeAsrHorizontal', 'azanTimeAsrVertical'],
            getTime:     () => asrTimeInMinutes,
            iqamaKey:    'ucIqamaASSR',
            durationKey: 'ucPrayDurationASSR'
        },
        {
            ids: ['azanTimeMgrbHorizontal', 'azanTimeMgrbVertical'],
            getTime:     () => maghribTimeInMinutes,
            iqamaKey:    'ucIqamaMGRB',
            durationKey: 'ucPrayDurationMGRB'
        },
        {
            ids: ['azanTimeIshaHorizontal', 'azanTimeIshaVertical'],
            getTime:     () => ishaTimeInMinutes,
            iqamaKey:    'ucIqamaISHA',
            durationKey: 'ucPrayDurationISHA'
        },
    ];

    prayerClickMap.forEach(function(entry) {
        entry.ids.forEach(function(id) {
            const el = document.getElementById(id);
            if (!el) return;
            const _origOnClick = el.onclick;   // préserve decrementThemeFunction() du HTML
            el.onclick = function() {
                if (_origOnClick) _origOnClick.call(this);   // changement de thème
                const iqamaMin  = JS_DATA[entry.iqamaKey];
                const duration  = entry.durationKey ? JS_DATA[entry.durationKey] : 0;
                const azanTime  = entry.getTime();
                const remaining = (azanTime + iqamaMin) - currentTimeInMinutes;
                if (remaining <= 0 || currentTimeInMinutes < azanTime) return;
                startIqamaCounterFunction(remaining, duration, iqamaMin);
                showIqamaCounter();
            };
        });
    });

})();

