// ── État du lecteur (variables globales, déclarées avant injectTechOptionsUI) ──
// Ces variables sont déjà déclarées en global (var) avant cette IIFE.
// On se contente ici de les réinitialiser à leur valeur par défaut.
_qpReciterIdx  = -1;
_qpSurahNum    = 0;
_qpAutoAdvance = false;
_qpUserAborted = false;
_qpSrcChanging = false;
_qpServerState = 'unknown';
_qpProbeTimer  = null;
_qpRestoring   = false;

// ── Persistance de la position de lecture (localStorage) ─────────────────
const _QP_STORAGE_KEY      = 'JS_QP_POSITION';
const _QP_STORAGE_SRC_KEY  = 'JS_QP_POSITION_SRC';
const _QP_STORAGE_TIME_KEY = 'JS_QP_POSITION_TIME';

// Restauration IMMÉDIATE et SYNCHRONE de l'état (reciterIdx + surahNum) au démarrage
// AVANT que _ensureQuranSelectionForAutoStart ou _playQP puissent s'exécuter
(function _earlyStateRestore() {
    try {
        const raw = localStorage.getItem(_QP_STORAGE_KEY);
        if (!raw) return;
        const data = JSON.parse(raw);
        if (typeof data.reciterIdx !== 'number' || typeof data.surahNum !== 'number') return;
        if (data.reciterIdx < 0 || data.surahNum < 1 || data.surahNum > 114) return;
        // Pré-remplir l'état → _ensureQuranSelectionForAutoStart ne touchera plus ces valeurs
        _qpReciterIdx = data.reciterIdx;
        _qpSurahNum   = data.surahNum;
        // Bloquer _playQP jusqu'à ce que le seek audio soit confirmé
        _qpRestoring  = true;
        var _rName = (JS_CUSTOM.ucReciters[_qpReciterIdx] && JS_CUSTOM.ucReciters[_qpReciterIdx].name) || '?';
        var _sName = (_SURAH_NAMES && _SURAH_NAMES[_qpSurahNum - 1]) || '?';
        _L('AUDIO','FIRE',{action:'restore',reciter:_qpReciterIdx,reciter_name:_rName,surah:_qpSurahNum,surah_name:_sName});
    } catch(e) {}
})();

function _qpSavePosition() {
    if (_qpRestoring) return;                          // ne pas écraser pendant la restauration
    const audio = document.getElementById('quranAudioPlayer');
    if (!audio || _qpReciterIdx < 0 || _qpSurahNum < 1) return;
    const t = audio.currentTime || 0;
    const src = audio.currentSrc || audio.src || _buildQPUrl(_qpReciterIdx, _qpSurahNum);
    if (t === 0 && audio.paused && !src) return; // audio non initialisé
    try {
        localStorage.setItem(_QP_STORAGE_KEY, JSON.stringify({
            reciterIdx:  _qpReciterIdx,
            surahNum:    _qpSurahNum,
            currentTime: t
        }));
        localStorage.setItem(_QP_STORAGE_SRC_KEY, src);
        localStorage.setItem(_QP_STORAGE_TIME_KEY, String(t));
    } catch(e) {}
}

// ── Politique autoplay navigateur ────────────────────────────────────────
// Le navigateur interdit audio.play() sans geste utilisateur préalable.
// _audioUnlocked   : passe à true au 1er geste (clic / toucher / touche)
// _pendingAutoStart: true si un auto-start a été bloqué et doit être relancé
// _audioUnlocked et _pendingAutoStart : globales declarees avant injectTechOptionsUI

// ── Injection de l'overlay + modale (une seule fois au démarrage) ────────
