// RESET ATHAN MINUTES — clic sur la valeur → remet à 0
// ─────────────────────────────────────────────────────────────────────────
(function _installAthanMinutesReset() {
    var _cells = [
        { id: 'athanMinutesFajrValue', key: 'ucAthanMinutesFAJR' },
        { id: 'athanMinutesShrqValue', key: 'ucAthanMinutesSHRQ' },
        { id: 'athanMinutesDohrValue', key: 'ucAthanMinutesDOHR' },
        { id: 'athanMinutesAsrValue',  key: 'ucAthanMinutesASSR' },
        { id: 'athanMinutesMgrbValue', key: 'ucAthanMinutesMGRB' },
        { id: 'athanMinutesIshaValue', key: 'ucAthanMinutesISHA' },
    ];

    _cells.forEach(function(cell) {
        var el = document.getElementById(cell.id);
        if (!el) return;
        el.style.cursor = 'pointer';
        el.title = 'Cliquer pour remettre à 0';
        el.addEventListener('click', function() {
            if (JS_DATA[cell.key] === 0) return;           // déjà à 0, rien à faire
            JS_DATA[cell.key] = 0;
            updateAthanIqamaDisplayFunction();
            saveSettingsToStorageFunction();
            calculateAndDisplayTimesFunction();
            _L('CFG','FIRE',{action:'athanMinutes_reset',key:cell.key,value:0});
        });
    });
})();
