// ═══════════════════════════════════════════════════════════════════════════
// MODE 2 – PALETTE ADAPTATIVE selon le background (data-bg-palette)
// ─────────────────────────────────────────────────────────────────────────
//  Pose l'attribut data-bg-palette sur mainHorizontalContainer à chaque
//  changement de thème.  Le CSS custom.css choisit ensuite la bonne palette
//  de couleurs pour les cellules du MODE 2 "Islamic Green" :
//
//    or    → backgrounds rouges / bordeaux / bruns / photos islamiques chaudes
//    teal  → backgrounds teal / vert-bleu foncé  (contraste or/ambre)
//    bleu  → backgrounds bleus                   (contraste cyan/blanc)
//    sombre→ backgrounds très sombres / noirs    (vert original, pas d'override)
// ═══════════════════════════════════════════════════════════════════════════
(function _installMode2AdaptivePalette() {

    var paletteMap = {
        // Rouge / bordeaux / brun / photo islamique chaude
        or:   [0,1,3,7,8,11,12,13,15,16,17,22,26,29,31,33,34,35,36,38],
        // Teal / vert-bleu foncé
        teal: [2,18,20,21,25,27,37],
        // Bleu
        bleu: [4,6,9,10,14,19,24,28,30]
        // Sombre / noir (5,23,32,39) → défaut vert islamique, pas d'entrée ici
    };

    function _getPalette(idx) {
        for (var name in paletteMap) {
            if (paletteMap.hasOwnProperty(name) && paletteMap[name].indexOf(idx) !== -1) {
                return name;
            }
        }
        return 'sombre';
    }

    function _applyPalette() {
        var hmc = document.getElementById('mainHorizontalContainer');
        if (!hmc) return;
        var idx = (typeof currentThemeIndex !== 'undefined') ? currentThemeIndex : -1;
        hmc.setAttribute('data-bg-palette', _getPalette(idx));
    }

    // Wrapping applyThemeFunction → palette mise à jour à chaque changement de thème
    var _origApply = window.applyThemeFunction;
    if (typeof _origApply === 'function') {
        window.applyThemeFunction = function () {
            var r = _origApply.apply(this, arguments);
            _applyPalette();
            return r;
        };
    }

    // Application initiale (thème déjà résolu au boot)
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', _applyPalette);
    } else {
        _applyPalette();
    }

})();


// ══════════════════════════════════════════════════════════════════════════
//  DEBUG CONSOLE  — affichée sur clic de cityCodeDisplayHorizontal
//  Fenêtre noire couvrant 50 % de l'écran, liste tous les console.log
// ══════════════════════════════════════════════════════════════════════════
(function () {

    // ── Buffer circulaire de logs ─────────────────────────────────────────
    // Chaque entrée : { text: string, isError: bool }
    const _dbgLogs   = [];
    const _MAX_LINES = 300;

    // ── Injection du DOM ──────────────────────────────────────────────────
    const _overlay = document.createElement('div');
    _overlay.id    = 'debugConsoleOverlay';
    _overlay.innerHTML =
        '<div id="debugConsoleHeader">' +
        '<span id="debugConsoleCopyBtn" style="cursor:pointer;" title="Tap to copy logs">DEBUG CONSOLE</span>' +
        '  <span style="font-size:0.8em;opacity:0.55;">(tap to close)</span>' +
        '  <span id="debugConsoleSendBtn" style="cursor:pointer;margin-left:14px;padding:2px 8px;border:1px solid #4af;border-radius:10px;" title="Envoyer ce rapport au developpeur">✉ إرسال للمطوّر</span>' +
        '  <span id="debugConsoleClearNativeBtn" style="cursor:pointer;margin-left:10px;padding:2px 8px;border:1px solid #888;border-radius:10px;" title="Effacer l\'historique natif enregistre (azan/premier-plan) pour repartir sur une journee vierge">🗑 natif</span>' +
        '</div>' +
        '<div id="debugConsoleContent"></div>';
    document.body.appendChild(_overlay);

    const _content = document.getElementById('debugConsoleContent');

    // ── Copie du buffer dans le presse-papiers ────────────────────────────
    function _copyLogs() {
        var text = _dbgLogs.map(function(e) { return e.text; }).join('\n');
        var btn  = document.getElementById('debugConsoleCopyBtn');
        function _feedback(ok) {
            if (!btn) return;
            btn.textContent = ok ? '✓ Copié !' : '✗ Erreur';
            setTimeout(function() {
                btn.textContent = 'DEBUG CONSOLE';
            }, 1800);
        }
        // Méthode moderne (Chrome, Firefox, GeckoView récent)
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(text).then(
                function()  { _feedback(true);  },
                function()  { _fallbackCopy(text, _feedback); }
            );
        } else {
            _fallbackCopy(text, _feedback);
        }
    }

    // Fallback execCommand pour les anciens Android / WebView
    function _fallbackCopy(text, cb) {
        try {
            var ta = document.createElement('textarea');
            ta.value = text;
            ta.style.cssText = 'position:fixed;top:-9999px;left:-9999px;opacity:0;';
            document.body.appendChild(ta);
            ta.focus();
            ta.select();
            var ok = document.execCommand('copy');
            document.body.removeChild(ta);
            cb(ok);
        } catch(e) { cb(false); }
    }

    var _copyBtn = document.getElementById('debugConsoleCopyBtn');
    if (_copyBtn) {
        _copyBtn.addEventListener('click', function(e) {
            e.stopPropagation();   // empêche la fermeture de l'overlay
            _copyLogs();
        });
    }

    // ── Envoi du rapport (contenu de la console) vers Supabase ────────────
    // Table dediee public.debug_reports (INSERT anon uniquement, cf. RLS -
    // aucune lecture cote client, seul le developpeur consulte via le
    // dashboard Supabase). Cle/URL dupliquees ici (meme cle publique deja
    // embarquee dans l'app, cf. _installConfigSync) : permet a un intervenant
    // a distance d'envoyer le rapport d'un simple tap, sans e-mail ni app
    // tierce a configurer sur le boitier.
    var _SB_URL = (window.MOSQUE_CONFIG && window.MOSQUE_CONFIG.SUPABASE_URL)
               || 'https://tjmjmlzwzebocfdmifrg.supabase.co';
    var _SB_KEY = (window.MOSQUE_CONFIG && window.MOSQUE_CONFIG.SUPABASE_ANON_KEY)
               || 'sb_publishable_P9MMDcQw_mM4bLqCVCj_3A_tdTK5Tj4';

    function _sendReport() {
        var btn = document.getElementById('debugConsoleSendBtn');
        var _reset = function(label, delay) {
            setTimeout(function() {
                if (btn) btn.textContent = '✉ إرسال للمطوّر';
            }, delay || 2200);
            if (btn) btn.textContent = label;
        };
        if (btn) btn.textContent = '… جارٍ الإرسال';

        var mosqueId = '';
        try { mosqueId = localStorage.getItem('UC_MOSQUE_ID') || ''; } catch(e) {}

        var payload = {
            mosque_id: mosqueId,
            log_text: _dbgLogs.map(function(e) { return e.text; }).join('\n'),
            device_info: {
                userAgent: navigator.userAgent,
                screen: screen.width + 'x' + screen.height,
                dpr: window.devicePixelRatio,
                mosqueName: (typeof JS_DATA !== 'undefined' && JS_DATA.ucMosqueName) || '',
                appVersion: (typeof CUSTOM_APP_VERSION !== 'undefined') ? CUSTOM_APP_VERSION : ''
            }
        };

        fetch(_SB_URL + '/rest/v1/debug_reports', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'apikey': _SB_KEY,
                'Authorization': 'Bearer ' + _SB_KEY
            },
            body: JSON.stringify(payload)
        }).then(function(r) {
            if (!r.ok) throw new Error('HTTP ' + r.status);
            _reset('✓ تم الإرسال');
            var _L_SENT = { AR: 'تم إرسال التقرير', FR: 'Rapport envoyé', EN: 'Report sent' };
            if (window._ucToast) window._ucToast(_L_SENT[_ucLang()] || _L_SENT.EN, 'ok');
        }).catch(function(err) {
            _reset('✗ فشل الإرسال');
            var _L_FAILED = { AR: 'فشل إرسال التقرير', FR: 'Échec envoi rapport', EN: 'Report send failed' };
            if (window._ucToast) window._ucToast(_L_FAILED[_ucLang()] || _L_FAILED.EN, 'err');
            console.error('[DIAG] send report failed', err.message || String(err));
        });
    }

    var _sendBtn = document.getElementById('debugConsoleSendBtn');
    if (_sendBtn) {
        _sendBtn.addEventListener('click', function(e) {
            e.stopPropagation();   // empêche la fermeture de l'overlay
            _sendReport();
        });
    }

    // ── Effacer l'historique natif persistant (NativeEventLog cote Android) ──
    // N'efface PAS les logs JS deja affiches dans cette session (_dbgLogs) :
    // seulement le stockage natif, pour qu'un prochain rechargement de page
    // ne re-fusionne pas les entrees d'avant.
    var _clearNativeBtn = document.getElementById('debugConsoleClearNativeBtn');
    if (_clearNativeBtn) {
        _clearNativeBtn.addEventListener('click', function(e) {
            e.stopPropagation();
            if (window.AndroidMobile && typeof window.AndroidMobile.clearNativeEventLog === 'function') {
                window.AndroidMobile.clearNativeEventLog();
                console.log('[AZAN] historique natif efface (nouveau depart)');
                var _L_CLEARED = { AR: 'تم مسح السجل الأصلي', FR: 'Historique natif effacé', EN: 'Native history cleared' };
                if (window._ucToast) window._ucToast(_L_CLEARED[_ucLang()] || _L_CLEARED.EN, 'ok');
            }
        });
    }

    // ── Rendu HTML (échappe < > & pour éviter toute injection) ───────────
    function _escHtml(s) {
        return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    }
    function _render() {
        _content.innerHTML = _dbgLogs.map(function(entry) {
            var escaped = _escHtml(entry.text);
            return entry.isError
                ? '<span style="color:#ff4444;">' + escaped + '</span>'
                : escaped;
        }).join('\n');
    }

    // ── Interception console.log / warn / error ───────────────────────────
    function _capture(level, orig, args) {
        orig.apply(console, args);
        const now = new Date();
        const ts  = now.getHours()  .toString().padStart(2, '0') + ':' +
                    now.getMinutes().toString().padStart(2, '0') + ':' +
                    now.getSeconds().toString().padStart(2, '0');
        const msg = Array.prototype.slice.call(args).map(function (a) {
            return (a !== null && typeof a === 'object') ? JSON.stringify(a) : String(a);
        }).join(' ');
        const prefix = level === 'warn' ? '⚠ ' : level === 'error' ? '🔴 ' : '';
        // Une ligne est "erreur" si console.warn/error OU si le message contient HTTP_ERR
        const isError = (level === 'warn' || level === 'error') ||
                        msg.indexOf('HTTP_ERR') !== -1;
        // Ne pas re-préfixer l'horodatage si le message commence déjà par [HH:MM:SS]
        var _tsPrefix = /^\[\d\d:\d\d:\d\d\]/.test(msg) ? '' : '[' + ts + '] ';
        _dbgLogs.push({ text: _tsPrefix + prefix + msg, isError: isError });
        if (_dbgLogs.length > _MAX_LINES) _dbgLogs.shift();
        if (_overlay.style.display !== 'none') {
            _render();
            _overlay.scrollTop = _overlay.scrollHeight;
        }
    }

    const _origLog   = console.log.bind(console);
    const _origWarn  = console.warn.bind(console);
    const _origError = console.error.bind(console);
    console.log   = function() { _capture('log',   _origLog,   arguments); };
    console.warn  = function() { _capture('warn',  _origWarn,  arguments); };
    console.error = function() { _capture('error', _origError, arguments); };

    // ── Erreurs de chargement de ressources HTML (audio, img, script…) ───
    // Ces erreurs ne passent PAS par console.error — elles sont générées par
    // le navigateur au niveau de l'élément DOM. On les capte en phase capture
    // (3e argument = true) et on les route comme 'error' pour qu'elles
    // apparaissent en rouge dans la console d'application.
    window.addEventListener('error', function(evt) {
        // Filtrer : on veut les erreurs sur des éléments (pas les erreurs JS globales)
        var t = evt.target;
        if (!t || t === window) return;
        var tag = (t.tagName || '?').toLowerCase();
        var src = t.src || t.href || t.currentSrc || '?';
        var msg = '🔴 [RES] ' + tag.toUpperCase() + ' load failed: ' + src;
        // Passer par _capture pour le rendu rouge + stockage dans _dbgLogs
        _capture('error', _origError, [msg]);
    }, true /* capture phase */);

    // ── Afficher / masquer ────────────────────────────────────────────────
    function _toggle(e) {
        if (e) e.stopPropagation();
        // getComputedStyle (état réellement affiché, qu'il vienne de la feuille de
        // style ou du style inline) plutôt que _overlay.style.display (inline
        // uniquement) : sinon le tout premier appel après chargement de page — où
        // le masquage vient de la règle CSS #debugConsoleOverlay{display:none} et
        // non d'un style inline — se trompait de branche (croyait la console déjà
        // visible) et la "cachait" en no-op au lieu de l'afficher.
        var isVisible = getComputedStyle(_overlay).display !== 'none';
        if (isVisible) {
            _overlay.style.display = 'none';
        } else {
            var _cb = document.getElementById('debugConsoleCopyBtn');
            if (_cb) _cb.textContent = 'DEBUG CONSOLE';
            _render();
            _overlay.style.display = 'flex';
            _overlay.scrollTop     = _overlay.scrollHeight;
        }
    }

    // Exposé pour d'autres déclencheurs externes (ex. qrCodeImageBig, cf. section
    // "QR CODE" plus haut) sans dupliquer la logique d'affichage/masquage.
    window._toggleDebugConsole = _toggle;

    // Clic sur l'overlay lui-même → ferme
    _overlay.addEventListener('click', function(e) { _toggle(e); });

    // Clic sur cityCodeDisplayHorizontal → ouvre / ferme la console
    var _trigger = document.getElementById('cityCodeDisplayHorizontal');
    if (_trigger) {
        _trigger.style.cursor = 'pointer';
        _trigger.addEventListener('click', _toggle);
    }
    var _triggerV = document.getElementById('cityCodeDisplayVertical');
    if (_triggerV) {
        _triggerV.style.cursor = 'pointer';
        _triggerV.addEventListener('click', _toggle);
    }

    // Clic sur qrFlagImageHorizontal/Vertical -> meme fonction que cityCode
    ['qrFlagImageHorizontal', 'qrFlagImageVertical'].forEach(function(id) {
        var el = document.getElementById(id);
        if (el) {
            el.style.cursor = 'pointer';
            el.addEventListener('click', _toggle);
        }
    });

})();

// ══════════════════════════════════════════════════════════════════════════
//  HISTORIQUE CYCLE DE VIE AZAN — fusion native -> console de debug
// ══════════════════════════════════════════════════════════════════════════
//  Objectif : pouvoir consulter, après une journée d'utilisation normale,
//  l'historique complet des événements liés à l'azan (alarme programmée /
//  déclenchée, lecture native jouée ou sautée, lecture webview, passages
//  premier-plan/arrière-plan) — y compris ce qui s'est passé pendant que
//  l'appli était fermée/en arrière-plan (cf. NativeEventLog.kt côté natif,
//  MobileJsBridge.getNativeEventLog()). Utile en particulier pour confirmer
//  qu'un seul azan se joue désormais (cf. correctif onPause/pauseTimers).
//
//  Chaque entrée native est réinjectée via console.log (donc interceptée et
//  affichée par la console de debug existante, cf. IIFE ci-dessus) avec son
//  horodatage RÉEL (celui de l'événement, pas l'heure de fusion) pour rester
//  chronologiquement cohérente avec les logs JS de la session en cours.
//  Exécuté UNE SEULE FOIS par chargement de page (pas à chaque ouverture de
//  la console) pour ne jamais dupliquer les entrées déjà fusionnées.
// ─────────────────────────────────────────────────────────────────────────
(function _mergeNativeAzanLog() {
    if (typeof window.AndroidMobile === 'undefined' ||
        typeof window.AndroidMobile.getNativeEventLog !== 'function') return;

    function _fmtTs(ts) {
        var d = new Date(ts);
        return '[' + ('0' + d.getHours()).slice(-2) + ':' +
                     ('0' + d.getMinutes()).slice(-2) + ':' +
                     ('0' + d.getSeconds()).slice(-2) + ']';
    }

    try {
        var arr = JSON.parse(window.AndroidMobile.getNativeEventLog() || '[]');
        arr.forEach(function(entry) {
            console.log(_fmtTs(entry.ts) + ' [' + entry.tag + '] ' + entry.text);
        });
        if (arr.length) {
            console.log('--- ' + arr.length + ' événement(s) natif(s) chargé(s) (historique complet, y compris appli fermée) ---');
        }
    } catch (e) {
        console.warn('[AZAN] fusion historique natif échouée : ' + e.message);
    }
})();

// ── Historique cycle de vie azan : lecture WebView (playAzanSoundFunction) ──
//  Seul événement du cycle de vie de l'azan qui n'a, jusque-là, aucune trace
//  dans la console de debug : le core (m2body.js) joue l'audio directement
//  (audioBeepElementVar en mode normal, audioAzanMainElement/audioFajrAzanElement
//  en mode vocal ucAzanIqamaByVoice=1) sans jamais logger quoi que ce soit.
//  Ce wrapper ne modifie aucun comportement (appelle _orig normalement),
//  il ajoute uniquement une ligne dans _dbgLogs pour compléter la timeline
//  déjà alimentée par NativeEventLog (alarme/lecture native/premier-plan).
(function _installAzanWebviewPlayLog() {
    var _orig = window.playAzanSoundFunction;
    if (typeof _orig !== 'function') return;

    window.playAzanSoundFunction = function() {
        _L('AZAN', 'WEBVIEW_PLAY_START', {
            prayer:    _ucPrayerAtMinutes(currentTimeInMinutes),
            voiceMode: (JS_DATA.ucAzanIqamaByVoice == 1)
        });
        return _orig.apply(this, arguments);
    };
})();

// ── TRACE DIAGNOSTIC TEMPORAIRE : identifier le WebView système ────────────
// Objectif : diagnostiquer, directement depuis la console de debug intégrée
// (pas besoin d'adb), les boîtiers TV Android dont le WebView système (cf.
// MainActivity.kt -> android.webkit.WebView, PAS un moteur embarqué dans
// l'APK) échoue à peindre certains overlays plein-écran alors que la logique
// JS s'exécute normalement (bug rapporté : quranPlayerOverlay invisible sur
// X96 Max, OK sur X88 Pro20). Placée APRÈS l'installation de la console de
// debug (juste au-dessus) pour apparaître dans son buffer, pas seulement
// dans logcat. À retirer une fois le problème diagnostiqué/contourné.
(function _installWebViewDiagTrace() {
    _L('DIAG', 'BOOT', {
        userAgent: navigator.userAgent,
        screen: screen.width + 'x' + screen.height,
        dpr: window.devicePixelRatio,
        hwConcurrency: navigator.hardwareConcurrency || 'n/a'
    });
})();


// ═══════════════════════════════════════════════════════════════════════════
// ── AZAN CUSTOM : audio spec/ + durée popup = durée audio + marquee sounna
// ═══════════════════════════════════════════════════════════════════════════
(function _installCustomAzanFeatures() {

    // ─────────────────────────────────────────────────────────────────────
    // 1. Sources audio : redirection vers spec/audio/
    //    • spec/audio/audio_fajr.ogg pour le fajr
    //    • spec/audio/audio_azan.ogg pour les autres prières
    // ─────────────────────────────────────────────────────────────────────
    (function _redirectAzanAudio() {
        // Redirige les elements audio vers la bonne source.
        // Si ucAzanFromServer == 1 : sonde le serveur HTTP, utilise
        //   {ucQuranServerUrl}/AUDIO/audio_azan.mp3 (et audio_fajr.mp3)
        //   En cas d'echec : repli sur spec/audio/.
        // Si ucAzanFromServer == 0 : utilise directement spec/audio/.
        if (JS_DATA.ucAzanIqamaByVoice != 1) return;

        var azanEl    = document.getElementById('audioAzanElement');
        var fajrEl    = document.getElementById('audioFajrElement');
        var localAzan = 'spec/audio/audio_azan.ogg';
        var localFajr = 'spec/audio/audio_fajr.ogg';

        function _applyAzanSrc(azanSrc, fajrSrc, source) {
            if (azanEl) { azanEl.src = azanSrc; azanEl.load(); }
            if (fajrEl) { fajrEl.src = fajrSrc; fajrEl.load(); }
            _L('AUDIO','FIRE',{action:'redirect_azan_audio',
                source:source, azan:azanSrc, fajr:fajrSrc});
        }

        if (JS_CUSTOM.ucAzanFromServer != 1) {
            _applyAzanSrc(localAzan, localFajr, 'local');
            return;
        }

        // Sonde le serveur (HEAD sur audio_azan) avec timeout 3 s
        var base       = (JS_CUSTOM.ucQuranServerUrl || 'http://127.0.0.1:8080').replace(/\/+$/, '');
        var serverAzan = base + '/AUDIO/audio_azan.mp3';
        var serverFajr = base + '/AUDIO/audio_fajr.mp3';

        var xhr = new XMLHttpRequest();
        xhr.open('HEAD', serverAzan, true);
        xhr.timeout = 3000;
        xhr.onload = function() {
            if (xhr.status >= 200 && xhr.status < 400) {
                _applyAzanSrc(serverAzan, serverFajr, 'server');
            } else {
                _L('AUDIO','WARN',{action:'redirect_azan_audio',
                    reason:'server_http_' + xhr.status, fallback:'local'});
                _applyAzanSrc(localAzan, localFajr, 'local_fallback');
            }
        };
        xhr.onerror = function() {
            _L('AUDIO','WARN',{action:'redirect_azan_audio',
                reason:'server_unreachable', fallback:'local'});
            _applyAzanSrc(localAzan, localFajr, 'local_fallback');
        };
        xhr.ontimeout = function() {
            _L('AUDIO','WARN',{action:'redirect_azan_audio',
                reason:'server_timeout', fallback:'local'});
            _applyAzanSrc(localAzan, localFajr, 'local_fallback');
        };
        xhr.send();
    })();


    // ─────────────────────────────────────────────────────────────────────
    // 1b. Source audio fin.ogg : redirection au chargement (même pattern que azan)
    // ─────────────────────────────────────────────────────────────────────
    (function _redirectFinAudio() {
        var finEl    = document.getElementById('quranFinAudio');
        if (!finEl) return;
        var localSrc = 'spec/audio/fin.ogg';

        function _applyFinSrc(src, source) {
            finEl.src = src;
            finEl.load();
            _L('AUDIO','FIRE',{action:'redirect_fin_audio', source:source, src:src});
        }

        // fin.mp3 suit le serveur Coran (ucQuranServerEnabled), pas l'azan (ucAzanFromServer)
        if (JS_CUSTOM.ucQuranServerEnabled != 1) {
            _applyFinSrc(localSrc, 'local');
            return;
        }

        var base      = (JS_CUSTOM.ucQuranServerUrl || 'http://127.0.0.1:8080').replace(/\/+$/, '');
        var serverSrc = base + '/AUDIO/fin.mp3';
        var xhr = new XMLHttpRequest();
        xhr.open('HEAD', serverSrc, true);
        xhr.timeout = 3000;
        xhr.onload = function() {
            if (xhr.status >= 200 && xhr.status < 400) {
                _applyFinSrc(serverSrc, 'server');
            } else {
                _L('AUDIO','WARN',{action:'redirect_fin_audio',
                    reason:'server_http_' + xhr.status, fallback:'local'});
                _applyFinSrc(localSrc, 'local_fallback');
            }
        };
        xhr.onerror   = function() {
            _L('AUDIO','WARN',{action:'redirect_fin_audio',
                reason:'server_unreachable', fallback:'local'});
            _applyFinSrc(localSrc, 'local_fallback');
        };
        xhr.ontimeout = function() {
            _L('AUDIO','WARN',{action:'redirect_fin_audio',
                reason:'server_timeout', fallback:'local'});
            _applyFinSrc(localSrc, 'local_fallback');
        };
        xhr.send();
    })();

    // ─────────────────────────────────────────────────────────────────────
    // 1c. APK : patch redirectToAudioHandlerFunction pour azan/fajr
    //     Sur APK (isTawkitApp=true), le coeur appelle
    //     redirectToAudioHandlerFunction(xfile) -> location.href=tawkit_audio
    //     au lieu de audioEl.play(). Trois effets negatifs :
    //       - La src redirigee vers le serveur (set par 1a) est ignoree
    //       - L'evenement 'ended' ne se declenche jamais -> popup reste ouverte
    //         jusqu'au safety_timeout_4min (imprecis, env. 4 min)
    //       - location.href declenche beforeunload -> _ucUnloading perturbe
    //     Ce patch intercepte audio_azan / audio_fajr et appelle audioEl.play()
    //     directement avec la src deja redirigee par _redirectAzanAudio().
    //     Si play() echoue (serveur indisponible), repli automatique vers natif.
    // ─────────────────────────────────────────────────────────────────────
    (function _patchRedirectAudioForAzan() {
        if (typeof isTawkitApp === 'undefined' || !isTawkitApp) return;
        if (typeof redirectToAudioHandlerFunction !== 'function') return;

        var _origRedirectToAudio = redirectToAudioHandlerFunction;
        var _AZAN_EL_MAP = {
            'audio_azan': 'audioAzanElement',
            'audio_fajr': 'audioFajrElement'
        };

        window.redirectToAudioHandlerFunction = function(xfile) {
            var elId = _AZAN_EL_MAP[xfile];
            if (!elId) { _origRedirectToAudio(xfile); return; }

            // N'intercepte que si le mode vocal est actif et azan long (non court)
            if (JS_DATA.ucAzanIqamaByVoice != 1 || JS_DATA.ucShortAzanActive == 1) {
                _origRedirectToAudio(xfile); return;
            }

            var el = document.getElementById(elId);
            if (!el || !el.src) { _origRedirectToAudio(xfile); return; }

            _L('AZAN', 'PATCH_AZAN_PLAY', {xfile: xfile,
                src: el.src.replace(/^https?:\/\/[^\/]+/, '...8080')});

            el.currentTime = 0;
            var p = el.play();
            if (p && typeof p.catch === 'function') {
                p.catch(function(err) {
                    _L('AZAN', 'PATCH_AZAN_ERR', {xfile: xfile, reason: String(err)});
                    _origRedirectToAudio(xfile);   // repli sur handler natif
                });
            }
            // Ne PAS appeler _origRedirectToAudio : on bypasse le handler natif
            // pour garder la src serveur et l'evenement 'ended'
        };

        _L('SYS', 'PATCH', {fn: 'redirectToAudioHandlerFunction',
            for: 'azan_webplay_server_ended'});
    })();

    // ─────────────────────────────────────────────────────────────────────
    // 2. Durée du popup azan = durée de l'audio
    //    Stratégie : bloquer hideAzanPopupFunction() tant que l'audio joue.
    //    En cas d'erreur audio, chaîne de fallback à 3 niveaux :
    //      1. serveur HTTP  (source initiale, déjà chargée par _redirectAzanAudio)
    //      2. spec/audio/   (fichiers locaux dans le dossier spec/)
    //      3. core APK      (resource://android/assets/audio/)
    //    Si tous les niveaux échouent, le popup reste affiché au moins 300 s
    //    (safety-timeout) sauf si l'utilisateur le ferme manuellement.
    // ─────────────────────────────────────────────────────────────────────
    var _ucBlockAzanHide    = false;
    var _ucAzanReleaseFunc  = null;
    var _ucAzanSafetyTimer  = null;
    var _ucLastAzanAudioEl  = null;
    // État du fallback courant
    var _ucAzanFbEl         = null;   // élément <audio> en cours de tentative
    var _ucAzanFbIsFajr     = false;  // true si prière Fajr

    // ── Poll natif avant fermeture réelle ───────────────────────────────────
    // Sur appli native, le son AUDIBLE vient TOUJOURS de AzanPlaybackService
    // (MediaPlayer natif, cf. plus haut) qui joue en dur un fichier bundlé
    // (spec/audio/audio_azan.ogg / audio_fajr.ogg) -- alors que ce <audio> JS
    // muted peut pointer vers une AUTRE source (serveur HTTP mosquée si
    // ucAzanFromServer==1, ou fichier choisi dans le catalogue d'azan
    // personnalisé, cf. _acApplyAzanToPlayer) dont la durée n'a aucune raison
    // de correspondre à celle du fichier natif. Résultat observé en usage
    // réel (boîtier) : l'événement 'ended' de ce <audio> JS arrive AVANT que
    // le son natif (le seul réellement audible) ne soit terminé -> la page
    // azan se ferme trop tôt alors que l'azan continue de sonner.
    // Fix : ne relâcher le verrou qu'une fois AzanPlaybackService confirme
    // (isAzanCurrentlyPlaying() == false) que la lecture native est bien
    // terminée -- le timer de sécurité 300s reste le filet de secours ultime
    // si ce polling ne se termine jamais (ex. bug natif).
    var _ucNativePollTimer  = null;
    var _ucNativePollGen    = 0;
    var _ucNativePollActive = false;   // un sondage tourne déjà pour ce cycle azan
    var _ucNativeSeenPlaying = false;  // isAzanCurrentlyPlaying() vu à true au moins une fois ce cycle

    // Garde anti-course (constaté en test live, 27/07/2026) : l'appel
    // IMMÉDIAT (cf. plus bas, "native_poll_immediate") sonde le natif dès
    // AZAN_TIME -- mais le déclenchement natif (PrayerAlarmReceiver, alarme
    // AlarmManager séparée) et l'AZAN_TIME JS (tick de clockTickFunction) ne
    // sont PAS synchronisés : isAzanCurrentlyPlaying() peut légitimement
    // renvoyer false ne serait-ce que parce que le service natif n'a pas
    // ENCORE démarré, pas parce que l'azan est terminé. Sans cette garde, le
    // popup se fermait instantanément, avant même le début du son natif
    // (confirmé en test : blocked=false juste après le trigger, alors
    // qu'aucune lecture native n'avait encore commencé). On n'accepte donc
    // un "false" comme "terminé" qu'après avoir observé au moins un "true"
    // pendant CE cycle -- le timer de sécurité 300s reste le filet de
    // secours ultime si le natif ne démarre jamais du tout.
    function _ucWaitNativeThenRelease(reason) {
        if (!_ucHasNative('isAzanCurrentlyPlaying')) {
            _ucReleaseAzanBlock(reason);
            return;
        }
        if (_ucNativePollActive) return;   // sondage déjà en cours pour ce cycle -- ne pas redémarrer/réinitialiser l'état "vu jouer"
        _ucNativePollActive = true;
        var gen = ++_ucNativePollGen;
        function _poll() {
            if (gen !== _ucNativePollGen) return;   // cycle azan suivant démarré entretemps
            if (!_ucBlockAzanHide)        return;   // déjà relâché (safety-timer, fermeture manuelle...)
            var stillPlaying = false;
            try { stillPlaying = !!window.AndroidMobile.isAzanCurrentlyPlaying(); } catch (err) {}
            if (stillPlaying) {
                _ucNativeSeenPlaying = true;
                _ucNativePollTimer = setTimeout(_poll, 1000);
                return;
            }
            if (!_ucNativeSeenPlaying) {
                // Pas encore démarré côté natif (ou déjà terminé si l'alarme
                // native a un train de retard) -- on ne peut pas encore
                // trancher, on continue de sonder.
                _ucNativePollTimer = setTimeout(_poll, 1000);
                return;
            }
            _L('AZAN', 'NATIVE_POLL_DONE', {reason: reason});
            _ucNativePollActive = false;
            _ucReleaseAzanBlock(reason);
        }
        _L('AZAN', 'NATIVE_POLL_WAIT', {reason: reason});
        _poll();
    }

    _ucRegisterCleanup(function() {
        if (_ucAzanSafetyTimer) { clearTimeout(_ucAzanSafetyTimer); _ucAzanSafetyTimer = null; }
        if (_ucNativePollTimer) { clearTimeout(_ucNativePollTimer); _ucNativePollTimer = null; }
        _ucNativePollGen++;
        _ucNativePollActive  = false;
        _ucNativeSeenPlaying = false;
        _ucBlockAzanHide = false;
        _ucAzanFbEl      = null;
    });

    // Wrapping de hideAzanPopupFunction (déjà patchée par _ucInstallHooks)
    var _origHideAzanCustom = hideAzanPopupFunction;
    hideAzanPopupFunction = function() {
        if (_ucBlockAzanHide) {
            _L('AZAN','POPUP_HIDE_BLOCKED',{reason:'audio_in_progress'});
            return;
        }
        _origHideAzanCustom();
    };

    // ── Chaîne de fallback : server → spec/audio → core APK ────────────────────────────
    //    Appelée sur l'événement 'error' de l'élément <audio> azan.
    //    Progresse dans la hiérarchie de sources jusqu'à épuisement ;
    //    si tout échoue, le popup reste ouvert jusqu'au safety-timer (300 s).
    function _ucAzanFallbackOrHold() {
        var el = _ucAzanFbEl;
        if (!el) { _ucReleaseAzanBlock(); return; }
        var isFajr  = _ucAzanFbIsFajr;
        var specSrc = isFajr ? 'spec/audio/audio_fajr.ogg' : 'spec/audio/audio_azan.ogg';
        var coreSrc = isFajr
            ? 'resource://android/assets/audio/audio_fajr.mp3'
            : 'resource://android/assets/audio/audio_azan.mp3';

        var cur    = (el.src || '').replace(/\?.*$/, '');
        var isSpec = cur.indexOf('spec/audio/') !== -1;
        var isCore = cur.indexOf('/assets/audio/audio_') !== -1;

        function _trySrc(fromLabel, src) {
            _L('AZAN','AUDIO_FALLBACK',{from:fromLabel, to:src});
            el.src = src;
            el.load();
            var p = el.play();
            if (p && typeof p.catch === 'function') {
                p.catch(function(err) {
                    _L('AZAN','AUDIO_FALLBACK_ERR',{src:src, err:String(err)});
                    // L'événement 'error' sur l'élément se déclenchera et appellera
                    // _ucAzanFallbackOrHold pour le niveau suivant
                });
            }
        }

        if (!isSpec && !isCore) {
            // Niveau 1 : server a échoué → essayer spec/audio
            _trySrc('server', specSrc);
            return;
        }
        if (isSpec) {
            // Niveau 2 : spec/audio a échoué → essayer core APK
            _trySrc('spec', coreSrc);
            return;
        }
        // Niveau 3 : tout épuisé → popup maintenu jusqu'au safety-timer (300 s)
        _L('AZAN','AUDIO_FALLBACK_EXHAUST',{note:'popup_held_until_safety_300s'});
        // Ne PAS appeler _ucReleaseAzanBlock : le safety-timer (300 s) fermera le popup
    }

    function _ucReleaseAzanBlock(reason) {
        if (!_ucBlockAzanHide) {
            _L('AZAN','RELEASE_BLOCK_SKIP',{reason:reason||'audio_ended',note:'already_released'});
            return;         // déjà libéré
        }
        _ucBlockAzanHide = false;
        _ucAzanFbEl      = null;
        if (_ucAzanSafetyTimer) { clearTimeout(_ucAzanSafetyTimer); _ucAzanSafetyTimer = null; }
        if (_ucLastAzanAudioEl && _ucAzanReleaseFunc) {
            _ucLastAzanAudioEl.removeEventListener('ended', _ucAzanReleaseFunc);
            _ucLastAzanAudioEl.removeEventListener('error', _ucAzanFallbackOrHold);
        }
        _L('AZAN','WEBVIEW_AUDIO_END',{result:'closing_popup',reason:reason||'audio_ended'});
        hideAzanPopupFunction();
    }
    // État lisible depuis l'extérieur (diagnostic resync) : true si le popup
    // est actuellement retenu ouvert par ce verrou (audio en cours/gelé).
    window._ucIsAzanBlocked = function() { return _ucBlockAzanHide; };
    // Exposé pour _ucResyncPrayerSequence (tout en haut du fichier) : sans
    // lever ce verrou AVANT d'appeler hideAzanPopupFunction() au réveil, le
    // popup restait bloqué indéfiniment si l'écran s'était éteint PENDANT la
    // lecture (audio JS muet gelé par pauseTimers() avant son 'ended' ->
    // _ucBlockAzanHide jamais relâché ; même le safety-timer 300s/180s ne
    // sauve pas, lui aussi gelé). Idempotent (no-op si déjà relâché).
    window._ucReleaseAzanBlock = _ucReleaseAzanBlock;

    ucOn(UC_EVT.AZAN_TIME, function(e) {
        if (e.isDohaPrayer)                     return;   // shuruq : pas d'audio long
        // mode silencieux : popup maintenu 180 s (= ~3min audio)
        if (JS_DATA.ucAzanIqamaByVoice != 1) {
            if (e.isDohaPrayer) return;
            if (_ucBlockAzanHide) return;
            _ucBlockAzanHide = true;
            if (_ucAzanSafetyTimer) clearTimeout(_ucAzanSafetyTimer);
            _ucAzanSafetyTimer = setTimeout(function() {
                _L('AZAN','POPUP_FORCE_CLOSE',{prayer:e.prayer,reason:'silent_mode_timeout_180s'});
                _ucReleaseAzanBlock();
            }, 180000);
            _L('AZAN','WEBVIEW_AUDIO_SKIP',{prayer:e.prayer,reason:'voice_disabled',popup_hold:'180s'});
            return;
        }
        if (JS_DATA.ucShortAzanActive  ==  1)   return;   // azan court : durée connue d'avance

        var isFajr   = (e.prayer === 'FAJR');
        var audioEl  = document.getElementById(isFajr ? 'audioFajrElement' : 'audioAzanElement');
        if (!audioEl) return;

        // Source audio UNIQUE : sur l'appli native (AndroidMobile present), le
        // vrai son est desormais TOUJOURS joue cote natif (AzanPlaybackService,
        // MediaPlayer) -- foreground ET background -- au lieu de dependre d'un
        // garde-fou "premier plan ?" evalue une seule fois par l'alarme (ancien
        // bug : sortir l'appli PENDANT la lecture ne faisait rien reprendre
        // cote natif puisque la decision avait deja ete prise). Ce <audio> JS
        // continue de jouer (muted) pour piloter exactement comme avant tout
        // ce qui en depend (equalizer, evenement 'ended' -> fermeture popup,
        // timer de securite) -- seule la sortie audible est coupee, evitant un
        // double son avec le natif. On atteint ce point uniquement en mode
        // "voix complete" (ucAzanIqamaByVoice==1, ucShortAzanActive!=1, cf. les
        // 2 "return" ci-dessus) : azan court/bip restent sur l'ancien
        // comportement (JS foreground uniquement, natif background seulement).
        audioEl.muted = !!window.AndroidMobile;
        _L('AZAN','AUDIO_SOURCE',{prayer:e.prayer,muted:audioEl.muted,
            reason:(audioEl.muted ? 'native_takeover' : 'no_native_bridge')});

        // Nettoyer une éventuelle session précédente
        if (_ucLastAzanAudioEl && _ucAzanReleaseFunc) {
            _ucLastAzanAudioEl.removeEventListener('ended', _ucAzanReleaseFunc);
            _ucLastAzanAudioEl.removeEventListener('error', _ucAzanFallbackOrHold);
        }
        if (_ucAzanSafetyTimer) { clearTimeout(_ucAzanSafetyTimer); _ucAzanSafetyTimer = null; }
        if (_ucNativePollTimer) { clearTimeout(_ucNativePollTimer); _ucNativePollTimer = null; }
        _ucNativePollGen++;   // invalide tout polling natif d'un cycle azan précédent
        _ucNativePollActive  = false;
        _ucNativeSeenPlaying = false;

        _ucAzanFbEl         = audioEl;
        _ucAzanFbIsFajr     = isFajr;
        _ucLastAzanAudioEl  = audioEl;
        _ucBlockAzanHide    = true;
        // 'ended' de ce <audio> JS (muted côté natif) ne ferme plus la popup
        // directement : il ne fait que déclencher l'attente de la fin RÉELLE
        // côté natif (cf. _ucWaitNativeThenRelease ci-dessus).
        _ucAzanReleaseFunc  = function() { _ucWaitNativeThenRelease('audio_ended'); };

        audioEl.addEventListener('ended', _ucAzanReleaseFunc);
        audioEl.addEventListener('error', _ucAzanFallbackOrHold);

        // Repli robuste (retour utilisateur, 27/07/2026) : constaté en
        // pratique (journal natif) -- le <audio> JS muet (simple minuteur
        // côté natif, aucun son audible) peut lui-même accuser un retard
        // important sur son PROPRE 'ended' par rapport à la lecture native
        // réelle, même appli au premier plan (~100s de retard observés un
        // jour, popup restée ouverte tout ce temps alors que l'azan était
        // déjà terminé -- cause probable : le <audio> JS a dû rebufferiser/
        // recharger sa propre source séparément du lecteur natif). Plutôt que
        // d'attendre cet événement pour DÉMARRER le sondage natif (cf.
        // _ucWaitNativeThenRelease), on le démarre désormais IMMÉDIATEMENT
        // dès que le natif prend la main -- reflète la réalité native sans
        // dépendre de la fidélité du <audio> JS. Le 'ended' ci-dessus reste
        // en place comme déclencheur redondant (sans risque : _ucReleaseAzanBlock
        // et le suivi par génération, cf. plus haut, sont idempotents).
        if (audioEl.muted && _ucHasNative('isAzanCurrentlyPlaying')) {
            _ucWaitNativeThenRelease('native_poll_immediate');
        }

        // Safety : fermeture forcée après 300 s au plus
        //   (couvre le cas où tous les fallbacks échouent silencieusement)
        _ucAzanSafetyTimer = setTimeout(function() {
            _L('AZAN','POPUP_FORCE_CLOSE',{prayer:e.prayer,reason:'safety_timeout_300s'});
            _ucReleaseAzanBlock();
        }, 300000);

        _L('AZAN','WEBVIEW_AUDIO_FIRE',{prayer:e.prayer,result:'popup_blocked_until_end'});
    });


    // ─────────────────────────────────────────────────────────────────────
    // 3. Marquee AZAN — texte de la sounna affiché pendant toute la page azan
    //    • Toujours actif, même si le marquee normal est désactivé
    //    • Défile en boucle jusqu'à la fermeture de la page (auto ou manuelle)
    //    • Restaure l'état précédent (actif ou inactif) après fermeture
    // ─────────────────────────────────────────────────────────────────────
    var _AZAN_TICKER_HTML =
    'قال رسول الله ﷺ: ' +
    '«إذا سمعتم المؤذّن فقولوا مثل ما يقول، ' +
    'ثم صلّوا عليّ، فإنّه من صلّى عليّ ' +
    'صلاةً صلّى الله عليه بها عشرًا»' +
    '<span class="messageSeparatorClass">&bull;</span>' +
    'قال رسول الله ﷺ: ' +
    '«من قال حين يسمع النداء: اللّهمّ ' +
    'ربّ هذه الدّعوة التّامّة، ' +
    'والصّلاة القائمة، ' +
    'آتِ محمّدًا الوسيلة والفضيلة، ' +
    'وابعثه مقامًا محمودًا الذي وعدته، ' +
    'حلّت له شفاعتي يوم القيامة»' +
    '<span class="messageSeparatorClass">&bull;</span>' +
    'خلاصة : ' +
    '1. تردّد مع المؤذِن' +
    '&nbsp;&nbsp; 2. تقول «لا حول ولا قوّة إلّا بالله» عند «حيّ على...»' +
    '&nbsp;&nbsp; 3. تصلّي على النبيّ ﷺ' +
    '&nbsp;&nbsp; 4. تقول دعاء الوسيلة' +
    '&nbsp;&nbsp; 5. تدعو بما شئت (وقت مستجاب)';
    /*var _AZAN_TICKER_HTML =
        '\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \uFDFA: ' +
        '\u201C\u0625\u0630\u0627 \u0633\u0645\u0639\u062A\u0645 \u0627\u0644\u0645\u0624\u0630\u0651\u0646 \u0641\u0642\u0648\u0644\u0648\u0627 \u0645\u062B\u0644 \u0645\u0627 \u064A\u0642\u0648\u0644\u060C ' +
        '\u062B\u0645 \u0635\u0644\u0651\u0648\u0627 \u0639\u0644\u064A\u0651\u060C \u0641\u0625\u0646\u0651\u0647 \u0645\u0646 \u0635\u0644\u0651\u0649 \u0639\u0644\u064A\u0651 ' +
        '\u0635\u0644\u0627\u0629\u064B \u0635\u0644\u0651\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064A\u0647 \u0628\u0647\u0627 \u0639\u0634\u0631\u064B\u0627\u201D' +
        '<span class="messageSeparatorClass">&bull;</span>' +
        '\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \uFDFA: ' +
        '\u201C\u0645\u0646 \u0642\u0627\u0644 \u062D\u064A\u0646 \u064A\u0633\u0645\u0639 \u0627\u0644\u0646\u062F\u0627\u0621: \u0627\u0644\u0644\u0651\u0647\u0645\u0651 ' +
        '\u0631\u0628\u0651 \u0647\u0630\u0647 \u0627\u0644\u062F\u0651\u0639\u0648\u0629 \u0627\u0644\u062A\u0651\u0627\u0645\u0651\u0629\u060C ' +
        '\u0648\u0627\u0644\u0635\u0651\u0644\u0627\u0629 \u0627\u0644\u0642\u0627\u0626\u0645\u0629\u060C ' +
        '\u0622\u062A\u0650 \u0645\u062D\u0645\u0651\u062F\u064B\u0627 \u0627\u0644\u0648\u0633\u064A\u0644\u0629 \u0648\u0627\u0644\u0641\u0636\u064A\u0644\u0629\u060C ' +
        '\u0648\u0627\u0628\u0639\u062B\u0647 \u0645\u0642\u0627\u0645\u064B\u0627 \u0645\u062D\u0645\u0648\u062F\u064B\u0627 \u0627\u0644\u0630\u064A \u0648\u0639\u062F\u062A\u0647\u060C ' +
        '\u062D\u0644\u062A \u0644\u0647 \u0634\u0641\u0627\u0639\u062A\u064A \u064A\u0648\u0645 \u0627\u0644\u0642\u064A\u0627\u0645\u0629\u201D' +
        '<span class="messageSeparatorClass">&bull;</span>' +
        '\u062E\u0644\u0627\u0635\u0629 \u0633\u0647\u0644\u0629: ' +
        '1. \u062A\u0631\u062F\u062F \u0645\u0639 \u0627\u0644\u0645\u0624\u0630\u0650\u0646' +
        '&nbsp;&nbsp; 2. \u062A\u0642\u0648\u0644 \u201C\u0644\u0627 \u062D\u0648\u0644 \u0648\u0644\u0627 \u0642\u0648\u0651\u0629 \u0625\u0644\u0651\u0627 \u0628\u0627\u0644\u0644\u0647\u201D \u0639\u0646\u062F \u201C\u062D\u064A\u0651 \u0639\u0644\u0649...\u201D' +
        '&nbsp;&nbsp; 3. \u062A\u0635\u0644\u0651\u064A \u0639\u0644\u0649 \u0627\u0644\u0646\u0628\u064A\u0651 \uFDFA' +
        '&nbsp;&nbsp; 4. \u062A\u0642\u0648\u0644 \u062F\u0639\u0627\u0621 \u0627\u0644\u0648\u0633\u064A\u0644\u0629' +
        '&nbsp;&nbsp; 5. \u062A\u062F\u0639\u0648 \u0628\u0645\u0627 \u0634\u0626\u062A (\u0648\u0642\u062A \u0645\u0633\u062A\u062C\u0627\u0628)';
     */
   
    var _azanMarqueeActive = false;

    // Bloquer les appels à updateMarqueeDisplayFunction pendant l'azan
    var _origUpdateMarqueeDisplay = window.updateMarqueeDisplayFunction;
    window.updateMarqueeDisplayFunction = function() {
        if (_azanMarqueeActive) return;
        if (typeof _origUpdateMarqueeDisplay === 'function') _origUpdateMarqueeDisplay.apply(this, arguments);
    };

    function _showAzanTicker(prayer) {
        _azanMarqueeActive = true;
        stopMarqueeAnimation();

        var isHR       = (typeof isHorizontalOrientation !== 'undefined') ? isHorizontalOrientation : true;
        var containerId = isHR ? 'marqueeContainerHorizontal' : 'marqueeContainerVertical';
        var textId      = isHR ? 'marqueeTextHorizontal'      : 'marqueeTextVertical';

        var container = document.getElementById(containerId);
        if (!container) { _azanMarqueeActive = false; return; }

        container.innerHTML = '<div id="' + textId + '"></div>';
        var textEl = document.getElementById(textId);
        if (!textEl)  { _azanMarqueeActive = false; return; }
        textEl.innerHTML = _AZAN_TICKER_HTML;

        // Couleur du doaa : blanc fixe en vertical (qq soit la prière) ;
        // table par prière (window._getAzanColors) conservée en horizontal.
        var _azCfg = (typeof window._getAzanColors === 'function')
            ? window._getAzanColors(prayer) : null;
        if (_azCfg) {
            textEl.style.color      = isHR ? _azCfg.doa : '#FFFFFF';
            textEl.style.textShadow = _azCfg.doaShadow;
        }

        // Passer au-dessus du popup azan (z-index 99991) + taille agrandie
        container.style.display    = '';        // annule un eventuel display:none du countdown
        container.style.zIndex     = '99995';
        container.style.visibility = 'visible';
        container.classList.add('ucAzanLargeText');

        // Démarrer l'animation
        marqueeElement = textEl;
        setMarqueeDirection('right');   // texte arabe → défilement de droite à gauche (RTL)
        initMarqueePosition(textEl);
        startMarqueeAnimation();

        _L('POPUP','SHOW',{item:'marquee_azan'});
    }

    function _hideAzanTicker() {
        if (!_azanMarqueeActive) return;  // garde anti-double appel
        _azanMarqueeActive = false;
        stopMarqueeAnimation();

        // Remettre le z-index normal + taille normale des conteneurs
        var hrC = document.getElementById('marqueeContainerHorizontal');
        var vrC = document.getElementById('marqueeContainerVertical');
        if (hrC) { hrC.style.zIndex = ''; hrC.classList.remove('ucAzanLargeText'); }
        if (vrC) { vrC.style.zIndex = ''; vrC.classList.remove('ucAzanLargeText'); }

        // Restaurer la couleur d'origine du marquee (définie par le CSS)
        var htEl = document.getElementById('marqueeTextHorizontal');
        var vtEl = document.getElementById('marqueeTextVertical');
        [htEl, vtEl].forEach(function(el) {
            if (!el) return;
            el.style.color      = '';
            el.style.textShadow = '';
        });

        // Restaurer l'état normal (actif ou inactif selon les réglages)
        // Effacer le display:none inline avant la restauration
        var _hrC2 = document.getElementById('marqueeContainerHorizontal');
        var _vrC2 = document.getElementById('marqueeContainerVertical');
        if (_hrC2) _hrC2.style.display = '';
        if (_vrC2) _vrC2.style.display = '';
        if (typeof updateMarqueeText         === 'function') updateMarqueeText();
        if (typeof _origUpdateMarqueeDisplay === 'function') _origUpdateMarqueeDisplay.call(window);

        _L('POPUP','HIDE',{item:'marquee_azan'});
    }

    ucOn(UC_EVT.AZAN_SHOW, function(e) {
        if (e && e.isDohaPrayer) return;   // shuruq : pas de texte azan
        if (JS_DATA.ucShowAzanWindow == 0) return;   // popup masqué : rien à afficher
        _showAzanTicker(e && e.prayer ? e.prayer : '');
    });

    ucOn(UC_EVT.AZAN_HIDE, function() {
        _hideAzanTicker();
    });

    // ── Fermeture manuelle par clic sur le popup ───────────────────────────
    // Le popup azan a onclick='hideElementFunction(this.id)' qui bypasse
    // hideAzanPopupFunction() → AZAN_HIDE n'est jamais émis → on intercepte
    // hideElementFunction pour rattraper ce cas.
    // Garde-fou : _azanMarqueeActive évite le double appel quand c'est la
    // fermeture automatique (hideAzanPopupFunction appelle aussi hideElement).
    (function _interceptHideElementForAzan() {
        var _origHideEl = window.hideElementFunction;
        window.hideElementFunction = function(id) {
            _origHideEl.apply(this, arguments);
            if (_azanMarqueeActive &&
                (id === 'azanPopupHorizontal' || id === 'azanPopupVertical')) {
                _hideAzanTicker();
            }
        };
    })();

    // ──────────────────────────────────────────────────────────────────────
    // 4. Égaliseur animé dans la fenêtre AZAN pendant la lecture audio
    //    Barres blanches, même style CSS que customQuranIcon.
    // ──────────────────────────────────────────────────────────────────────
    (function _installAzanEqAnimation() {
        // Élément overlay indépendant : position:fixed, mêmes coords que customQuranIcon
        var _eq = document.createElement('div');
        _eq.id = 'azanEqOverlay';
        _eq.innerHTML =
            '<div class="azanEqBar"></div><div class="azanEqBar"></div>' +
            '<div class="azanEqBar"></div><div class="azanEqBar"></div>' +
            '<div class="azanEqBar"></div>';
        document.body.appendChild(_eq);

        function _syncPos() {
            var icon = document.getElementById('customQuranIcon');
            if (!icon) return;
            var r = icon.getBoundingClientRect();
            _eq.style.left   = r.left   + 'px';
            _eq.style.top    = r.top    + 'px';
            _eq.style.width  = r.width  + 'px';
            _eq.style.height = r.height + 'px';
        }

        function _setAzanEq(on) {
            if (on) { _syncPos(); _eq.classList.add('azanEqActive'); }
            else    { _eq.classList.remove('azanEqActive'); }
        }

        function _attachAzanAudio(el) {
            if (!el) return;
            el.addEventListener('playing', function() { _setAzanEq(true);  });
            el.addEventListener('pause',   function() { _setAzanEq(false); });
            el.addEventListener('ended',   function() { _setAzanEq(false); });
            el.addEventListener('error',   function() { _setAzanEq(false); });
        }

        _attachAzanAudio(document.getElementById('audioAzanElement'));
        _attachAzanAudio(document.getElementById('audioFajrElement'));
    })();

    // -----------------------------------------------------------------
    // 5. Arret audio azan a la fermeture de la popup (toutes causes)
    //    - UC_EVT.AZAN_HIDE : chemin normal (audio termine, safety timeout)
    //    - hideElementFunction patch : clic direct sur popup Android/web
    //      qui bypasse hideAzanPopupFunction() et n'emet pas AZAN_HIDE.
    //    Idempotent : el.paused == true -> aucune action.
    // -----------------------------------------------------------------
    (function _installAzanAudioForceStop() {
        var _AZAN_POPUP_IDS = { 'azanPopupVertical': 1, 'azanPopupHorizontal': 1 };

        // Une meme fermeture de popup declenche _stopAzanAudio jusqu'a 3 fois
        // (AZAN_HIDE + hideElementFunction sur azanPopupVertical ET
        // azanPopupHorizontal), quasi simultanement -- avant, chacun logguait
        // sa propre ligne (3 lignes [AUDIO] pour 1 seule fermeture reelle,
        // et jusqu'a 3 appels stopAzanPlayback natifs pour rien). Le nettoyage
        // (pause audio, stop natif) reste execute a chaque appel -- idempotent,
        // donc sans risque -- seul le LOG est deduplique, pour qu'une fermeture
        // = une ligne dans le journal.
        var _lastStopLogAt = 0;
        var _STOP_DEDUP_MS = 500;

        function _stopAzanAudio(reason) {
            var stoppedEls = [];
            ['audioAzanElement', 'audioFajrElement'].forEach(function(id) {
                var el = document.getElementById(id);
                if (el && !el.paused) {
                    try { el.pause(); el.currentTime = 0; } catch(e) {}
                    stoppedEls.push(id);
                }
            });
            // Coupe aussi la lecture NATIVE de l'azan (AzanPlaybackService,
            // MediaPlayer natif utilise pour que l'azan sonne meme appli en
            // arriere-plan) : sans cet appel, seul le bouton "Arreter" de la
            // notification pouvait la stopper -- fermer la popup dans l'appli
            // ne faisait rien cote natif. prayer/source transmis pour que
            // NATIVE_STOP_USER (journal natif) distingue cette source du
            // bouton "Arreter" de la notification (cf. AzanPlaybackService.kt).
            var nativeStopIssued = false;
            if (window.AndroidMobile && typeof window.AndroidMobile.stopAzanPlayback === 'function') {
                window.AndroidMobile.stopAzanPlayback(_ucPrayerAtMinutes(currentTimeInMinutes), 'webview_popup_close');
                nativeStopIssued = true;
            }
            // Nettoyer l'etat du bloc pour eviter un blocage futur
            _ucBlockAzanHide   = false;
            _ucLastAzanAudioEl = null;
            if (_ucAzanSafetyTimer) {
                clearTimeout(_ucAzanSafetyTimer);
                _ucAzanSafetyTimer = null;
            }

            var now = Date.now();
            if (now - _lastStopLogAt > _STOP_DEDUP_MS) {
                _lastStopLogAt = now;
                _L('AZAN', stoppedEls.length ? 'WEBVIEW_STOP' : 'WEBVIEW_STOP_NOOP', {
                    reason: reason,
                    elements: stoppedEls.join(',') || 'none_playing',
                    nativeStopIssued: nativeStopIssued
                });
            }
        }

        // Chemin 1 : AZAN_HIDE emis par hideAzanPopupFunction (flux normal)
        ucOn(UC_EVT.AZAN_HIDE, function() {
            _stopAzanAudio('azan_hide_event');
        });

        // Chemin 2 : clic direct popup -> hideElementFunction bypasse tout
        var _origHideEl = window.hideElementFunction;
        if (typeof _origHideEl === 'function') {
            window.hideElementFunction = function(id) {
                _origHideEl.apply(this, arguments);
                if (_AZAN_POPUP_IDS[id]) {
                    _stopAzanAudio('direct_close_' + id);
                }
            };
            _L('SYS','PATCH',{fn:'hideElementFunction',
                               for:'azan_audio_force_stop'});
        }
    })();

})();


// ═══════════════════════════════════════════════════════════════════════════
// ── MARQUEE CSS FLUIDE : anime le bandeau défilant (page principale ET
//    ticker azan, m2body.js/custom.js réutilisent les mêmes fonctions
//    globales) via une animation CSS @keyframes plutôt que le
//    requestAnimationFrame + réécriture de style.transform du core.
//
//    Constat (retour utilisateur, boîtier TV) : léger saccadé visible malgré
//    le translate3d+rAF déjà en place côté core. Cause : même avec un calcul
//    de vitesse correct (delta-temps, cf. m2body.js animateMarquee), cette
//    animation reste pilotée PAR LE THREAD JS PRINCIPAL -- chaque frame doit
//    repasser par un callback JS qui réécrit .style.transform. Le moindre
//    à-coup de ce thread (tick d'horloge chaque seconde, mise à jour d'un
//    autre overlay, etc.) retarde le prochain rAF -> le pas de position
//    suivant est plus grand que la normale -> saccade visible, même si la
//    vitesse MOYENNE reste juste.
//    Une animation CSS @keyframes est calculée par le thread de composition,
//    totalement indépendant du thread JS une fois démarrée : aucune saccade
//    tant que le JS ne bloque pas le rendu lui-même (repaint complet, rare).
//    Remplace entièrement initMarqueePosition/startMarqueeAnimation/
//    stopMarqueeAnimation (identifiants globaux du core, cf. Golden Rule —
//    on ne modifie jamais m2body.js) ; animateMarquee (rAF) n'a alors plus
//    aucun appelant, laissée intacte mais inerte.
// ═══════════════════════════════════════════════════════════════════════════
(function _installSmoothMarqueeCss() {
    var _styleEl = document.createElement('style');
    _styleEl.textContent =
        '@keyframes ucMarqueeSlide {' +
        '  from { transform: translate3d(var(--uc-mq-start, 0px), 0, 0); }' +
        '  to   { transform: translate3d(var(--uc-mq-end, 0px), 0, 0); }' +
        '}';
    document.head.appendChild(_styleEl);

    window.initMarqueePosition = function(el) {
        if (!el) return;
        var parentContainer = el.parentElement;
        if (!parentContainer) return;

        el.style.display    = 'inline-block';
        el.style.whiteSpace = 'nowrap';
        el.style.overflow   = 'visible';
        el.style.willChange = 'transform';
        parentContainer.style.overflow = 'hidden';

        // Variables globales du core (let, portée script partagée) réutilisées
        // telles quelles par le reste de l'appli -- cf. _showAzanTicker qui lit
        // directement marqueeElement.
        marqueeElement = el;
        marqueeWidth   = el.offsetWidth;
        containerWidth = parentContainer.offsetWidth;

        var startPx = (marqueeDirection === 'left') ? containerWidth : -marqueeWidth;
        var endPx   = (marqueeDirection === 'left') ? -marqueeWidth  : containerWidth;

        el.style.animation = 'none';   // reset avant repose des variables (evite un saut si deja anime)
        el.style.setProperty('--uc-mq-start', startPx + 'px');
        el.style.setProperty('--uc-mq-end',   endPx   + 'px');
        el.style.transform = 'translate3d(' + startPx + 'px, 0, 0)';   // position de depart avant meme le demarrage
    };

    window.startMarqueeAnimation = function() {
        if (!marqueeElement) return;
        var distance = containerWidth + marqueeWidth;
        var speed    = JS_DATA.ucMovingMessagesSpeed || 55;   // px/s, cf. settings-defaults.js (40-70)
        var duration = distance / speed;
        if (!isFinite(duration) || duration <= 0) duration = 15;
        marqueeElement.style.animation = 'ucMarqueeSlide ' + duration.toFixed(2) + 's linear infinite';
    };

    window.stopMarqueeAnimation = function() {
        if (marqueeElement) marqueeElement.style.animation = 'none';
    };

    _L('SYS', 'PATCH', {fn: 'initMarqueePosition/startMarqueeAnimation/stopMarqueeAnimation',
        for: 'smooth_css_marquee'});
})();


// ═══════════════════════════════════════════════════════════════════════════
// ── HADITH IQAMA OVERLAY : plein écran, fond semi-transparent, fondu sortie
// ═══════════════════════════════════════════════════════════════════════════
//
//  Remplace l'affichage d'origine (staticMessageDisplay) par un overlay
//  plein écran qui :
//    • Apparaît à remainingSeconds == 58 (si ucIqamaHadith == 1)
//    • Disparaît en fondu à remainingSeconds == 40
//    • Fond noir semi-transparent (le compte à rebours reste vaguement visible)
//    • Texte blanc fluorescent (glow CSS) sur 3 lignes
//
// ═══════════════════════════════════════════════════════════════════════════
(function _installIqamaHadithOverlay() {

    // ── Injection CSS ─────────────────────────────────────────────────────
    var _css = document.createElement('style');
    _css.id  = 'ucIqamaHadithStyle';
    _css.textContent =
        '#ucIqamaHadithOverlay {' +
        '    position: fixed;' +
        '    top: 0; left: 0; right: 0; bottom: 0;' +
        '    z-index: 99995;' +           /* au-dessus de tout sauf debug console */
        '    display: flex;' +
        '    flex-direction: column;' +
        '    align-items: center;' +
        '    justify-content: center;' +
        '    text-align: center;' +
        '    direction: rtl;' +
        '    background: rgba(0,0,0,0.95);' +  /* fond noir 93 % opaque  */
        '    opacity: 0;' +
        '    pointer-events: none;' +
        '    transition: opacity 0.7s ease-in;' +
        '}' +
        '#ucIqamaHadithOverlay.ucIH-visible {' +
        '    opacity: 1;' +
        '    pointer-events: auto;' +
        '}' +
        '#ucIqamaHadithOverlay.ucIH-fading {' +
        '    opacity: 0 !important;' +
        '    transition: opacity 1.8s ease-out;' +
        '}' +
        '#ucIqamaHadithBox {' +
        '    display: flex;' +
        '    flex-direction: column;' +
        '    align-items: center;' +
        '    gap: 1.7em;' +
        '    padding: 3em 4em;' +
        '    width: 90vw;' +
        '}' +
        '.ucIH-line1 {' +       /* « قال رسول الله ﷺ » */
        '    font-family: var(--csvar_mainFONT), serif;' +
        '    font-size: 5vw;' +
        '    font-weight: 600;' +
        '    color: #f39e0b;' +                /* or islamique chaud */
        '    text-shadow: 0 0 18px rgba(211, 165, 85, 0.55);' +
        '    letter-spacing: 0.06em;' +
        '    text-align: center;' +
        '    width: 100%;' +
        '}' +
        '.ucIH-line2 {' +       /* texte principal du hadith */
        '    font-family: var(--csvar_mainFONT), serif;' +
        '    font-size: 5.5vw;' +
        '    font-weight: 700;' +
        '    color: #f5f0e8;' +                /* blanc ivoire — lecture confortable */
        '    line-height: 1.55;' +
        '    text-shadow: 0 1px 6px rgba(0,0,0,0.8);' + /* ombre portée discrète */
        '    letter-spacing: 0.03em;' +
        '    text-align: center;' +
        '    width: 100%;' +
        '}' +
        '.ucIH-line3 {' +       /* « رواه البخاري و مسلم » */
        '    font-family: var(--csvar_mainFONT), serif;' +
        '    font-size: 3.0vw;' +
        '    font-weight: 400;' +
        '    color: #a89060;' +                /* or atténué pour l attribution */
        '    text-shadow: none;' +
        '    letter-spacing: 0.08em;' +
        '    opacity: 0.85;' +
        '    text-align: center;' +
        '    width: 100%;' +
        '}';
    document.head.appendChild(_css);

    // ── Injection DOM ─────────────────────────────────────────────────────
    var _overlay = document.createElement('div');
    _overlay.id  = 'ucIqamaHadithOverlay';
    _overlay.innerHTML =
        '<div id="ucIqamaHadithBox">' +
        '<div class="ucIH-line1">' +
            '\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \uFDFA' +
        '</div>' +
        '<div class="ucIH-line2">' +
            '\u0625\u0630\u0627 \u0623\u064F\u0642\u064A\u0645\u062A\u0020' +
            '\u0627\u0644\u0635\u0644\u0627\u0629\u064F\u0020' +
            '\u0641\u0644\u0627 \u062A\u0642\u0648\u0645\u0648\u0627\u0020' +
            '\u062D\u062A\u0649 \u062A\u0631\u0648\u0646\u064A\u0020' +
            '\u0642\u062F \u062E\u0631\u062C\u062A\u064F' +
        '</div>' +
        '<div class="ucIH-line3">' +
            '\u0631\u0648\u0627\u0647 \u0627\u0644\u0628\u062E\u0627\u0631\u064A\u0020' +
            '\u0645\u0633\u0644\u0645' +
        '</div>' +
        '</div>';
    document.body.appendChild(_overlay);

    // ── État interne ──────────────────────────────────────────────────────
    var _visible    = false;
    var _fadeTimer  = null;
    _ucRegisterCleanup(function() {
        if (_fadeTimer) { clearTimeout(_fadeTimer); _fadeTimer = null; }
    });

    function _show() {
        if (_visible) return;
        _visible = true;
        if (_fadeTimer) { clearTimeout(_fadeTimer); _fadeTimer = null; }
        _overlay.classList.remove('ucIH-fading');
        _overlay.classList.add('ucIH-visible');
        _L('POPUP','SHOW',{item:'hadith_iqama',trigger:'58s'});
    }

    function _startFade() {
        if (!_visible) return;
        _overlay.classList.remove('ucIH-visible');
        _overlay.classList.add('ucIH-fading');
        if (_fadeTimer) clearTimeout(_fadeTimer);
        _fadeTimer = setTimeout(function() {
            _overlay.classList.remove('ucIH-fading');
            _visible   = false;
            _fadeTimer = null;
            _L('POPUP','HIDE',{item:'hadith_iqama'});
        }, 2000);
    }

    function _forceHide() {
        if (_fadeTimer) { clearTimeout(_fadeTimer); _fadeTimer = null; }
        _overlay.classList.remove('ucIH-visible', 'ucIH-fading');
        _visible = false;
    }

    // ── Intercepter l'affichage d'origine (évite que staticMessage
    //    masque le marquee / hadith pendant 30 s inutilement) ──────────────
    var _origShowStaticMsg = window.showStaticMessageFunction;
    window.showStaticMessageFunction = function(msg) {
        if (_visible &&
            typeof JS_IqamaRULE !== 'undefined' &&
            msg === JS_IqamaRULE)
        {
            return;   // notre overlay gère cet affichage, ignorer l'original
        }
        if (typeof _origShowStaticMsg === 'function')
            _origShowStaticMsg.apply(this, arguments);
    };

    // ── Écoute du compte à rebours ────────────────────────────────────────
    ucOn(UC_EVT.COUNTDOWN_TICK, function(e) {
        if (JS_DATA.ucIqamaHadith != 1)                              return;
        if (typeof isDohaCounter !== 'undefined' && isDohaCounter)   return;

        var s = e.remainingSeconds;
        if      (s === 58) { _show();      }
        else if (s === 40) { _startFade(); }
    });

    // ── Sécurité : masquer dès que l'iqama démarre réellement ─────────────
    ucOn(UC_EVT.IQAMA_SHOW, function() {
        if (_visible) _startFade();
    });

    // ── Sécurité : réinitialiser entre deux prières ───────────────────────
    ucOn(UC_EVT.AZAN_TIME, function() {
        _forceHide();
    });

})();


// ═══════════════════════════════════════════════════════════════════════════
// ── ATHAN MINUTES RANGE : ±60 → ±300 ────────────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════════
//
//  Monkey-patch de decrementAthanMinutesFunction et incrementAthanMinutesFunction
//  pour étendre les limites de ±60 à ±300 minutes.
//
// ═══════════════════════════════════════════════════════════════════════════
(function _extendAthanMinutesRange() {

    var MAX = 300;

    // ── Table prayer key → {setting, displayElement} ─────────────────────
    var _map = {
        'FAJR'   : { key: 'ucAthanMinutesFAJR', el: function() { return athanFajrValueElement; } },
        'SHRQ'   : { key: 'ucAthanMinutesSHRQ', el: function() { return athanShrqValueElement; } },
        'DOHR'   : { key: 'ucAthanMinutesDOHR', el: function() { return athanDohrValueElement; } },
        'ASR'    : { key: 'ucAthanMinutesASSR', el: function() { return athanAsrValueElement;  } },
        'MAGHRIB': { key: 'ucAthanMinutesMGRB', el: function() { return athanMgrbValueElement; } },
        'ISHA'   : { key: 'ucAthanMinutesISHA', el: function() { return athanIshaValueElement; } }
    };

    // ── Nouvelle implémentation commune ──────────────────────────────────
    function _adjust(prayerKey, delta) {
        var entry = _map[prayerKey];
        if (!entry) return false;   // clé inconnue → laisser l'original gérer

        var val = JS_DATA[entry.key] + delta;
        if (val < -MAX) val = -MAX;
        if (val >  MAX) val =  MAX;
        JS_DATA[entry.key] = val;
        entry.el().innerHTML = val;
        saveSettingsToStorageFunction();
        calculateAndDisplayTimesFunction();
        return true;
    }

    // ── Remplacement de decrementAthanMinutesFunction ────────────────────
    window.decrementAthanMinutesFunction = function(prayerKey) {
        if (!_adjust(prayerKey, -1)) {
            // Clé non gérée : appel de l'originale pour ne rien casser
            console.warn('[EVT] decrementAthanMinutes: clé inconnue →', prayerKey);
        }
    };

    // ── Remplacement de incrementAthanMinutesFunction ────────────────────
    window.incrementAthanMinutesFunction = function(prayerKey) {
        if (!_adjust(prayerKey, +1)) {
            console.warn('[EVT] incrementAthanMinutes: clé inconnue →', prayerKey);
        }
    };

    

})();


// ═══════════════════════════════════════════════════════════════════════════
// AUTO-MASQUAGE DES ICONES LATERALES (speaker + coran)
// Les icones disparaissent pendant : azan, compteurs, hadith iqama,
// page iqama, ecran noir, pages azkar.
// ═══════════════════════════════════════════════════════════════════════════
(function() {
    'use strict';

    var _reasons = {};

    function _set(reason, active) {
        if (active) {
            _reasons[reason] = true;
        } else {
            delete _reasons[reason];
        }
        _apply();
    }

    function _apply() {
        var mustHide = Object.keys(_reasons).length > 0;
        var sp = document.getElementById('customSpeakerIcon');
        var qr = document.getElementById('customQuranIcon');
        if (mustHide) {
            if (sp) { sp.style.visibility = 'hidden'; }
            if (qr) { qr.style.visibility = 'hidden'; }
        } else {
            if (typeof applyCustomIconsVisibility === 'function') {
                applyCustomIconsVisibility();
            }
        }
    }

    // Surveille la classe CSS d'un element : si activeClass presente -> hide
    function _watchClass(elId, activeClass, reason) {
        var el = document.getElementById(elId);
        if (!el) { return; }
        var obs = new MutationObserver(function() {
            _set(reason, el.classList.contains(activeClass));
        });
        obs.observe(el, { attributes: true, attributeFilter: ['class'] });
    }

    // Surveille style.transform : scaleX(1) = ecran noir actif
    function _watchTransform(elId, reason) {
        var el = document.getElementById(elId);
        if (!el) { return; }
        var obs = new MutationObserver(function() {
            var t = el.style.transform || '';
            _set(reason, t !== '' && t.indexOf('scaleX(0)') === -1);
        });
        obs.observe(el, { attributes: true, attributeFilter: ['style'] });
    }

    // 1. Page AZAN
    _watchClass('azanPopupHorizontal', 'visibleTransitionClass', 'azan_hr');
    _watchClass('azanPopupVertical',   'visibleTransitionClass', 'azan_vr');

    // 2a. Compteur plein ecran iqama
    _watchClass('fullScreenCounterContainerHorizontal', 'fullScreenVisibleClass', 'ctr_fs_hr');
    _watchClass('fullScreenCounterContainerVertical',   'fullScreenVisibleClass', 'ctr_fs_vr');

    // 2b. Compteur secondes (<= 59 s)
    _watchClass('secondCounterContainerHorizontal', 'visibleTransitionClass', 'ctr_sec_hr');
    _watchClass('secondCounterContainerVertical',   'visibleTransitionClass', 'ctr_sec_vr');

    // 2c. Compteur iqama secondaire
    _watchClass('iqamaCounterContainerHorizontal', 'visibleTransitionClass', 'ctr_iq_hr');
    _watchClass('iqamaCounterContainerVertical',   'visibleTransitionClass', 'ctr_iq_vr');

    // 3. Overlay hadith iqama (cree dynamiquement : on attend son insertion)
    function _watchHadithOverlay() {
        var el = document.getElementById('ucIqamaHadithOverlay');
        if (!el) { return; }
        var obs = new MutationObserver(function() {
            _set('hadith', el.classList.contains('ucIH-visible'));
        });
        obs.observe(el, { attributes: true, attributeFilter: ['class'] });
    }
    if (document.getElementById('ucIqamaHadithOverlay')) {
        _watchHadithOverlay();
    } else {
        var bodyObs = new MutationObserver(function() {
            if (document.getElementById('ucIqamaHadithOverlay')) {
                bodyObs.disconnect();
                _watchHadithOverlay();
            }
        });
        bodyObs.observe(document.body, { childList: true });
    }

    // 4. Page iqama
    _watchClass('iqamaPopupHorizontal', 'visibleTransitionClass', 'iqama_hr');
    _watchClass('iqamaPopupVertical',   'visibleTransitionClass', 'iqama_vr');

    // 5. Ecran noir
    _watchTransform('blackScreenHorizontal', 'black_hr');
    _watchTransform('blackScreenVertical',   'black_vr');

    // 6. Pages azkar
    _watchClass('azkarContainerHorizontal', 'fullScreenVisibleClass', 'azkar_hr');
    _watchClass('azkarContainerVertical',   'fullScreenVisibleClass', 'azkar_vr');


}());

// ── Masquer le tableau des horaires dès l'apparition du rideau noir
// (BLACK_SHOW), et le garder masqué jusqu'au PROCHAIN vrai azan (AZAN_SHOW)
// -- PAS jusqu'à BLACK_HIDE. #blackScreenHorizontal/Vertical (style0.css) a
// une transition CSS de 5s (balayage façon rideau) : sans hook sur BLACK_SHOW,
// le tableau restait visible EN DESSOUS pendant tout le balayage. Mais
// restaurer sur BLACK_HIDE était incorrect : après Isha (et plus généralement
// après n'importe quelle prière), le rideau se lève rapidement puis
// displayNextAzkarFunction()/decideNextAzkarOrSlideFunction() (m2body.js)
// enchaînent les azkar/slides EN BOUCLE INDÉFINIE (toute la nuit jusqu'au
// prochain azan), avec une pause de 7s entre chaque cycle complet où l'écran
// principal redevient visible -- BLACK_HIDE étant déjà passé, le tableau
// réapparaissait alors, superposé, à chacune de ces pauses (signalé par
// l'utilisateur : visible "durant la période d'affichage des azkar... quand
// l'écran principal est visible"). Le tableau doit donc rester masqué tout du
// long de cette période post-salat, jusqu'à ce qu'un nouveau cycle de prière
// réel commence.
(function _installBlackScreenHidesPrayerTable() {
    var _containers = ['prayerTimesContainerHorizontal', 'prayerTimesContainerVertical'];
    function _restoreTable() {
        _containers.forEach(function (id) {
            var el = document.getElementById(id);
            if (el) el.style.visibility = 'visible';
        });
    }
    ucOn(UC_EVT.BLACK_SHOW, function () {
        _containers.forEach(function (id) {
            var el = document.getElementById(id);
            if (el) el.style.visibility = 'hidden';
        });
    });
    ucOn(UC_EVT.AZAN_SHOW, _restoreTable);

    // Bug rapporté (retour utilisateur, 27/07/2026) : fermeture MANUELLE du
    // rideau noir (clic dessus -> index.html onclick='deactivateBlackScreen()',
    // appel DIRECT qui ne passe PAS par onIqamaEndFunction()/la chaîne azkar)
    // -- le tableau restait masqué jusqu'au PROCHAIN azan réel (des heures
    // plus tard), laissant l'utilisateur face à une page incomplète au lieu
    // de la page principale. Non couvert par la restauration ci-dessus (liée
    // à AZAN_SHOW uniquement, volontairement -- cf. commentaire plus haut sur
    // le risque de superposition pendant la boucle azkar). Sans danger de
    // resuperposition ici : à ce stade, soit rien d'autre ne recouvre encore
    // l'écran (le tableau DOIT être visible), soit l'azkar plein écran suit
    // sous peu et le recouvre entièrement (aucune superposition possible,
    // contrairement au problème d'origine qui concernait la barre "mini" --
    // déjà gérée séparément par _installAzkarMainPageInterlude).
    var _origDeactivateBlackScreen = window.deactivateBlackScreen;
    if (typeof _origDeactivateBlackScreen === 'function') {
        window.deactivateBlackScreen = function () {
            _origDeactivateBlackScreen.apply(this, arguments);
            _restoreTable();
        };
    }
})();

// ── FIX : compteur iqama parfois invisible après la fin de l'azan (bug
//    rapporté 27/07/2026 mosquée "يوسف", récidive 28/07/2026 boîtier Z6).
//
//    Cause réelle, identifiée en lisant ensemble _ucResyncPrayerSequence
//    (_installResyncOnResume, plus haut dans ce fichier) et le cœur
//    (m2body.js checkAndRestoreIqamaCounter, ~L8233) :
//
//    1) showAzanPopup() (m2body.js) affiche normalement le compteur de façon
//       SYNCHRONE, sous le popup azan, dans le même tick que
//       startIqamaCounterFunction() -- ce chemin est fiable, pas de course.
//    2) _ucResyncPrayerSequence (déclenché par tout retour au premier plan
//       après >=5s en arrière-plan -- visibilitychange OU onResume natif,
//       cf. MainActivity.maybeTriggerJsResync) force INCONDITIONNELLEMENT
//       isIqamaCounterActive=false et masque les conteneurs du compteur,
//       PUIS appelle checkAndRestoreIqamaCounter() pour tout remettre en
//       place si une fenêtre d'iqama est réellement en cours.
//    3) BUG CŒUR : chaque cas de checkAndRestoreIqamaCounter() compare avec
//       ">" strict (jamais ">="). Si ce resync se déclenche pendant la
//       MÊME minute d'horloge que le début de l'azan (fenêtre d'environ 60s
//       -- largement atteignable : l'azan natif joue 1 à 4+ minutes, et
//       n'importe quel blip onPause/onResume du boîtier TV pendant ce
//       laps -- évènement CEC, launcher qui reprend brièvement la main,
//       pression mémoire -- suffit à déclencher le resync), AUCUN cas ne
//       correspond : rien ne rappelle startIqamaCounterFunction()/
//       showIqamaCounter(). Le compteur reste effacé pour tout le reste du
//       cycle -- y compris à la fermeture du popup azan, qui n'a alors plus
//       rien à révéler en dessous. Explique le caractère intermittent
//       (dépend d'un timing précis) sans exiger un reload -- corrigé ici en
//       comblant nous-mêmes ce seul angle mort (égalité exacte), avec les
//       mêmes paramètres que le cœur utilise pour chaque prière.
(function _installIqamaCounterExactMinuteRestoreFix() {
    if (typeof window.checkAndRestoreIqamaCounter !== 'function') return;
    var _origCheckRestore = window.checkAndRestoreIqamaCounter;
    window.checkAndRestoreIqamaCounter = function () {
        _origCheckRestore.apply(this, arguments);
        // Déjà restauré normalement par le cœur (un des cas ">" a matché) : rien à faire.
        if (typeof isIqamaCounterActive !== 'undefined' && isIqamaCounterActive) return;
        if (typeof currentTimeInMinutes === 'undefined') return;
        var _restoredPrayer = null;
        if (currentTimeInMinutes === fajrTimeInMinutes && JS_DATA.ucIqamaFAJR > 0) {
            startIqamaCounterFunction(JS_DATA.ucIqamaFAJR, JS_DATA.ucPrayDurationFAJR, JS_DATA.ucIqamaFAJR);
            positionHighlightBar(prayerRowFajrVerticalElement, prayerCellFajrHorizontalElement);
            _restoredPrayer = 'FAJR';
        } else if (currentTimeInMinutes === shuruqTimeInMinutes && JS_DATA.ucIqamaSHRQ > 0) {
            startIqamaCounterFunction(JS_DATA.ucIqamaSHRQ, 0, JS_DATA.ucIqamaSHRQ);
            positionHighlightBar(prayerRowShrqVerticalElement, prayerCellShrqHorizontalElement);
            _restoredPrayer = 'SHRQ';
        } else if (currentTimeInMinutes === dohrTimeInMinutes && JS_DATA.ucIqamaDOHR > 0) {
            startIqamaCounterFunction(JS_DATA.ucIqamaDOHR, JS_DATA.ucIqamaDOHR, JS_DATA.ucIqamaDOHR);
            positionHighlightBar(prayerRowDohrVerticalElement, prayerCellDohrHorizontalElement);
            _restoredPrayer = 'DOHR';
        } else if (currentTimeInMinutes === asrTimeInMinutes && JS_DATA.ucIqamaASSR > 0) {
            startIqamaCounterFunction(JS_DATA.ucIqamaASSR, JS_DATA.ucIqamaASSR, JS_DATA.ucIqamaASSR);
            positionHighlightBar(prayerRowAsrVerticalElement, prayerCellAsrHorizontalElement);
            _restoredPrayer = 'ASSR';
        } else if (currentTimeInMinutes === maghribTimeInMinutes && JS_DATA.ucIqamaMGRB > 0) {
            startIqamaCounterFunction(JS_DATA.ucIqamaMGRB, JS_DATA.ucIqamaMGRB, JS_DATA.ucIqamaMGRB);
            positionHighlightBar(prayerRowMgrbVerticalElement, prayerCellMgrbHorizontalElement);
            _restoredPrayer = 'MGRB';
        } else if (currentTimeInMinutes === ishaTimeInMinutes && JS_DATA.ucIqamaISHA > 0) {
            startIqamaCounterFunction(JS_DATA.ucIqamaISHA, JS_DATA.ucPrayDurationISHA, JS_DATA.ucIqamaISHA);
            positionHighlightBar(prayerRowIshaVerticalElement, prayerCellIshaHorizontalElement);
            _restoredPrayer = 'ISHA';
        }
        if (_restoredPrayer) {
            showIqamaCounter();
            _L('RESYNC', 'COUNTER_EXACT_MINUTE_RESTORE', { prayer: _restoredPrayer, currentTimeInMinutes: currentTimeInMinutes });
        }
    };
})();

// ── DIAGNOSTIC : trace l'état des conteneurs à chaque appel de
//    showIqamaCounter() -- conservé après le fix ci-dessus pour confirmer en
//    conditions réelles qu'aucun autre chemin ne reproduit encore le
//    symptôme (bug rapporté 27/07/2026, 28/07/2026).
(function _installIqamaCounterVisibilityDiag() {
    if (typeof window.showIqamaCounter !== 'function') return;
    var _origShowIqamaCounter = window.showIqamaCounter;
    window.showIqamaCounter = function () {
        _origShowIqamaCounter.apply(this, arguments);
        var fsV = document.getElementById('fullScreenCounterContainerVertical');
        var fsH = document.getElementById('fullScreenCounterContainerHorizontal');
        var icV = document.getElementById('iqamaCounterContainerVertical');
        var icH = document.getElementById('iqamaCounterContainerHorizontal');
        _L('DIAG', 'SHOW_IQAMA_COUNTER', {
            isFullScreenCounterMode: (typeof isFullScreenCounterMode !== 'undefined') ? isFullScreenCounterMode : 'undef',
            isIqamaCounterActive:    (typeof isIqamaCounterActive    !== 'undefined') ? isIqamaCounterActive    : 'undef',
            fsV: fsV && fsV.className, fsH: fsH && fsH.className,
            icV: icV && icV.className, icH: icH && icH.className
        });
    };
})();

/* ═══════════════════════════════════════════════════════════════════════════
   SÉQUENCE HADITH AVANT IQAMA
   • 58s → 40s : nouveau hadith (marche vers la prière) via ucIqamaHadithOverlay
   • 30s → 20s : hadith original (JS_IqamaRULE) via staticMessageDisplay
   ═══════════════════════════════════════════════════════════════════════════ */
(function () {
    /* ── ① Remplacer le texte de l'overlay existant par le nouveau hadith ── */
    var HADITH_33_LINE1 = "قالَ رسولُ اللهِ \uFDFA";
    var HADITH_33_LINE2 = "إذا أُقيمتِ الصلاةُ فلا تأتوها تسعون، وأتوها تمشون، عليكم السكينة، فما أدركتم فصلّوا، وما فاتكم فأتمّوا";
    var HADITH_33_LINE3 = "رواه البخاري و مسلم";

    function _updateOverlayText() {
        var box = document.getElementById('ucIqamaHadithOverlay');
        if (!box) return;
        var l1 = box.querySelector('.ucIH-line1');
        var l2 = box.querySelector('.ucIH-line2');
        var l3 = box.querySelector('.ucIH-line3');
        if (l1) l1.textContent = HADITH_33_LINE1;
        if (l2) l2.textContent = HADITH_33_LINE2;
        if (l3) l3.textContent = HADITH_33_LINE3;
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', _updateOverlayText);
    } else {
        _updateOverlayText();
    }

    /* ── ② Overlay dédié 30s→20s (position:fixed, au-dessus de tout) ───── */
    /* Overlay plein écran avec fond opaque — même style que ucIqamaHadithOverlay */
    var _ov15 = document.createElement('div');
    _ov15.id = 'ucIqama15sOverlay';
    _ov15.style.cssText = [
        'position:fixed', 'inset:0', 'z-index:19999',
        'display:flex', 'align-items:flex-start', 'justify-content:center',
        'padding-top:12%',
        'pointer-events:none', 'opacity:0',
        'transition:opacity 0.4s ease',
        'background:rgba(0,0,0,0.94)',
        'direction:rtl'
    ].join(';');

    _ov15.innerHTML =
        '<div id="ucIqama15sBox" style="display:flex;flex-direction:column;align-items:center;gap:1.7em;padding:3em 4em;width:90vw;text-align:center;">' +
            '<div class="ucIH-line1">قالَ رسولُ اللهِ \uFDFA</div>' +
            '<div id="ucIqama15sText" class="ucIH-line2"></div>' +
            '<div class="ucIH-line3">رواه البخاري و مسلم</div>' +
        '</div>';

    document.body.appendChild(_ov15);

    function _show15() {
        var txt = typeof JS_IqamaRULE === 'string'
            ? JS_IqamaRULE.replace(/^قالَ\s*ﷺ\s*:\s*/u, '').trim()
            : JS_IqamaRULE;
        document.getElementById('ucIqama15sText').textContent = txt;
        _ov15.style.opacity = '1';
        _L('POPUP','SHOW',{item:'hadith_15s'});
    }
    function _hide15() {
        _ov15.style.opacity = '0';
        _L('POPUP','HIDE',{item:'hadith_15s'});
    }

    ucOn(UC_EVT.COUNTDOWN_TICK, function (e) {
        if (JS_DATA.ucIqamaHadith != 1) return;
        if (typeof isDohaCounter !== 'undefined' && isDohaCounter) return;
        if (e.remainingSeconds === 30) _show15();
        if (e.remainingSeconds === 20) _hide15();
    });

    /* Reset à chaque nouveau cycle azan */
    ucOn(UC_EVT.AZAN_TIME, function () { _ov15.style.opacity = '0'; });
}());

/* ═══════════════════════════════════════════════════════════════════════════
   LABEL "الأرقام العربية" -> "الأرقام الهندية" (terminologie correcte : les
   chiffres ٠١٢٣٤٥٦٧٨٩ sont appelés "الأرقام الهندية" en arabe ; "الأرقام
   العربية" désigne en réalité les chiffres 0123456789). Arabe uniquement —
   les autres langues (EN, FR...) restent inchangées, leur formulation est
   correcte dans leur propre langue.
   ═══════════════════════════════════════════════════════════════════════════ */
(function () {
    var LABEL_TEXT = "تفعيل الأرقام الهندية (أو أرقام اللغة المستعملة)";

    /* ① Mettre à jour l'objet JS_eLang (arabe uniquement) */
    if (typeof JS_eLang !== 'undefined' && typeof JS_DATA !== 'undefined' && JS_DATA.ucLangNOW === 'AR') {
        JS_eLang.cx_UseArabicDIGITS = LABEL_TEXT;
    }

    /* ② Mettre à jour le DOM directement (initUILabels s'est exécuté avant custom.js) */
    if (typeof JS_DATA !== 'undefined' && JS_DATA.ucLangNOW === 'AR') {
        var domLabel = document.getElementById('arabicDigitsLabel');
        if (domLabel) { domLabel.innerHTML = LABEL_TEXT; }
    }
}());

/* ═══════════════════════════════════════════════════════════════════════════
   IQAMA POPUP — texte coranique (sourate Al-Mu'minûn 23:1-2)
   Remplace le texte standard "إقامة الصلاة" par les deux premiers versets.
   Exécuté après le chargement complet de l'app et de JS_eLang.
   ═══════════════════════════════════════════════════════════════════════════ */
(function () {
    var IQAMA_TEXT = "قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝<br>الَّذِينَ هُمْ فِي صَلَاتِهِمْ <span class='iqamaBlinkWord'>خَاشِعُونَ</span>";

    /* ① Mettre à jour l'objet JS_eLang */
    if (typeof JS_eLang !== 'undefined') {
        JS_eLang.cx_IQAMAT_SALAT = IQAMA_TEXT;
    }

    /* ② Mettre à jour le DOM directement (initUILabels s'est exécuté avant custom.js) */
    var domV = document.getElementById('iqamaPopupTextVertical');
    var domH = document.getElementById('iqamaPopupTextHorizontal');
    if (domV) { domV.innerHTML = IQAMA_TEXT; }
    if (domH) { domH.innerHTML = IQAMA_TEXT; }
    /* Injection de la référence coranique (nom sourate + numéros ayats)
       dans les deux popups iqama (portrait et paysage).                  */
    var REF_HTML = "<div class='iqamaSurahRef'>سورة المؤمنون &nbsp;﴿ 1 - 2 ﴾</div>";

    function injectRef(popupId) {
        var popup = document.getElementById(popupId);
        if (popup && !popup.querySelector('.iqamaSurahRef')) {
            popup.insertAdjacentHTML('beforeend', REF_HTML);
        }
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function () {
            injectRef('iqamaPopupVertical');
            injectRef('iqamaPopupHorizontal');
        });
    } else {
        injectRef('iqamaPopupVertical');
        injectRef('iqamaPopupHorizontal');
    }
}());

/* ═══════════════════════════════════════════════════════════════════════════
   IQAMA POPUP — extension de durée (+5 s)
   Le popup s'affiche normalement 10 s après le compteur 00, puis se masque.
   On intercepte hideElementFunction (pour les IDs iqama) et
   activateBlackScreenIfEnabled afin d'ajouter 5 s supplémentaires,
   sans toucher aux fichiers core.

   Garde-fou perimption (cf. _ucIqamaSeqEpoch, _installResyncOnResume tout en
   haut du fichier) : startIqamaSequenceFunction() (core) programme TOUTE sa
   suite (ce hideElementFunction differe, activateBlackScreenIfEnabled,
   onIqamaEndFunction, animateBlackScreenCountdown) via setTimeout brut, sans
   identifiant recuperable -> aucun clearTimeout possible. Si l'appli passe en
   arriere-plan (timers geles) puis revient alors qu'une PRIERE DIFFERENTE est
   desormais en cours (ou plus aucune), ces callbacks perimes se declenchaient
   quand meme en rafale au reveil des timers, rejouant popup/rideau
   noir/azkar de l'ANCIENNE sequence. Chaque callback verifie maintenant qu'il
   appartient toujours a la sequence active (_ucIqamaSeqEpoch inchange depuis
   son demarrage) avant de faire quoi que ce soit.
   ═══════════════════════════════════════════════════════════════════════════ */
(function () {
    var EXTRA_MS   = 5000;   // 5 secondes de plus
    var IQAMA_IDS  = ['iqamaPopupVertical', 'iqamaPopupHorizontal'];
    var _delayBlackScreen = false;

    function _ucIqamaSeqStale() { return _ucIqamaSeqEpoch !== _ucActiveIqamaSeqEpoch; }

    /* ── 1. Intercept hideElementFunction pour les popups iqama ───────────── */
    var _origHide = window.hideElementFunction;
    window.hideElementFunction = function (elementId) {
        if (IQAMA_IDS.indexOf(elementId) !== -1) {
            if (_ucIqamaSeqStale()) return; // deja masque directement par le resync
            _delayBlackScreen = true;   // signaler qu'il faut aussi retarder le rideau
            //_L('IQAMA','FIRE',{action:'hide_delayed',element:elementId,extra:'+10s'});
            setTimeout(function () { if (!_ucIqamaSeqStale()) _origHide(elementId); }, EXTRA_MS);
        } else {
            _origHide(elementId);
        }
    };

    /* ── 1b. Trace affichage effectif du popup iqama ──────────────────────── */
    ucOn(UC_EVT.IQAMA_SHOW, function(e) {
        _L('POPUP','SHOW',{item:'texte_iqama', trigger:'iqama_show', prayer:(e && e.prayer)||'?'});
    });

    /* ── 2. Intercept activateBlackScreenIfEnabled pour retarder le rideau ── */
    var _origActivate = window.activateBlackScreenIfEnabled;
    window.activateBlackScreenIfEnabled = function () {
        if (_ucIqamaSeqStale()) { _delayBlackScreen = false; return; }
        if (_delayBlackScreen) {
            _delayBlackScreen = false;
            //_L('IQAMA','FIRE',{action:'black_screen_delayed',extra:'+10s'});
            setTimeout(function () { if (!_ucIqamaSeqStale()) _origActivate(); }, EXTRA_MS);
        } else {
            _origActivate();
        }
    };

    /* ── 3. Intercept onIqamaEndFunction / animateBlackScreenCountdown ─────
       Ces deux-la ne sont normalement appeles qu'une fois, en toute fin de
       sequence (fin de priere -> azkar ; animation du compte a rebours du
       rideau noir) -- jamais ailleurs dans le code, donc aucun risque de
       bloquer un usage legitime independant en les rendant no-op perimes. */
    var _origIqamaEnd = window.onIqamaEndFunction;
    if (typeof _origIqamaEnd === 'function') {
        window.onIqamaEndFunction = function () {
            if (_ucIqamaSeqStale()) return;
            _origIqamaEnd();
        };
    }
    var _origAnimateCountdown = window.animateBlackScreenCountdown;
    if (typeof _origAnimateCountdown === 'function') {
        window.animateBlackScreenCountdown = function () {
            if (_ucIqamaSeqStale()) return;
            _origAnimateCountdown();
        };
    }
}());

/* ═══════════════════════════════════════════════════════════════════════════
   IQAMA POPUP — tap-to-dismiss INSTANTANÉ (corrige un effet de bord du bloc
   "extension de durée (+5s)" ci-dessus). Le popup a déjà, en dur dans le
   core (index.html), onclick="hideElementFunction(this.id)" — mais
   window.hideElementFunction est monkey-patché juste au-dessus pour RETARDER
   le masquage de 5s pour ces IDs, y compris pour cet appel-là : un tap
   manuel semblait donc ne rien faire pendant 5 secondes (régression
   involontaire du patch +5s, pas un manque de fonctionnalité).
   On remplace l'onclick (propriété IDL — remplace entièrement le handler
   inline, n'affecte PAS les appels internes du core qui appellent
   hideElementFunction(...) directement pour le masquage AUTOMATIQUE en fin
   de séquence, toujours retardés comme prévu) par un masquage immédiat,
   identique à ce que fait hideElementFunction (className = 'hiddenClass'),
   sans passer par le patch +5s.
   ═══════════════════════════════════════════════════════════════════════════ */
(function () {
    ['iqamaPopupVertical', 'iqamaPopupHorizontal'].forEach(function(id) {
        var el = document.getElementById(id);
        if (!el) return;
        el.onclick = function() {
            _L('POPUP', 'DISMISS', { item: 'texte_iqama', reason: 'tap' });
            this.className = 'hiddenClass';
        };
    });
}());


// ═══════════════════════════════════════════════════════════════════════════
// ── CACHE MÉTÉO — affichage immédiat au reload (Android / réseau lent) ──────
// ═══════════════════════════════════════════════════════════════════════════
//
//  Problème : updateWeatherData() fait un fetch() réseau à chaque chargement.
//  Sur Android (GeckoView, réseau mobile), la résolution DNS + connexion prend
//  plusieurs secondes → le widget météo reste vide pendant ce délai.
//
//  Solution : cache localStorage  JS_WEATHER_CACHE  { data, ts }.
//    • Au chargement → si cache < 1 h, injecter immédiatement weatherApiData
//      et appeler refreshWeatherDisplay() → météo visible dès le 1er rendu.
//    • Monkey-patch updateWeatherData() → sauvegarder la réponse fraîche en cache.
//      Le fetch réseau continue normalement ; la mise à jour live se fait comme avant.
//
// ───────────────────────────────────────────────────────────────────────────
(function _installWeatherCache() {

    var _CACHE_KEY  = 'JS_WEATHER_CACHE';
    var _MAX_AGE_MS = 60 * 60 * 1000;   // 1 h

    // ── 1. Lecture du cache → affichage immédiat ───────────────────────────
    (function _restoreFromCache() {
        try {
            var _raw = localStorage.getItem(_CACHE_KEY);
            if (!_raw) return;
            var _entry = JSON.parse(_raw);
            var _age   = Date.now() - (_entry.ts || 0);
            if (!_entry.data || _age >= _MAX_AGE_MS) return;

            // Invalider le cache si la timezone stockée ne correspond plus à l'appareil
            var _deviceTz = (typeof Intl !== 'undefined')
                          ? Intl.DateTimeFormat().resolvedOptions().timeZone : null;
            if (_deviceTz && _entry.tz && _entry.tz !== _deviceTz) {
                localStorage.removeItem(_CACHE_KEY);
                _L('METEO','CACHE',{action:'invalidated', reason:'tz_mismatch',
                   stored:_entry.tz, device:_deviceTz});
                return;
            }

            weatherApiData = _entry.data;
            // Différer d'un tick pour que les variables de prière soient initialisées
            setTimeout(function () {
                if (typeof refreshWeatherDisplay === 'function') {
                    refreshWeatherDisplay();
                    _L('METEO','CACHE',{action:'restored', age_min:Math.round(_age/60000)+'min'});
                }
            }, 0);
        } catch (e) { /* cache corrompu → ignoré silencieusement */ }
    })();

    // ── 2. Monkey-patch updateWeatherData() → persistance + traces complètes ──
    var _origUpdateWeather = (typeof updateWeatherData === 'function') ? updateWeatherData : null;
    if (!_origUpdateWeather) return;

    updateWeatherData = function () {
        if (JS_DATA.ucIsMeteoOn == 0) return;
        if (!JS_DATA.ucMeteoLatitude || JS_DATA.ucMeteoLatitude == 0) {
            return _origUpdateWeather();
        }

        // ── Vérification connectivité avant fetch ───────────────────────────
        if (typeof navigator !== 'undefined' && navigator.onLine === false) {
            _L('METEO','NO_INTERNET',{reason:'navigator.onLine=false'});
            return;
        }

        // Utiliser la timezone de l'appareil (pas auto qui prend celle des coords GPS)
        // pour que les timestamps de l'API matchent getCurrentTimestampForWeather()
        var _deviceTz = (typeof Intl !== 'undefined')
                      ? Intl.DateTimeFormat().resolvedOptions().timeZone
                      : 'auto';

        // Priorité : coordonnées physiques de l'écran (MOSQUE_CONFIG.WEATHER_COORDS)
        // Fallback : coordonnées de prière (JS_DATA.ucMeteoLatitude/Longitude)
        var _wc  = (typeof MOSQUE_CONFIG !== 'undefined' && MOSQUE_CONFIG.WEATHER_COORDS)
                   ? MOSQUE_CONFIG.WEATHER_COORDS : null;
        var _lat = _wc ? _wc.latitude  : JS_DATA.ucMeteoLatitude;
        var _lon = _wc ? _wc.longitude : JS_DATA.ucMeteoLongitude;
        var _src = _wc ? 'MOSQUE_CONFIG' : 'JS_DATA';

        var _url = 'https://api.open-meteo.com/v1/forecast'
                 + '?latitude='  + _lat
                 + '&longitude=' + _lon
                 + '&hourly=temperature_2m,weathercode'
                 + '&forecast_days=7&timezone=' + encodeURIComponent(_deviceTz);

        _L('METEO','FETCH',{lat:_lat, lon:_lon, tz:_deviceTz, src:_src});

        fetch(_url)
            .then(function (r) {
                if (!r.ok) {
                    _L('METEO','HTTP_ERR',{http:r.status, statusText:r.statusText});
                    throw new Error('HTTP ' + r.status);
                }
                _L('METEO','OK',{http:r.status});
                return r.json();
            })
            .then(function (data) {
                weatherApiData = data;
                // Sauvegarder en cache pour le prochain chargement
                try {
                    var _saveTz = (typeof Intl !== 'undefined')
                                ? Intl.DateTimeFormat().resolvedOptions().timeZone : null;
                    localStorage.setItem(_CACHE_KEY, JSON.stringify({ data: data, ts: Date.now(), tz: _saveTz }));
                    _L('METEO','CACHE',{action:'saved'});
                } catch (e) { /* quota exceeded → ignoré */ }
                if (typeof refreshWeatherDisplay === 'function') refreshWeatherDisplay();
            })
            .catch(function (err) {
                // Distinguer absence internet vs erreur serveur
                var _isOffline = (typeof navigator !== 'undefined' && navigator.onLine === false)
                               || (err && (err.message === 'Failed to fetch'
                                        || err.message === 'NetworkError when attempting to fetch resource.'
                                        || err.message === 'Load failed'));
                if (_isOffline) {
                    _L('METEO','NO_INTERNET',{reason: err && err.message || 'network_error'});
                } else {
                    _L('METEO','ERR',{reason: err && err.message || String(err)});
                }
            });
    };

    // ── 3. Appel explicite au démarrage (filet de sécurité) ─────────────────
    // Le core appelle updateWeatherData() au chargement, mais si ce n'est pas
    // le cas (reload partiel, GeckoView), on force un appel après 4 s.
    var _startupWeatherDone = false;
    var _origFn = updateWeatherData;
    updateWeatherData = function () {
        _startupWeatherDone = true;
        return _origFn.apply(this, arguments);
    };
    setTimeout(function () {
        if (!_startupWeatherDone) {
            _L('METEO','STARTUP',{action:'forced_call', reason:'core_did_not_call'});
            updateWeatherData();
        }
    }, 4000);

})();
// ══════════════════════════════════════════════════════════════════════════
// ── AMPLI INT OFF : FILET DE SÉCURITÉ 5 MIN — WATCHDOG + RÉCUPÉRATION RELOAD
//
//  Scénarios couverts :
//  1. afterBlackHide déclenche ampliIntOff après délai configuré (flux normal).
//  2. Si 5 min s'écoulent après BLACK_HIDE sans qu'ampliIntOff ait été envoyé
//     (délai très long, échec HTTP, settings modifiés en cours) → envoi forcé.
//  3. Si la page est rechargée pendant l'écran noir (BLACK_HIDE ne se produit
//     jamais) → marqueur localStorage détecté au chargement suivant → envoi.
//
//  Marqueur localStorage : _ampliIntBlackShowAt (horodatage de BLACK_SHOW).
//  Effacé dès qu'ampliIntOff est envoyé (quelle que soit la source).
// ══════════════════════════════════════════════════════════════════════════

/* ═════════════════════════════
   PATCH : decrementPrayerDurationFunction
   Override de la fonction core (m2body.js) qui clampait a 5.
   Autorise la descente jusqu'a 1 minute.
   ═════════════════════════════ */
(function _patchPrayerDurationMin() {
    var _MAP = {
        FAJR:    { s: 'ucPrayDurationFAJR', el: 'durationFajrValue' },
        DOHR:    { s: 'ucPrayDurationDOHR', el: 'durationDohrValue' },
        ASR:     { s: 'ucPrayDurationASSR', el: 'durationAsrValue'  },
        MAGHRIB: { s: 'ucPrayDurationMGRB', el: 'durationMgrbValue' },
        ISHA:    { s: 'ucPrayDurationISHA', el: 'durationIshaValue' },
    };
    window.decrementPrayerDurationFunction = function(prayerKey) {
        var cfg = _MAP[prayerKey];
        if (!cfg) return;
        var val = parseInt(JS_DATA[cfg.s], 10);
        if (isNaN(val)) return;
        val = Math.max(1, val - 1);
        JS_DATA[cfg.s] = val;
        var el = document.getElementById(cfg.el);
        if (el) el.innerHTML = val;
        saveSettingsToStorageFunction();
    };
})();

(function _installAmpliIntOffWatchdog() {

    var WATCHDOG_MS    = 5 * 60 * 1000;   // 5 min après BLACK_HIDE
    var RELOAD_MAX_AGE = 30 * 60 * 1000;  // marqueur localStorage valide 30 min
    var LS_KEY         = '_ampliIntBlackShowAt';

    var _watchdogTimer = null;   // handle setTimeout watchdog
    var _offSent       = false;  // true dès qu'ampliIntOff est parti (cycle courant)
    _ucRegisterCleanup(function() {
        if (_watchdogTimer) { clearTimeout(_watchdogTimer); _watchdogTimer = null; }
    });

    // ── Helper : envoyer ampliIntOff si les conditions sont remplies ─────
    function _fireAmpliOff(reason) {
        if (JS_CUSTOM.ucLightAmpliIntOffEnabled != 1) {
            _L('LIGHTS','SKIP',{item:'ampliIntOff',evt:reason,reason:'disabled'});
            return;
        }
        var u = (JS_CUSTOM.ucLightAmpliIntOffUrl || '').trim();
        if (!u) {
            _L('LIGHTS','SKIP',{item:'ampliIntOff',evt:reason,reason:'url_empty'});
            return;
        }
        if (!_lightPrayerAllowed({prayersMaskSetting:'ucLightAmpliIntOnPrayers'}, _lastAzanPrayer)) {
            _L('LIGHTS','SKIP',{item:'ampliIntOff',evt:reason,reason:'mask_blocked',prayer:_lastAzanPrayer});
            return;
        }
        // _ucHttpCall déclenchera notre patch → _offSent=true + localStorage clear
        _L('LIGHTS','FIRE',{item:'ampliIntOff',evt:reason});
        _ucHttpCall(u, 'ampliIntOff');
    }

    // ── Monkey-patch _ucHttpCall : détecter quand ampliIntOff part ───────
    var _origHttp = _ucHttpCall;
    _ucHttpCall = function(url, label, silent) {
        if (label && label.indexOf('ampliIntOff') === 0) {
            _offSent = true;
            try { localStorage.removeItem(LS_KEY); } catch(e) {}
        }
        return _origHttp.apply(this, arguments);
    };

    // ── BLACK_SHOW : nouvelle salat — reset état + save localStorage ─────
    ucOn(UC_EVT.BLACK_SHOW, function() {
        _offSent = false;
        if (_watchdogTimer) { clearTimeout(_watchdogTimer); _watchdogTimer = null; }
        try { localStorage.setItem(LS_KEY, Date.now().toString()); } catch(e) {}
    });

    // ── BLACK_HIDE : démarrer le watchdog 5 min ──────────────────────────
    ucOn(UC_EVT.BLACK_HIDE, function() {
        if (_watchdogTimer) clearTimeout(_watchdogTimer);
        _watchdogTimer = setTimeout(function() {
            _watchdogTimer = null;
            if (_offSent) {
                _L('LIGHTS','SKIP',{item:'ampliIntOff',evt:'WATCHDOG_5MIN',reason:'already_sent'});
                return;
            }
            _L('LIGHTS','WARN',{item:'ampliIntOff',evt:'WATCHDOG_5MIN',reason:'not_sent_in_5min'});
            _fireAmpliOff('WATCHDOG_5MIN');
        }, WATCHDOG_MS);
    });

    // ── Vérification au chargement (survie reload pendant écran noir) ────
    //   Si BLACK_SHOW a été enregistré il y a < 30 min et ampliIntOff n'a
    //   pas encore été confirmé (marqueur toujours présent), on envoie.
    (function _checkOnLoad() {
        var stored;
        try { stored = localStorage.getItem(LS_KEY); } catch(e) { return; }
        if (!stored) return;
        var elapsed = Date.now() - parseInt(stored, 10);
        if (isNaN(elapsed) || elapsed < 0 || elapsed > RELOAD_MAX_AGE) {
            try { localStorage.removeItem(LS_KEY); } catch(e) {}
            return;
        }
        // Page rechargée pendant ou juste après une salat.
        // Délai 3 s pour laisser custom.js et ses patches s'initialiser.
        var _elapsed_min = Math.round(elapsed / 60000);
        _L('LIGHTS','WARN',{item:'ampliIntOff',evt:'RELOAD_RECOVERY',elapsed_min:_elapsed_min});
        setTimeout(function() {
            _fireAmpliOff('RELOAD_RECOVERY');
        }, 3000);
    })();

})();

// ══════════════════════════════════════════════════════════════════════════════
//  UNLOAD CLEANUP — annule tous les timers/events avant reload ou RESET
// ══════════════════════════════════════════════════════════════════════════════
(function _installSpecDataOverride() {

    var _SD = 'spec/data/';

    // _probeAndLoad: tente de charger spec/data/{PAYS}/wtimes-{city}.js via <script>.
    // Le code pays est extrait du cityCode (ex: 'tn.monastir' -> 'TN').
    // Fonctionne sur file://, http:// et resource://android sans restriction CORS.
    function _probeAndLoad(cityCode, onFound, onMiss) {
        var _country = cityCode.split('.')[0].toUpperCase();
        var src = _SD + _country + '/wtimes-' + cityCode + '.js';
        var s = document.createElement('script');
        s.src = src + '?_sd=' + Date.now();
        s.onload  = function() { onFound(src); };
        s.onerror = function() {
            if (s.parentNode) s.parentNode.removeChild(s);
            onMiss();
        };
        document.head.appendChild(s);
    }

    // Demarrage : le core a deja charge wtimes via document.write().
    // On sonde spec/data/ ; si override trouve, on recharge JS_TIMES et recalcule.
    var _startCity = JS_DATA.ucNowCityCODE || '';
    if (_startCity) {
        _probeAndLoad(_startCity, function(src) {
            _L('DATA', 'OVERRIDE_STARTUP', {city: _startCity, src: src});
            if (typeof calculateAndDisplayTimesFunction === 'function')
                calculateAndDisplayTimesFunction();
        }, function() {
            _L('DATA', 'CORE_STARTUP', {city: _startCity});
        });
    }

    // Changement de ville : monkey-patch selectCityFunction
    var _origSelectCity = window.selectCityFunction;
    if (typeof _origSelectCity === 'function') {
        window.selectCityFunction = function(selectedCityCode) {
            _probeAndLoad(selectedCityCode, function(src) {
                _L('DATA', 'OVERRIDE_SELECT', {city: selectedCityCode, src: src});
                JS_DATA.ucNowCityCODE = selectedCityCode;
                saveSettingsToStorageFunction();
                var _parts = selectedCityCode.split('.');
                var _btn = document.getElementById('selectCityButton');
                if (_btn && _parts[1])
                    _btn.innerHTML = typeof capitalizeFirstLetterFunction === 'function'
                        ? capitalizeFirstLetterFunction(_parts[1]) : _parts[1];
                hideElementByIdFunction('cityListModalId');
                calculateAndDisplayTimesFunction();
            }, function() {
                _L('DATA', 'CORE_SELECT', {city: selectedCityCode});
                _origSelectCity(selectedCityCode);
            });
        };
    } else {
        _L('DATA', 'WARN', {reason: 'selectCityFunction_not_found'});
    }

    _L('DATA', 'INIT', {specDir: _SD, city: _startCity || '?'});
})();

(function _installUnloadCleanup() {

    var _HTTP_RETRY_MAX_AGE_MS = 8000;

    function _ucFlushHttpRetry() {
        if (!_ucHttpRetryQueue.length) return;
        var _now = Date.now();
        var _retried = 0, _expired = 0;
        var _queue = _ucHttpRetryQueue.splice(0);
        _queue.forEach(function(entry) {
            if (_now - entry.ts > _HTTP_RETRY_MAX_AGE_MS) { _expired++; return; }
            _L('LIGHTS', 'RETRY_HTTP', {item: entry.label || '?', age: Math.round((_now - entry.ts) / 1000) + 's'});
            _ucHttpCall(entry.url, entry.label, false);
            _retried++;
        });
        if (_retried || _expired)
            _L('LIGHTS', 'RETRY_FLUSH', {retried: _retried, expired: _expired});
    }

    function _ucCancelAll(reason) {
        if (_ucUnloading) return;          // déjà déclenché
        _ucUnloading = true;

        // ── Timers module-level ─────────────────────────────────────────────
        if (_qpFallbackTimer) { clearTimeout(_qpFallbackTimer);  _qpFallbackTimer = null; }
        if (typeof _qpProbeTimer  !== 'undefined' && _qpProbeTimer)
            { clearInterval(_qpProbeTimer); _qpProbeTimer = null; }
        if (typeof _hijriSyncTimer !== 'undefined' && _hijriSyncTimer)
            { clearTimeout(_hijriSyncTimer); _hijriSyncTimer = null; }

        // ── Strobes lumières actifs ─────────────────────────────────────────
        if (typeof _strobeRunId === 'object') {
            Object.keys(_strobeRunId).forEach(function(lbl) {
                if (typeof _cancelStrobe === 'function') _cancelStrobe(lbl);
            });
        }

        // ── IIFEs privées (via registry) ────────────────────────────────────
        _ucCleanupFns.forEach(function(fn) { try { fn(); } catch(e) {} });

        _L('SYS', 'CLEANUP', {
            reason:     reason || 'unload',
            registered: _ucCleanupFns.length,
            note:       'ucUnloading_set_true — if pageshow follows, will be reset'
        });

        // Fallback : si pageshow ne se déclenche pas (GeckoView/Android),
        // réinitialise _ucUnloading après 3 s pour que le cycle suivant fonctionne.
        if (_ucUnloadingFallbackTimer) clearTimeout(_ucUnloadingFallbackTimer);
        _ucUnloadingFallbackTimer = setTimeout(function() {
            _ucUnloadingFallbackTimer = null;
            if (!_ucUnloading) return;   // pageshow est déjà passé
            _ucUnloading = false;
            _L('SYS', 'RESUME', {
                reason: 'fallback_timeout',
                delay:  '3s',
                note:   'pageshow_did_not_fire'
            });
            _ucFlushHttpRetry();
        }, 3000);
    }

    // beforeunload : page quittée / rechargée par le navigateur
    window.addEventListener('beforeunload', function() { _ucCancelAll('beforeunload'); });

    // pageshow : déclenché quand la page redevient visible (BFCache ou fin de reload).
    // Sur Android GeckoView, location.reload() peut déclencher beforeunload sans que le
    // contexte JS soit détruit (la page continue à tourner). Le pageshow qui suit permet
    // de réinitialiser _ucUnloading et tous les timers annulés, pour que les prochaines
    // lectures Coran et commandes lumières puissent se déclencher normalement.
    window.addEventListener('pageshow', function(evt) {
        if (_ucUnloadingFallbackTimer) {
            clearTimeout(_ucUnloadingFallbackTimer);
            _ucUnloadingFallbackTimer = null;
        }
        if (_ucUnloading) {
            _ucUnloading = false;
            _L('SYS', 'RESUME', {
                reason:      'pageshow',
                persisted:   evt.persisted ? 1 : 0,
                note:        'ucUnloading_reset'
            });
        }
        _ucFlushHttpRetry();
    });

    // restartApplicationFunction : clic sur le drapeau / double-clic version
    if (typeof restartApplicationFunction === 'function') {
        var _origRestart = restartApplicationFunction;
        window.restartApplicationFunction = function() {
            _ucCancelAll('restartApplicationFunction');
            _origRestart();
        };
    }

})();


// ══════════════════════════════════════════════════════════════════════════════
//  FIX : tick ":00" manqué → affichage nextPrayerTimeDisplay figé +1 minute
//
//  Cause : setInterval('clockTickFunction()', 1000) peut sauter la seconde :00
//  (drift setInterval sous charge CPU). updateTimeAndPrayersFunction — qui seul
//  met à jour currentTimeInMinutes ET l'affichage — n'est appelé qu'à :00.
//  Si ce tick est manqué, currentTimeInMinutes reste figé une minute de plus.
//
//  Solution : on monkey-patche clockTickFunction (possible car setInterval
//  utilise une string → eval au moment du tick, donc la nouvelle référence
//  globale est utilisée). À chaque tick, on compare la minute courante avec
//  currentTimeInMinutes ; si elles divergent, on force updateTimeAndPrayers.
// ══════════════════════════════════════════════════════════════════════════════
(function _fixMissedMinuteTick() {
    if (typeof clockTickFunction !== 'function') return;

    var _prevWallMin = -1;
    var _origTick    = clockTickFunction;

    clockTickFunction = function() {
        _origTick();   // exécution normale (peut appeler updateTimeAndPrayersFunction si :00)

        // Lire la minute courante directement depuis l'horloge
        var _now    = new Date();
        if (JS_DATA && JS_DATA.ucLocalHoursAdjustment)
            _now.setTime(_now.getTime() + JS_DATA.ucLocalHoursAdjustment * 3600000);
        var _wallMin = _now.getHours() * 60 + _now.getMinutes();

        if (_prevWallMin !== -1 && _wallMin !== _prevWallMin) {
            // La minute vient de changer — vérifier si currentTimeInMinutes a suivi
            if (typeof currentTimeInMinutes !== 'undefined' && currentTimeInMinutes !== _wallMin) {
                // Le tick :00 a été manqué → forcer la mise à jour (silencieux :
                // pas de trace debug, seule la correction reste active)
                if (typeof updateTimeAndPrayersFunction === 'function')
                    updateTimeAndPrayersFunction(false);
            }
        }
        _prevWallMin = _wallMin;
    };

    _L('SYS', 'PATCH', { item: 'clockTickFunction', fix: 'missed_minute_tick' });
})();
// ── Dump de configuration au démarrage ──────────────────────────────────────
// Loggue en une seule passe tous les paramètres lumières + Coran pour faciliter
// le diagnostic sans avoir à ouvrir les settings.
(function _logStartupConfig() {
    document.addEventListener('DOMContentLoaded', function() {

        // ── Lumières (un log par item) ────────────────────────────────────
        _lightProgramConfig.forEach(function(item) {
            var enabled = JS_CUSTOM[item.enabledSetting] == 1 ? 1 : 0;
            var url     = (JS_CUSTOM[item.urlSetting] || '').trim();
            var delay   = parseInt(JS_CUSTOM[item.delaySetting], 10);
            if (isNaN(delay)) delay = item.delayDefault || 0;
            var pair    = item.pairEnabledSetting != null
                        ? (JS_CUSTOM[item.pairEnabledSetting] == 1 ? 1 : 0) : null;
            var effectiveTrigger = _getItemTrigger(item);
            var ctx = { item: item.key,
                        trigger: effectiveTrigger !== item.trigger
                            ? effectiveTrigger + '(custom:' + item.trigger + ')'
                            : item.trigger,
                        enabled: enabled, url: url || '(vide)', delay: delay + 's' };
            if (pair !== null) ctx.pair = pair;
            if (item.prayerFilter)       ctx.prayerFilter = item.prayerFilter;
            if (item.prayersMaskSetting) ctx.mask         = JS_CUSTOM[item.prayersMaskSetting] || '?';
            if (item.jomaDelaySetting)   ctx.delayJomoa   = (JS_CUSTOM[item.jomaDelaySetting] || item.jomaDelayDefault || 0) + 's';
            _L('CFG', 'LIGHT', ctx);
        });

        // ── Blink minaret / mihrab ────────────────────────────────────────
        var _mnCb  = document.getElementById('iqamaZeroMinaretBlinkCb');
        var _mhCb  = document.getElementById('iqamaZeroMihrabBlinkCb');
        var _mnUrl = (JS_CUSTOM.ucLightMinaretOnUrl || '').trim();
        var _mhUrl = (JS_CUSTOM.ucLightMihrabOnUrl  || '').trim();
        _L('CFG', 'BLINK', {
            minaret_cb:  _mnCb ? (_mnCb.checked ? 1 : 0) : 'not_found',
            minaret_url: _mnUrl || '(vide)',
            mihrab_cb:   _mhCb ? (_mhCb.checked ? 1 : 0) : 'not_found',
            mihrab_url:  _mhUrl || '(vide)',
            conflict:    (_mnUrl && _mhUrl && _mnUrl === _mhUrl) ? 'YES' : 'no'
        });

        // ── Coran — paramètres globaux ────────────────────────────────────
        _L('CFG', 'QURAN_GLOBAL', {
            globalEnabled: JS_CUSTOM.ucStartQuranBeforeAzan == 1 ? 1 : 0,
            serverEnabled: JS_CUSTOM.ucQuranServerEnabled   == 1 ? 1 : 0,
            serverUrl:     JS_CUSTOM.ucQuranServerUrl || '(vide)',
            stopEnabled:   JS_CUSTOM.ucStopQuranBeforeAzan  == 1 ? 1 : 0,
            stopDelay:     (JS_CUSTOM.ucStopQuranBeforeAzanDelay || 0) + 's',
            probeEnabled:  JS_CUSTOM.ucQPServerProbeEnabled == 1 ? 1 : 0,
            maxRetry:      JS_CUSTOM.ucQPMaxRetryBeforeStop || 0
        });

        // ── Coran — par prière ────────────────────────────────────────────
        var _qCfg = [
            { p:'FAJR',  e:'ucStartQuranBeforeAzanFajrEnabled',  d:'ucStartQuranBeforeAzanFajr',  dd:'ucStartQuranBeforeAzanFajrDays'  },
            { p:'DOHR',  e:'ucStartQuranBeforeAzanDohrEnabled',  d:'ucStartQuranBeforeAzanDohr',  dd:'ucStartQuranBeforeAzanDohrDays'  },
            { p:'ASSR',  e:'ucStartQuranBeforeAzanAsrEnabled',   d:'ucStartQuranBeforeAzanAsr',   dd:'ucStartQuranBeforeAzanAsrDays'   },
            { p:'MGRB',  e:'ucStartQuranBeforeAzanMgrbEnabled',  d:'ucStartQuranBeforeAzanMgrb',  dd:'ucStartQuranBeforeAzanMgrbDays'  },
            { p:'ISHA',  e:'ucStartQuranBeforeAzanIshaEnabled',  d:'ucStartQuranBeforeAzanIsha',  dd:'ucStartQuranBeforeAzanIshaDays'  },
            { p:'JOMOA', e:'ucStartQuranBeforeAzanDohrEnabled', d:'ucStartQuranBeforeAzanDohr', dd:'ucStartQuranBeforeAzanDohrDays' } // fusionné avec DOHR, cf. _quranAutoStartConfig.JOMOA
        ];
        _qCfg.forEach(function(c) {
            var ctx = { prayer: c.p,
                        enabled: JS_CUSTOM[c.e] == 1 ? 1 : 0,
                        delay:   (JS_CUSTOM[c.d] || 0) + 's' };
            if (c.dd) ctx.days = JS_CUSTOM[c.dd] || '?';
            _L('CFG', 'QURAN_PRAYER', ctx);
        });

        // ── Réciteurs actifs ──────────────────────────────────────────────
        var _reciters = Array.isArray(JS_CUSTOM.ucReciters) ? JS_CUSTOM.ucReciters : [];
        var _active   = _reciters.filter(function(r){ return r.enabled == 1; })
                                 .map(function(r){ return r.dir; });
        _L('CFG', 'QURAN_RECITERS', {
            total:   _reciters.length,
            enabled: _active.length,
            active:  _active.join(',') || '(aucun)'
        });

    }, { once: true });

})();
// ═══════════════════════════════════════════════════════════════════════════
// ── THÈMES CUSTOM : spec/themes/HR/HR{n}.png + spec/themes/VR/VR{n}.png ───
// ═══════════════════════════════════════════════════════════════════════════
//
//  Les images HR{n}.png / VR{n}.png dans spec/themes/HR/ et spec/themes/VR/
//  s'ajoutent aux 40 thèmes core (indices 0-39).
//  Indices custom : 40 = HR1/VR1, 41 = HR2/VR2, …
//  Si une orientation a moins de thèmes que l'autre, on boucle sur le dernier
//  disponible plutôt que d'afficher une image manquante.
//
//  Détection au démarrage (probe asynchrone) : sonde HR1..HR{MAX_PROBE}
//  et VR1..VR{MAX_PROBE} via Image.onload/onerror.
// ───────────────────────────────────────────────────────────────────────────
(function _installCustomThemes() {

    var CUSTOM_BASE = 1000;     // premier index custom (loin du core, collision-proof)
    var MAX_PROBE   = 20;       // indices sondés : 1 … MAX_PROBE
    var HR_BASE     = 'spec/themes/HR/';
    var VR_BASE     = 'spec/themes/VR/';
    var EXT         = '.webp';

    // ── Sonde un fichier image : résout true/false ────────────────────────
    function _probeFile(url) {
        return new Promise(function(resolve) {
            var img = new Image();
            img.onload  = function() { resolve(true);  };
            img.onerror = function() { resolve(false); };
            img.src = url;
        });
    }

    // ── Sonde tous les indices 1…MAX_PROBE pour un préfixe ───────────────
    function _probeSeq(base, prefix) {
        var promises = [];
        for (var i = 1; i <= MAX_PROBE; i++) {
            promises.push(_probeFile(base + prefix + i + EXT));
        }
        return Promise.all(promises);
    }

    Promise.all([
        _probeSeq(HR_BASE, 'HR_A'),   // 0 : HR avec arcade
        _probeSeq(HR_BASE, 'HR_S'),   // 1 : HR sans arcade
        _probeSeq(VR_BASE, 'VR_A'),   // 2 : VR avec arcade  (classicVrClass)
        _probeSeq(VR_BASE, 'VR_S'),   // 3 : VR sans arcade
    ]).then(function(results) {
        var hrA = results[0];
        var hrS = results[1];
        var vrA = results[2];
        var vrS = results[3];

        // ── Construit _customThemes[] ─────────────────────────────────────
        // Ordre : A-type d'abord (classicVrClass = arcade), puis S-type.
        // Un slot n est inclus si au moins une image HR ou VR existe.
        var themes = [];
        var nextIdx = CUSTOM_BASE;

        // Passe 1 : A-type
        for (var n = 1; n <= MAX_PROBE; n++) {
            if (!hrA[n-1] && !vrA[n-1]) continue;
            themes.push({
                idx:     nextIdx++,
                hrUrl:   hrA[n-1] ? (HR_BASE + 'HR_A' + n + EXT) : null,
                vrUrl:   vrA[n-1] ? (VR_BASE + 'VR_A' + n + EXT) : null,
                vrClass: 'classicVrClass',
            });
        }

        // Passe 2 : S-type
        for (var m = 1; m <= MAX_PROBE; m++) {
            if (!hrS[m-1] && !vrS[m-1]) continue;
            themes.push({
                idx:     nextIdx++,
                hrUrl:   hrS[m-1] ? (HR_BASE + 'HR_S' + m + EXT) : null,
                vrUrl:   vrS[m-1] ? (VR_BASE + 'VR_S' + m + EXT) : null,
                vrClass: '',
            });
        }

        if (themes.length === 0) {
            _L('THEME','INFO',{custom:'aucun thème trouvé dans spec/themes/'});
            return;
        }

        var _minIdx = themes[0].idx;
        var _maxIdx = themes[themes.length - 1].idx;
        _L('THEME','INFO',{customThemes: themes.length, idxRange: _minIdx + '-' + _maxIdx});
        _installPatches(themes, _minIdx, _maxIdx);
    });

    function _installPatches(themes, _minIdx, _maxIdx) {

        var NEUTRAL_IDX = 20;   // index core neutre existant (évite 404)

        function _findEntry(idx) {
            for (var i = 0; i < themes.length; i++) {
                if (themes[i].idx === idx) return themes[i];
            }
            return null;
        }

        // ── Applique background custom sur les deux containers ────────────
        function _applyCustomBg(entry) {
            var isHR = (typeof isHorizontalOrientation !== 'undefined') && isHorizontalOrientation;
            var url  = isHR ? entry.hrUrl : entry.vrUrl;
            if (!url) url = entry.hrUrl || entry.vrUrl;   // fallback cross-orientation
            if (!url) return;
            var hrC = document.getElementById('mainHorizontalContainer');
            var vrC = document.getElementById('mainVerticalContainer');
            [hrC, vrC].forEach(function(el) {
                if (!el) return;
                el.style.background       = 'url(' + url + ')';
                el.style.backgroundRepeat = 'no-repeat';
                el.style.backgroundSize   = '100% 100%';
            });
        }

        // ── Applique vrClass sur mainVerticalContainer ────────────────────
        // (le core ne repassera pas ici ; on force la classe arcade/standard)
        function _applyVrClass(entry) {
            var vrC = document.getElementById('mainVerticalContainer');
            if (!vrC) return;
            vrC.classList.remove('classicVrClass', 'specialVrClass');
            if (entry.vrClass) vrC.classList.add(entry.vrClass);
        }

        // ── Patch applyThemeFunction ──────────────────────────────────────
        // Pour un index custom : substitue NEUTRAL_IDX le temps que l'original
        // règle layout/couleurs (sans charger themes/HR-{custom}.jpg → 404),
        // puis restore l'index et surcharge le fond + la classe arcade.
        var _origApply = window.applyThemeFunction;
        window.applyThemeFunction = function(withTransition) {
            var entry = _findEntry(currentThemeIndex);
            if (entry) {
                var saved = currentThemeIndex;
                currentThemeIndex = NEUTRAL_IDX;
                _origApply.call(this, withTransition);
                currentThemeIndex = saved;
                _applyCustomBg(entry);
                _applyVrClass(entry);
                // Mettre a jour le preview currentThemeDisplay avec l'image custom
                (function(e) {
                    var el = document.getElementById('currentThemeDisplay');
                    if (!el) return;
                    var isHR = (typeof isHorizontalOrientation === 'undefined') || isHorizontalOrientation;
                    var url = isHR ? (e.hrUrl || e.vrUrl) : (e.vrUrl || e.hrUrl);
                    if (url) {
                        el.style.background       = 'url(' + url + ')';
                        el.style.backgroundRepeat = 'no-repeat';
                        el.style.backgroundSize   = 'auto 100%';
                    }
                    var label = (url || '').replace(/.*\//, '').replace(/\.\w+$/, '');
                    el.innerHTML = label || String(e.idx);
                })(entry);
            } else {
                _origApply.call(this, withTransition);
            }
        };

        // ── Patch incrementThemeFunction ──────────────────────────────────
        // Cycle : 0-39 (core) → CUSTOM_BASE…_maxIdx → retour à 0
        window.incrementThemeFunction = function() {
            if ((JS_DATA.ucUserFilesACTIVE == 1) && userUploadedImages[0]) return;
            if (currentThemeIndex >= _maxIdx) {
                currentThemeIndex = 0;
            } else if (currentThemeIndex >= 39 && currentThemeIndex < _minIdx) {
                currentThemeIndex = _minIdx;
            } else {
                currentThemeIndex++;
            }
            setThemeFunction(currentThemeIndex, false);
        };

        // ── Patch decrementThemeFunction ──────────────────────────────────
        window.decrementThemeFunction = function() {
            if ((JS_DATA.ucUserFilesACTIVE == 1) && userUploadedImages[0]) return;
            if (currentThemeIndex <= 0) {
                currentThemeIndex = _maxIdx;
            } else if (currentThemeIndex === _minIdx) {
                currentThemeIndex = 39;
            } else {
                currentThemeIndex--;
            }
            setThemeFunction(currentThemeIndex, false);
        };

        _L('THEME','PATCH',{fn:'apply/increment/decrement',
            coreMax:39, customMin:_minIdx, customMax:_maxIdx});
    }

})();


// ═══════════════════════════════════════════════════════════════════════════
// ── TAKBIR : sélection manuelle (lecteur) et auto-play Maghreb Dhûl-Hijja ───────
// ═══════════════════════════════════════════════════════════════════════════
//
// Bouton « تكبير » dans le lecteur Coran : joue spec/audio/takbir.ogg en local.
// Contrairement à l'azan/fin/salatnabi, le takbir n'a pas d'option serveur :
// toujours local, jamais de requête vers ucQuranServerUrl (évite un échec
// total quand le serveur Coran est désactivé/injoignable — il n'y avait
// auparavant aucun repli local sur ce bouton).
// Auto-play : se déclenche à l’ouverture du rideau noir de Maghreb,
//   uniquement du 1er au 13e jour de Dhûl-Hijja, après un délai configurable.
// Débogage console :  takbirTest()  → joue immédiatement
// ─────────────────────────────────────────────────────────────────────────

/** Indice sentinelle : mode takbir (hors récitateurs normaux, != -1) */
var _QP_TAKBIR_IDX = -2;

/** Chemin local unique du takbir (jamais de variante serveur). */
var _QP_TAKBIR_LOCAL_SRC = 'spec/audio/takbir.ogg';

// ── Rafraîchissement visuel du bouton تكبير ─────────────────────────────────────
function _refreshQPTakbirBtn() {
    var btn = document.getElementById('qpTakbirBtn');
    if (btn) btn.classList.toggle('qSel', _qpReciterIdx === _QP_TAKBIR_IDX);
}

// Note : le mini lecteur #qpTakbirAudio (cf. _buildQPReciters/#qpTakbirRow)
// reste toujours visible en face du bouton تكبير — plus de show/hide.

// ── Sélection manuelle du takbir dans le lecteur Coran ─────────────────────
// IMPORTANT : ne joue PAS sur quranAudioPlayer. Cet élément est câblé une
// fois pour toutes sur l'égaliseur Web Audio (createMediaElementSource, cf.
// _qpInitAnalyser) ; or un fichier local file:// routé à travers ce graphe
// perd son flag "origin-clean" (pas d'en-têtes CORS possibles sur file://)
// -> Web Audio rend la sortie silencieuse (currentTime avance normalement,
// mais 0 son), quel que soit le réglage de l'attribut crossorigin. Constaté
// sous Chrome/Windows ; masqué sous Android par allowUniversalAccessFromFileURLs
// (WebView traite alors les origines file:// comme équivalentes). On rejoue
// donc le takbir manuel sur le même <audio> dédié, jamais câblé sur
// l'égaliseur, que l'auto-play (cf. window._ucPlayTakbirManual ci-dessous).
function selectQPTakbir() {
    _qpUserAborted = false;
    _qpErrorCount  = 0;
    _qpReciterIdx  = _QP_TAKBIR_IDX;
    _qpSurahNum    = 0;
    _refreshQPReciters();
    _refreshQPTakbirBtn();
    // Coupe une éventuelle sourate en cours sur le lecteur partagé.
    var qpAudio = document.getElementById('quranAudioPlayer');
    if (qpAudio && !qpAudio.paused) { try { qpAudio.pause(); } catch(e) {} }
    if (typeof _qpStopEq === 'function') _qpStopEq();
    var nowEl = document.getElementById('quranNowPlaying');
    if (nowEl) nowEl.innerHTML = '&#9904;&nbsp;تكبير';
    if (typeof window._ucPlayTakbirManual === 'function') window._ucPlayTakbirManual();
    _L('QP','FIRE',{action:'takbir',url:_QP_TAKBIR_LOCAL_SRC});
}

// Patch selectQPReciter : désélectionne تكبير quand on choisit un récitateur normal
(function _patchSelectQPReciterForTakbir() {
    var _orig = selectQPReciter;
    selectQPReciter = function(idx) {
        // Le takbir manuel joue sur son propre <audio> (cf. selectQPTakbir) :
        // il faut l'arrêter explicitement, sinon il continue en arrière-plan.
        if (_qpReciterIdx === _QP_TAKBIR_IDX && typeof window._ucStopTakbir === 'function') {
            window._ucStopTakbir('switch_to_reciter');
        }
        _orig(idx);
        _refreshQPTakbirBtn();
    };
})();

// Patch _refreshQPNowPlaying : affiche "تكبير" en mode takbir
(function _patchRefreshQPNowPlayingForTakbir() {
    var _orig = _refreshQPNowPlaying;
    _refreshQPNowPlaying = function() {
        if (_qpReciterIdx === _QP_TAKBIR_IDX) {
            var el = document.getElementById('quranNowPlaying');
            if (el) el.innerHTML = '&#9904;&nbsp;تكبير';
            return;
        }
        _orig();
    };
})();

