    var pn = _el('ucPinNew');  if (pn) pn.placeholder = t('newPin');
    var pc = _el('ucPinConf'); if (pc) pc.placeholder = t('confPin');
    var cc = _el('ucPinChangeCancel'); if (cc) cc.textContent = t('cancel');
    var co = _el('ucPinChangeOk');     if (co) co.textContent = t('confirm');

    // Overlay Janaza
    var jt = _el('ucJanazaTitle'); if (jt) jt.textContent = t('janazaTitle');
    var jn = _el('ucJanazaName');  if (jn) {
        jn.placeholder = t('janazaName');
        jn.style.direction = isRtl ? 'rtl' : 'ltr';
        jn.style.textAlign = isRtl ? 'right' : 'left';
    }
    var jd = _el('ucJanazaDohr');  if (jd) jd.textContent = t('janazaDohr');
    var ja = _el('ucJanazaAsr');   if (ja) ja.textContent = t('janazaAsr');
    var jc = _el('ucJanazaCancel');if (jc) jc.textContent = t('cancel');
    var jo = _el('ucJanazaSend');  if (jo) jo.textContent = t('send');

    // Overlay Preview
    var pt = _el('ucPreviewTitle');  if (pt) pt.textContent = t('previewTitle');
    var pcc = _el('ucPreviewCancel'); if (pcc) pcc.textContent = t('cancel');
    var ps = _el('ucPreviewSend');   if (ps) ps.textContent = t('send');

    // Overlay Message
    var mt = document.querySelector('#ucMsgOverlay p'); if (mt) mt.textContent = t('msgTitle');
    var mx = _el('ucMsgText');    if (mx) {
        mx.placeholder = t('msgPlaceholder');
        mx.style.direction = isRtl ? 'rtl' : 'ltr';
        mx.style.textAlign = isRtl ? 'right' : 'left';
    }
    var mp = _el('ucMsgPin');     if (mp) mp.placeholder = t('pinBtn');
    var mc = _el('ucMsgCancel');  if (mc) mc.textContent = t('cancel');
    var ms = _el('ucMsgSend');    if (ms) ms.textContent = t('send');

    // Overlay Historique
    var ht = _el('ucHistTitle'); if (ht) ht.textContent = t('histTitle');
    var hc = _el('ucHistClose'); if (hc) hc.textContent = t('close');

    // Messages toast accessibles aux handlers existants
