// ── Historique des messages envoyes (Notifier / Message / Janaza) ────────────
// Stocke localement (cet appareil uniquement) les 10 derniers envois admin pour
// pouvoir les consulter via le bouton "Historique", et pour alimenter le bloc
// "Dernieres notifications" de l'onglet Actualites (_installMosqueInfoModal).
// Cle localStorage : UC_NOTIF_HISTORY, tableau JSON, le plus recent en index 0.
var UC_NOTIF_HISTORY_KEY = 'UC_NOTIF_HISTORY';
var UC_NOTIF_HISTORY_MAX = 10;

function _ucGetNotifHistory() {
    try {
        var raw = localStorage.getItem(UC_NOTIF_HISTORY_KEY);
        var arr = raw ? JSON.parse(raw) : [];
        return Array.isArray(arr) ? arr : [];
    } catch (e) {
        return [];
    }
}

// type : 'notifier' | 'message' | 'janaza' — body : texte libre (vide pour notifier)
function _ucAddNotifHistory(type, body, ok) {
    try {
        var arr = _ucGetNotifHistory();
        arr.unshift({
            ts:   new Date().toISOString(),
            type: type,
            body: String(body || '').slice(0, 300),
            ok:   !!ok
        });
        arr = arr.slice(0, UC_NOTIF_HISTORY_MAX);
        localStorage.setItem(UC_NOTIF_HISTORY_KEY, JSON.stringify(arr));
        _L('NOTIF', 'HIST_ADD', { type: type, ok: !!ok });
    } catch (e) {
        // localStorage indisponible : on ignore silencieusement
    }
}
window._ucGetNotifHistory = _ucGetNotifHistory;
window._ucAddNotifHistory = _ucAddNotifHistory;

// ── Payload admin + overlay preview ──────────────────────────────────────────
// _buildAdminPayload() lit JS_DATA et construit le JSON a envoyer a l'API.
// Flow : PIN ok -> apercu JSON -> bouton Envoyer (API branchee a l'etape suivante).
(function _installAdminPayloadPreview() {

    // ── Construction du payload ───────────────────────────────────────────
    function _buildAdminPayload() {
        var d   = JS_DATA;
        var mid = (window.MOSQUE_CONFIG && window.MOSQUE_CONFIG.MOSQUE_ID)
               || (function() { try { return localStorage.getItem('UC_MOSQUE_ID') || ''; } catch(e) { return ''; } })()               || '';
        return {
            mosque_id:   mid,
            sent_at:     new Date().toISOString(),
            time_flags: {
                ramadan_isha_30min: d.ucRamadanDoIsha30min || 0,
                summer_time:        d.ucInSummerAdd1Hour   || 0,
                force_1h_more:      d.ucForce1HourMore     || 0,
                force_1h_less:      d.ucForce1HourLess     || 0
            },
            azan_offsets: {
                fajr:    d.ucAthanMinutesFAJR || 0,
                shrouq:  d.ucAthanMinutesSHRQ || 0,
                dhuhr:   d.ucAthanMinutesDOHR || 0,
                asr:     d.ucAthanMinutesASSR || 0,
                maghrib: d.ucAthanMinutesMGRB || 0,
                isha:    d.ucAthanMinutesISHA || 0
            },
            iqama_delay: {
                fajr:    d.ucIqamaFAJR || 0,
                shrouq:  d.ucIqamaSHRQ || 0,
                dhuhr:   d.ucIqamaDOHR || 0,
                asr:     d.ucIqamaASSR || 0,
                maghrib: d.ucIqamaMGRB || 0,
                isha:    d.ucIqamaISHA || 0
            },
            iqama_fixed: {
                fajr:  d.ucFixedIqamaFAJR || '',
                dhuhr: d.ucFixedIqamaDOHR || '',
                asr:   d.ucFixedIqamaASSR || '',
                isha:  d.ucFixedIqamaISHA || ''
            },
            jumua: {
                time:              d.ucJomoaFixedTime   || 'AUTO',
                show_on_hr_screen: d.ucJomoaOnHRscreen  || 0
            },
            primary_azan:        d.ucPrimaryAzanMinutes || 0,
            dohr_before_asr_min: d.ucDohrXminutesAsr    || 0,
            eid: {
                fitr_enabled: d.ucActivateEidFITR        || 0,
                fitr_time:   (d.ucTimeOfEidFITR          || '').trim(),
                adha_enabled: d.ucActivateEidADHA        || 0,
                adha_time:   (d.ucTimeOfEidADHA          || '').trim()
            },
            // Réglages Coran (JS_CUSTOM, pas JS_DATA -- cf. administration à
            // distance, _installRemoteMosqueAdmin plus bas). Un seul récitateur
            // représenté (le premier actif de JS_CUSTOM.ucReciters) : la liste
            // complète des récitateurs n'est pas un réglage "mosquée" au sens
            // de cette table, seul celui effectivement utilisé l'est.
            quran_settings: _buildQuranSettingsPayload()
        };
    }
    window._buildAdminPayload = _buildAdminPayload;   // accessible depuis console

    // NB : pas de champ "enabled" par prière -- depuis le relookage en
    // tableau (_buildQuranAutoStartTableHtml, _isAutoStartEnabledForPrayer),
    // une prière est active dès que son délai (minutes) est > 0, il n'existe
    // plus de case "actif" séparée dans le comportement réel de l'app (les
    // clés ucStartQuranBeforeAzanXxxEnabled restent dans JS_CUSTOM_DEFAULTS à
    // titre historique/diagnostic, mais ne pilotent plus rien). "days" est le
    // masque 7 caractères (dimanche→samedi, '1'=actif) déjà utilisé par cette
    // même grille locale -- repris ici à l'identique pour l'administration à
    // distance, cf. discussion 26/07/2026.
    function _buildQuranSettingsPayload() {
        var c = JS_CUSTOM;
        var _reciters = Array.isArray(c.ucReciters) ? c.ucReciters : [];
        var _active   = _reciters.filter(function(r) { return r.enabled == 1; });
        return {
            enabled: c.ucStartQuranBeforeAzan || 0,
            prayers: {
                FAJR: { delay: c.ucStartQuranBeforeAzanFajr || 0, days: c.ucStartQuranBeforeAzanFajrDays || '1111111' },
                DOHR: { delay: c.ucStartQuranBeforeAzanDohr || 0, days: c.ucStartQuranBeforeAzanDohrDays || '1111111' },
                ASSR: { delay: c.ucStartQuranBeforeAzanAsr  || 0, days: c.ucStartQuranBeforeAzanAsrDays  || '1111111' },
                MGRB: { delay: c.ucStartQuranBeforeAzanMgrb || 0, days: c.ucStartQuranBeforeAzanMgrbDays || '1111111' },
                ISHA: { delay: c.ucStartQuranBeforeAzanIsha || 0, days: c.ucStartQuranBeforeAzanIshaDays || '1111111' }
            },
            reciterDir: _active.length ? _active[0].dir : ''
        };
    }

    // ── Overlay preview ───────────────────────────────────────────────────
    var ov = document.createElement('div');
    ov.id = 'ucPayloadPreviewOverlay';
    ov.style.cssText = [
        'display:none', 'position:fixed', 'inset:0',
        'background:rgba(0,0,0,0.84)', 'z-index:999999',
        'align-items:center', 'justify-content:center',
        'padding:4vh 5%', 'box-sizing:border-box'
    ].join(';');

    ov.innerHTML = [
        '<div style="background:#0d0d1a;border:1px solid #c8a84b;border-radius:10px;',
        'padding:20px;width:100%;max-width:480px;color:#fff;font-family:monospace;',
        'display:flex;flex-direction:column;max-height:90vh;box-sizing:border-box;">',

        // titre
        '<p id="ucPreviewTitle" style="margin:0 0 10px;font-size:0.95em;',
        'color:#c8a84b;text-align:center;font-family:sans-serif;">Payload a envoyer</p>',

        // bloc JSON scrollable
        '<pre id="ucPreviewJson" style="background:#000;border-radius:6px;padding:12px;',
        'font-size:0.75em;overflow:auto;white-space:pre;color:#7fffaa;',
        'flex:1;min-height:0;margin:0 0 14px;"></pre>',

        // boutons
        '<div style="display:flex;gap:10px;justify-content:center;flex-shrink:0;">',
        '<span id="ucPreviewCancel" class="ucModalBtn ucModalBtn--secondary">Annuler</span>',
        '<span id="ucPreviewSend" class="ucModalBtn ucModalBtn--primary">Envoyer</span>',
        '</div></div>'
    ].join('');
    document.body.appendChild(ov);

    function _showPreview() {
        document.getElementById('ucPreviewJson').textContent =
            JSON.stringify(_buildAdminPayload(), null, 2);
        ov.style.display = 'flex';
    }
    function _hidePreview() { ov.style.display = 'none'; }

    document.getElementById('ucPreviewCancel').addEventListener('click', _hidePreview);
    // __ Credentials Supabase (surchargeable via MOSQUE_CONFIG) ____________
    var _SB_URL = (window.MOSQUE_CONFIG && window.MOSQUE_CONFIG.SUPABASE_URL)
               || 'https://tjmjmlzwzebocfdmifrg.supabase.co';
    var _SB_KEY = (window.MOSQUE_CONFIG && window.MOSQUE_CONFIG.SUPABASE_ANON_KEY)
               || 'sb_publishable_P9MMDcQw_mM4bLqCVCj_3A_tdTK5Tj4';

    // ── Envoi reel (POST /rest/v1/mosques) ────────────────────────────────
    // Extrait du handler ucPreviewSend pour pouvoir etre appele directement
    // depuis le bouton Notifier, sans passer par l'apercu JSON.
    function _sendPayload() {
        _hidePreview();
        var payload = _buildAdminPayload();
        var mc  = window.MOSQUE_CONFIG || {};
        var wc  = mc.WEATHER_COORDS || {};
        var row = {
            mosque_id:           payload.mosque_id,
            mosque_name:         mc.MOSQUE_NAME   || '',
            location_code:       mc.LOCATION_CODE || '',
            latitude:            wc.latitude  || null,
            longitude:           wc.longitude || null,
            time_flags:          payload.time_flags,
            azan_offsets:        payload.azan_offsets,
            iqama_delay:         payload.iqama_delay,
            iqama_fixed:         payload.iqama_fixed,
            jumua:               payload.jumua,
            eid:                 payload.eid,
            primary_azan:        payload.primary_azan,
            dohr_before_asr_min: payload.dohr_before_asr_min
        };
        var _L_SENDING = { AR: 'جارٍ الإرسال...', FR: 'Envoi en cours...', EN: 'Sending...' };
        _ucToast(_L_SENDING[_ucLang()] || _L_SENDING.EN, 'ok');
        fetch(_SB_URL + '/rest/v1/mosques', {
            method:  'POST',
            headers: {
                'apikey':        _SB_KEY,
                'Authorization': 'Bearer ' + _SB_KEY,
                'Content-Type':  'application/json',
                'Prefer':        'resolution=merge-duplicates'
            },
            body: JSON.stringify(row)
        })
        .then(function(r) {
            if (r.ok || r.status === 204) {
                _ucToast((window._ucAdminMsg && window._ucAdminMsg.notifOk) || 'Enregistre !', 'ok');
                _ucAddNotifHistory('notifier', '', true);
                // Tient aussi a jour la config complete distante (PIN inclus) sous
                // ce meme mosque_id -- independant du sync horaires ci-dessus,
                // n'affecte pas son toast/historique en cas d'echec isole.
                if (payload.mosque_id && window._ucPushRemoteBackup) {
                    window._ucPushRemoteBackup(payload.mosque_id, function(ok) {
                        _L('NOTIF', ok ? 'FULL_CONFIG_SYNCED' : 'FULL_CONFIG_SYNC_ERR', { mosque_id: payload.mosque_id });
                    });
                }
            } else {
                return r.text().then(function(t) {
                    _ucToast((window._ucAdminMsg && window._ucAdminMsg.notifErr) || 'Erreur : ' + r.status, 'err');
                    _L('NOTIF', 'SUPABASE_ERR', 'status=' + r.status + ' body=' + t.slice(0,200));
                    _ucAddNotifHistory('notifier', '', false);
                });
            }
        })
        .catch(function(e) {
            _ucToast((window._ucAdminMsg && window._ucAdminMsg.notifNetErr) || 'Erreur reseau', 'err');
            _L('NOTIF', 'NET_ERR', e.message || String(e));
            _ucAddNotifHistory('notifier', '', false);
        });
    }
    window._ucSendPayload = _sendPayload; // accessible depuis console / debug

    document.getElementById('ucPreviewSend').addEventListener('click', _sendPayload);

    // ── Override ucPinVerifyOk : apres PIN valide → envoi direct (plus d'apercu) ─
    // On clone le bouton pour supprimer l'ancien handler (TODO/toast factice), puis on rebranche.
    var oldBtn = document.getElementById('ucPinVerifyOk');
    if (oldBtn) {
        var newBtn = oldBtn.cloneNode(true);
        oldBtn.parentNode.replaceChild(newBtn, oldBtn);
        newBtn.addEventListener('click', function() {
            var inp   = document.getElementById('ucPinVerifyInput');
            var errEl = document.getElementById('ucPinVerifyErr');
            if (window._ucPinGuard && window._ucPinGuard.check(errEl)) return;
            var pin = (JS_CUSTOM && JS_CUSTOM.ucAdminPin) || _ucDefaultAdminPin();
            if (inp.value !== pin) {
                window._ucPinGuard && window._ucPinGuard.fail();
                errEl.textContent =
                    (window._ucAdminMsg && window._ucAdminMsg.pinErr) || 'Code PIN incorrect';
                inp.select();
                return;
            }
            window._ucPinGuard && window._ucPinGuard.success();
            document.getElementById('ucPinVerifyOverlay').style.display = 'none';
            _sendPayload();
        });
        // Le listener keydown (Enter) existant dans _installAdminNotifyPanel pointe
        // deja sur _el('ucPinVerifyOk') par ID → trouve le nouveau bouton. Pas de doublon.
    }

    _updateAdminLabels();
    _L('CUSTOM', 'INIT', { item: 'adminPayloadPreview' });
})();

// -- Panneau message personnalise (admin -> fideles) ----------------------
// Bouton 'Message' dans #ucAdminBtnRow -> overlay textarea + PIN -> POST Edge Function
// Edge Function mode : { type:'custom_message', mosque_id, mosque_name, message }
(function _installAdminMessagePanel() {
    // Traductions AR/FR/EN (auparavant mélange arabe/français figé au sein
    // de la MÊME modale -- titre/placeholder déjà corrigés via
    // _updateAdminLabels ci-dessus, mais placeholder PIN, boutons Annuler/
    // Envoyer et messages de validation restaient 100% français -- cf. audit
    // langue 25/07/2026).
    var L_MSGPANEL = {
        pinPlaceholder: { AR: 'رمز PIN', FR: 'Code PIN', EN: 'PIN code' },
        cancel:         { AR: 'إلغاء', FR: 'Annuler', EN: 'Cancel' },
        send:           { AR: 'إرسال', FR: 'Envoyer', EN: 'Send' },
        emptyMessage:   { AR: 'الرسالة فارغة', FR: 'Message vide', EN: 'Message is empty' },
        tooLong:        { AR: 'الرسالة طويلة جدًا ({len}/{max})', FR: 'Message trop long ({len}/{max})', EN: 'Message too long ({len}/{max})' },
        sending:        { AR: 'جارٍ الإرسال...', FR: 'Envoi en cours...', EN: 'Sending...' },
        sentOk:         { AR: 'تم إرسال الرسالة ✔', FR: 'Message envoyé ✔', EN: 'Message sent ✔' },
        networkError:   { AR: 'خطأ في الشبكة', FR: 'Erreur réseau', EN: 'Network error' }
    };
    function _mpT(key, vars) {
        var row = L_MSGPANEL[key];
        if (!row) return key;
        var s = row[_ucLang()] || row.EN;
        if (vars) Object.keys(vars).forEach(function (k) { s = s.replace('{' + k + '}', vars[k]); });
        return s;
    }

    var MC     = window.MOSQUE_CONFIG || {};
    var _SB_URL = MC.SUPABASE_URL     || 'https://tjmjmlzwzebocfdmifrg.supabase.co';
    var _SB_KEY = MC.SUPABASE_ANON_KEY|| 'sb_publishable_P9MMDcQw_mM4bLqCVCj_3A_tdTK5Tj4';
    var _FN_URL = _SB_URL + '/functions/v1/rapid-service';
    var MAX     = 150;

    // Ajouter bouton Message dans la barre admin --------------------------
    var line3 = document.getElementById('ucAdminBtnLine3');
    if (!line3) return;

    var btnMsg = document.createElement('button');
    btnMsg.type      = 'button';
    btnMsg.id        = 'ucMsgBtn';
    btnMsg.className = 'addSlideButtonClass cursorPointerClass';
    (function(){
        var _l = _ucLang();
        var _T = { AR:'رسالة', FR:'Message', EN:'Message', TR:'Mesaj', ID:'Pesan' };
        btnMsg.textContent = _T[_l] || _T.EN;
    })();
    // Ligne 3 : ucMsgBtn (droite) puis ucJanazaBtn (gauche, ajouté par
    // _installAdminJanazaPanel juste après).
    line3.appendChild(btnMsg);

    // Overlay -----------------------------------------------------------
    var OV  = 'display:none;position:fixed;inset:0;background:rgba(0,0,0,0.78);'
            + 'z-index:999999;align-items:center;justify-content:center;';
    var BOX = 'background:#1a1a2e;border:1px solid #c8a84b;border-radius:10px;'
            + 'padding:20px;width:92%;max-width:360px;color:#fff;'
            + 'font-family:inherit;box-sizing:border-box;';
    var ITA = 'width:100%;padding:8px;font-size:1em;background:#0d0d1a;'
            + 'border:1px solid #888;color:#fff;border-radius:6px;'
            + 'box-sizing:border-box;resize:none;font-family:inherit;';
    var IPN = 'width:220px;padding:8px;font-size:1.2em;letter-spacing:0.18em;'
            + 'text-align:center;background:#0d0d1a;border:1px solid #888;'
            + 'color:#fff;border-radius:6px;box-sizing:border-box;margin:10px auto 0;display:block;';
    var ERR = 'color:#ff4444;font-size:0.85em;min-height:1.2em;margin:6px 0 0;';
    var BRW = 'display:flex;gap:10px;justify-content:center;margin-top:14px;';

    var ov = document.createElement('div');
    ov.id = 'ucMsgOverlay';
    ov.style.cssText = OV;
    ov.innerHTML = [
        '<div style="' + BOX + '">',
        '<p style="margin:0 0 10px;font-size:1em;color:#c8a84b;text-align:center;">',
        'Message aux fid\u00e8les</p>',
        '<textarea id="ucMsgText" rows="4" maxlength="' + MAX + '"',
        ' placeholder="Votre message\u2026" style="' + ITA + '"></textarea>',
        '<div style="text-align:right;font-size:0.78em;color:#aaa;margin:2px 0 0;">',
        '<span id="ucMsgCount">0</span>/' + MAX + '</div>',
        '<input id="ucMsgPin" type="password" maxlength="8" inputmode="numeric"',
        ' placeholder="' + _mpT('pinPlaceholder') + '" style="' + IPN + '"/>',
        '<p id="ucMsgErr" style="' + ERR + '"></p>',
        '<div style="' + BRW + '">',
        '<span id="ucMsgCancel" class="ucModalBtn ucModalBtn--secondary">' + _mpT('cancel') + '</span>',
        '<span id="ucMsgSend"   class="ucModalBtn ucModalBtn--primary">' + _mpT('send') + '</span>',
        '</div></div>'
    ].join('');
    document.body.appendChild(ov);

    var _e = function(id) { return document.getElementById(id); };

    // Compteur de caracteres
    _e('ucMsgText').addEventListener('input', function() {
        _e('ucMsgCount').textContent = this.value.length;
    });

    // Ouverture overlay
    btnMsg.addEventListener('click', function() {
        _e('ucMsgText').value       = '';
        _e('ucMsgPin').value        = '';
        _e('ucMsgErr').textContent  = '';
        _e('ucMsgCount').textContent= '0';
        ov.style.display = 'flex';
        setTimeout(function() { _e('ucMsgText').focus(); }, 120);
    });

    // Fermeture
    _e('ucMsgCancel').addEventListener('click', function() {
        ov.style.display = 'none';
    });
    ov.addEventListener('click', function(evt) {
        if (evt.target === ov) ov.style.display = 'none';
    });

    // Envoi
    function _doSend() {
        var msg = (_e('ucMsgText').value || '').trim();
        var pin = _e('ucMsgPin').value;
        var storedPin = (typeof JS_CUSTOM !== 'undefined' && JS_CUSTOM.ucAdminPin) || _ucDefaultAdminPin();
        _e('ucMsgErr').textContent = '';
        if (window._ucPinGuard && window._ucPinGuard.check(_e('ucMsgErr'))) return;

        if (!msg) {
            _e('ucMsgErr').textContent = _mpT('emptyMessage');
            return;
        }
        if (msg.length > MAX) {
            _e('ucMsgErr').textContent = _mpT('tooLong', { len: msg.length, max: MAX });
            return;
        }
        if (pin !== storedPin) {
            window._ucPinGuard && window._ucPinGuard.fail();
            _e('ucMsgErr').textContent = (window._ucAdminMsg && window._ucAdminMsg.pinErr) || 'Wrong PIN';
            _e('ucMsgPin').select();
            return;
        }
        window._ucPinGuard && window._ucPinGuard.success();

        var mid   = MC.MOSQUE_ID || '';
        if (!mid) { try { mid = localStorage.getItem('UC_MOSQUE_ID') || ''; } catch(e) {} }
        var mname = MC.MOSQUE_NAME || mid;

        ov.style.display = 'none';
        window._ucToast && window._ucToast(_mpT('sending'), 'ok');

        fetch(_FN_URL, {
            method: 'POST',
            headers: {
                'Content-Type':  'application/json',
                'Authorization': 'Bearer ' + _SB_KEY,
                'apikey':        _SB_KEY
            },
            body: JSON.stringify({
                type:        'custom_message',
                notif_type:  'message',
                mosque_id:   mid,
                mosque_name: mname,
                message:     msg
            })
        })
        .then(function(r) { return r.json(); })
        .then(function(res) {
            _L('MSG', 'SENT', res);
            window._ucToast && window._ucToast(_mpT('sentOk'), 'ok');
            window._ucAddNotifHistory && window._ucAddNotifHistory('message', msg, true);
        })
        .catch(function(e) {
            _L('MSG', 'NET_ERR', e.message || String(e));
            window._ucToast && window._ucToast(_mpT('networkError'), 'err');
            window._ucAddNotifHistory && window._ucAddNotifHistory('message', msg, false);
        });
    }

    _e('ucMsgSend').addEventListener('click', _doSend);
    _e('ucMsgPin').addEventListener('keydown', function(ev) {
        if (ev.key === 'Enter') _doSend();
    });

    _updateAdminLabels();
    _L('CUSTOM', 'INIT', { item: 'adminMessagePanel' });
})();

