// -- Panneau Historique (admin) ---------------------------------------------
// Bouton 'Historique' dans #ucAdminBtnRow -> overlay listant les 5 derniers
// envois admin (Notifier / Message / Janaza), lus depuis UC_NOTIF_HISTORY
// (voir _ucAddNotifHistory, defini plus haut, appele par les 3 boutons d'envoi).
(function _installNotifHistoryPanel() {

    // Ligne 5 : protégée par le code PIN, seul sous ucNotifierBtn (ligne 4).
    var line5 = document.getElementById('ucAdminBtnLine5');
    if (!line5) return;

    var btnHist = document.createElement('button');
    btnHist.type      = 'button';
    btnHist.id        = 'ucHistoryBtn';
    btnHist.className = 'addSlideButtonClass cursorPointerClass';
    (function(){
        var _l = _ucLang();
        var _T = { AR:'سجل الإرساليات', FR:'Historique', EN:'History', TR:'Geçmiş', ID:'Riwayat' };
        btnHist.textContent = _T[_l] || _T.EN;
    })();
    // Ligne 5 : ucHistoryBtn seul, centré.
    line5.appendChild(btnHist);

    // Overlay -----------------------------------------------------------
    var OV  = 'display:none;position:fixed;inset:0;background:rgba(0,0,0,0.78);'
            + 'z-index:999999;align-items:center;justify-content:center;';
    var BOX = 'background:#1a1a2e;border:1px solid #c8a84b;border-radius:10px;'
            + 'padding:20px;width:92%;max-width:380px;color:#fff;'
            + 'font-family:inherit;box-sizing:border-box;max-height:80vh;'
            + 'display:flex;flex-direction:column;';

    var ov = document.createElement('div');
    ov.id = 'ucHistOverlay';
    ov.style.cssText = OV;
    ov.innerHTML = [
        '<div style="' + BOX + '">',
        '<p id="ucHistTitle" style="margin:0 0 12px;font-size:1em;color:#c8a84b;',
        'text-align:center;flex-shrink:0;">Historique des messages</p>',
        '<div id="ucHistList" style="overflow:auto;flex:1;min-height:0;"></div>',
        '<div style="display:flex;justify-content:center;margin-top:14px;flex-shrink:0;">',
        '<span id="ucHistClose" class="ucModalBtn ucModalBtn--secondary">Fermer</span>',
        '</div></div>'
    ].join('');
    document.body.appendChild(ov);

    var _e = function(id) { return document.getElementById(id); };

    function _lang() { return _ucLang(); }

    function _typeLabel(type) {
        var L = {
            notifier: { AR:'تحديث الأوقات', FR:'Mise à jour des horaires', EN:'Schedule update',  TR:'Takvim güncellemesi',     ID:'Pembaruan jadwal' },
            message:  { AR:'رسالة',         FR:'Message',                 EN:'Message',          TR:'Mesaj',                    ID:'Pesan' },
            janaza:   { AR:'جنازة',         FR:'Janaza',                  EN:'Janaza',           TR:'Cenaze',                   ID:'Janazah' }
        };
        var row = L[type] || L.message;
        return row[_lang()] || row.EN;
    }

    function _emptyLabel() {
        var L = { AR:'لا توجد رسائل مرسلة', FR:'Aucun message envoyé', EN:'No messages sent', TR:'Gönderilen mesaj yok', ID:'Belum ada pesan terkirim' };
        return L[_lang()] || L.EN;
    }

    function _fmtTs(iso) {
        var d = new Date(iso);
        if (isNaN(d.getTime())) return '';
        function p2(n) { return (n < 10 ? '0' : '') + n; }
        return p2(d.getDate()) + '/' + p2(d.getMonth() + 1) + ' ' + p2(d.getHours()) + ':' + p2(d.getMinutes());
    }

    function _renderHistory() {
        var list = _e('ucHistList');
        list.innerHTML = '';
        var arr = (window._ucGetNotifHistory && window._ucGetNotifHistory()) || [];

        if (!arr.length) {
            var empty = document.createElement('p');
            empty.style.cssText = 'color:#aaa;text-align:center;font-size:0.9em;margin:18px 0;';
            empty.textContent = _emptyLabel();
            list.appendChild(empty);
            return;
        }

        arr.forEach(function(item) {
            var row = document.createElement('div');
            row.style.cssText = 'border-left:3px solid ' + (item.ok ? '#4caf50' : '#ff4444')
                + ';background:rgba(255,255,255,0.04);border-radius:4px;'
                + 'padding:8px 10px;margin-bottom:8px;';

            var head = document.createElement('div');
            head.style.cssText = 'display:flex;justify-content:space-between;align-items:baseline;gap:8px;';

            var type = document.createElement('span');
            type.style.cssText = 'color:#c8a84b;font-size:0.88em;font-weight:bold;';
            type.textContent = _typeLabel(item.type) + (item.ok ? ' ✔' : ' ✖');

            var time = document.createElement('span');
            time.style.cssText = 'color:#aaa;font-size:0.78em;flex-shrink:0;';
            time.textContent = _fmtTs(item.ts);

            head.appendChild(time);
            head.appendChild(type);
            row.appendChild(head);

            if (item.body) {
                var body = document.createElement('div');
                body.style.cssText = 'color:#ddd;font-size:0.85em;margin-top:4px;white-space:pre-wrap;word-break:break-word;';
                body.textContent = item.body;
                row.appendChild(body);
            }

            list.appendChild(row);
        });
    }

    btnHist.addEventListener('click', function() {
        _renderHistory();
        ov.style.display = 'flex';
    });
    _e('ucHistClose').addEventListener('click', function() { ov.style.display = 'none'; });
    ov.addEventListener('click', function(evt) {
        if (evt.target === ov) ov.style.display = 'none';
    });

    _updateAdminLabels();
    _L('CUSTOM', 'INIT', { item: 'notifHistoryPanel' });
})();


// -- Synchronisation config Supabase (bouton MaJ) ---------------------------
(function _installConfigSync() {

    // Traductions AR/FR/EN (auparavant 100% français figé) -- cf. audit
    // langue 25/07/2026.
    var L_SYNC = {
        mosqueUndefined: { AR: 'المسجد غير محدد', FR: 'Mosquée non définie', EN: 'Mosque not defined' },
        syncing:         { AR: 'جارٍ المزامنة...', FR: 'Synchronisation...', EN: 'Syncing...' },
        noData:          { AR: 'لا توجد بيانات', FR: 'Aucune donnée', EN: 'No data' },
        configUpToDate:  { AR: 'الإعدادات محدّثة ✔', FR: 'Config à jour ✔', EN: 'Config up to date ✔' },
        networkError:    { AR: 'خطأ في الشبكة', FR: 'Erreur réseau', EN: 'Network error' }
    };
    function _syncT(key) {
        var row = L_SYNC[key];
        if (!row) return key;
        return row[_ucLang()] || row.EN;
    }

    var _SB_URL = (window.MOSQUE_CONFIG && window.MOSQUE_CONFIG.SUPABASE_URL)
               || 'https://tjmjmlzwzebocfdmifrg.supabase.co';
    var _SB_KEY = (window.MOSQUE_CONFIG && window.MOSQUE_CONFIG.SUPABASE_ANON_KEY)
               || 'sb_publishable_P9MMDcQw_mM4bLqCVCj_3A_tdTK5Tj4';

    function _applyRow(row) {
        if (row.time_flags) {
            JS_DATA.ucRamadanDoIsha30min = row.time_flags.ramadan_isha_30min || 0;
            JS_DATA.ucInSummerAdd1Hour   = row.time_flags.summer_time        || 0;
            JS_DATA.ucForce1HourMore     = row.time_flags.force_1h_more      || 0;
            JS_DATA.ucForce1HourLess     = row.time_flags.force_1h_less      || 0;
        }
        if (row.azan_offsets) {
            JS_DATA.ucAthanMinutesFAJR = row.azan_offsets.fajr    || 0;
            JS_DATA.ucAthanMinutesSHRQ = row.azan_offsets.shrouq  || 0;
            JS_DATA.ucAthanMinutesDOHR = row.azan_offsets.dhuhr   || 0;
            JS_DATA.ucAthanMinutesASSR = row.azan_offsets.asr     || 0;
            JS_DATA.ucAthanMinutesMGRB = row.azan_offsets.maghrib || 0;
            JS_DATA.ucAthanMinutesISHA = row.azan_offsets.isha    || 0;
        }
        if (row.iqama_delay) {
            JS_DATA.ucIqamaFAJR = row.iqama_delay.fajr    || 0;
            JS_DATA.ucIqamaSHRQ = row.iqama_delay.shrouq  || 0;
            JS_DATA.ucIqamaDOHR = row.iqama_delay.dhuhr   || 0;
            JS_DATA.ucIqamaASSR = row.iqama_delay.asr     || 0;
            JS_DATA.ucIqamaMGRB = row.iqama_delay.maghrib || 0;
            JS_DATA.ucIqamaISHA = row.iqama_delay.isha    || 0;
        }
        if (row.iqama_fixed) {
            JS_DATA.ucFixedIqamaFAJR = row.iqama_fixed.fajr  || '';
            JS_DATA.ucFixedIqamaDOHR = row.iqama_fixed.dhuhr || '';
            JS_DATA.ucFixedIqamaASSR = row.iqama_fixed.asr   || '';
            JS_DATA.ucFixedIqamaISHA = row.iqama_fixed.isha  || '';
        }
        if (row.jumua) {
            JS_DATA.ucJomoaFixedTime  = row.jumua.time              || 'AUTO';
            JS_DATA.ucJomoaOnHRscreen = row.jumua.show_on_hr_screen || 0;
        }
        JS_DATA.ucPrimaryAzanMinutes = row.primary_azan        || 0;
        JS_DATA.ucDohrXminutesAsr    = row.dohr_before_asr_min || 0;
        if (row.eid) {
            JS_DATA.ucActivateEidFITR = row.eid.fitr_enabled || 0;
            JS_DATA.ucTimeOfEidFITR   = row.eid.fitr_time    || '';
            JS_DATA.ucActivateEidADHA = row.eid.adha_enabled || 0;
            JS_DATA.ucTimeOfEidADHA   = row.eid.adha_time    || '';
        }
        // Réglages Coran (JS_CUSTOM, pas JS_DATA -- cf. _buildQuranSettingsPayload
        // plus haut pour le sens inverse, administration à distance).
        if (row.quran_settings) {
            var qs = row.quran_settings;
            JS_CUSTOM.ucStartQuranBeforeAzan = qs.enabled || 0;
            if (qs.prayers) {
                // Pas de clé "Enabled" ici : une prière Coran est active dès
                // que son délai (secondes) est > 0 -- cf. commentaire de
                // _buildQuranSettingsPayload plus haut, même convention que
                // la grille locale _buildQuranAutoStartTableHtml.
                var _qMap = {
                    FAJR: ['ucStartQuranBeforeAzanFajr', 'ucStartQuranBeforeAzanFajrDays'],
                    DOHR: ['ucStartQuranBeforeAzanDohr', 'ucStartQuranBeforeAzanDohrDays'],
                    ASSR: ['ucStartQuranBeforeAzanAsr',  'ucStartQuranBeforeAzanAsrDays'],
                    MGRB: ['ucStartQuranBeforeAzanMgrb', 'ucStartQuranBeforeAzanMgrbDays'],
                    ISHA: ['ucStartQuranBeforeAzanIsha', 'ucStartQuranBeforeAzanIshaDays']
                };
                Object.keys(_qMap).forEach(function(k) {
                    var p = qs.prayers[k];
                    if (!p) return;
                    JS_CUSTOM[_qMap[k][0]] = p.delay || 0;
                    JS_CUSTOM[_qMap[k][1]] = p.days   || '1111111';
                });
            }
            if (qs.reciterDir && Array.isArray(JS_CUSTOM.ucReciters)) {
                JS_CUSTOM.ucReciters.forEach(function(r) { r.enabled = (r.dir === qs.reciterDir) ? 1 : 0; });
            }
            if (typeof saveCustomSettingsFunction === 'function') saveCustomSettingsFunction();
        }
        try { localStorage.setItem('JS_DATA', JSON.stringify(JS_DATA)); } catch(e) {}
        if (typeof calculateAndDisplayTimesFunction === 'function')
            calculateAndDisplayTimesFunction();
        _L('SYNC', 'APPLIED', { mosque_id: row.mosque_id });
        // Rechargement complet apres 1.2 s pour rafraichir tout l'affichage
        setTimeout(function() { location.reload(); }, 1200);
    }

    window._ucSyncFromSupabase = function(mosqueId, silent) {
        var mid = mosqueId || (window.MOSQUE_CONFIG && window.MOSQUE_CONFIG.MOSQUE_ID) || '';
        if (!mid) { try { mid = localStorage.getItem('UC_MOSQUE_ID') || ''; } catch(e) {} }
        if (!mid) { if (!silent) window._ucToast && window._ucToast(_syncT('mosqueUndefined'), 'err'); return; }
        if (!silent) window._ucToast && window._ucToast(_syncT('syncing'), 'ok');
        fetch(_SB_URL + '/rest/v1/mosques?mosque_id=eq.' + encodeURIComponent(mid) + '&select=*',
              { headers: { 'apikey': _SB_KEY, 'Authorization': 'Bearer ' + _SB_KEY } })
        .then(function(r) { return r.json(); })
        .then(function(rows) {
            if (!rows || !rows.length) { window._ucToast && window._ucToast(_syncT('noData'), 'err'); return; }
            _applyRow(rows[0]);
            window._ucToast && window._ucToast(_syncT('configUpToDate'), 'ok');
        })
        .catch(function(e) {
            _L('SYNC', 'ERR', e.message || String(e));
            window._ucToast && window._ucToast(_syncT('networkError'), 'err');
        });
    };

    // Ligne 1 : toujours accessible, indépendamment du code PIN.
    var alwaysRow = document.getElementById('ucAdminAlwaysRow');
    if (alwaysRow) {
        var btnMaj = document.createElement('button');
        btnMaj.type      = 'button';
        btnMaj.id        = 'ucMaJBtn';
        btnMaj.className = 'addSlideButtonClass cursorPointerClass';
        (function(){
            var _l = _ucLang();
            var _T = { AR:'تنزيل', FR:'Mise à jour', EN:'Update', TR:'Güncelle', ID:'Perbarui' };
            btnMaj.textContent = _T[_l] || _T.EN;
        })();
        // Ligne 1 : ucMaJBtn seul, centré.
        alwaysRow.appendChild(btnMaj);
        btnMaj.addEventListener('click', function() { window._ucSyncFromSupabase(); });
    }

    window.addEventListener('ucConfigSync', function(e) {
        var mid = (e.detail && e.detail.mosque_id) || '';
        _L('SYNC', 'NOTIF_TAP', { mosque_id: mid });
        window._ucSyncFromSupabase(mid, true);
    });

    // ── Actions à distance (onglet "Actions" de _installRemoteMosqueAdmin) ──
    // Dispatché par MainActivity.kt (dispatchRemoteAction) à la réception du
    // push silencieux OneSignal type="remote_action" -- aucune écriture
    // Supabase associée (contrairement à ucConfigSync), ce sont des commandes
    // ponctuelles "fais ça maintenant", pas des changements de configuration.
    window.addEventListener('ucRemoteAction', function (e) {
        var action = (e.detail && e.detail.action) || '';
        var target = (e.detail && e.detail.target) || '';
        _L('REMOTE_ACTION', 'FIRE', { action: action, target: target });

        if (action === 'quran_toggle') {
            var qAudio = document.getElementById('quranAudioPlayer');
            if (qAudio) {
                if (qAudio.paused) qAudio.play().catch(function () {}); else qAudio.pause();
            }
            return;
        }
        if (action === 'azan_preview') {
            if (typeof window._acPreviewCurrentlySelected === 'function') window._acPreviewCurrentlySelected();
            return;
        }
        if (action === 'light_on' || action === 'light_off') {
            var isOn = (action === 'light_on');
            var URL_KEY = {
                ampliExt: isOn ? 'ucLightAmpliExtOnUrl' : 'ucLightAmpliExtOffUrl',
                ampliInt: isOn ? 'ucLightAmpliIntOnUrl' : 'ucLightAmpliIntOffUrl',
                minaret:  isOn ? 'ucLightMinaretOnUrl'  : 'ucLightMinaretOffUrl',
                mihrab:   isOn ? 'ucLightMihrabOnUrl'   : 'ucLightMihrabOffUrl'
            }[target];
            var url = URL_KEY && (JS_CUSTOM[URL_KEY] || '').trim();
            if (url) _ucHttpCall(url, 'remote_' + target + '_' + action);
            return;
        }
    });

    _L('CUSTOM', 'INIT', { item: 'configSync' });
})();

// ═══════════════════════════════════════════════════════════════════════════
// POLLING DE SECOURS POUR L'ADMINISTRATION À DISTANCE (filet de sécurité)
// ─────────────────────────────────────────────────────────────────────────────
// Le chemin rapide est le push OneSignal silencieux (cf. MainActivity.kt
// addForegroundLifecycleListener + rapid-service mode remote_config_update),
// mais un push peut échouer/être retardé (Doze, réseau) -- ce polling léger
// (toutes les ~18s, une seule colonne updated_at lue à chaque fois) rattrape
// systématiquement tout changement sous ~20s au pire, même en son absence.
// Tourne sur tout appareil ayant une mosquée sélectionnée (pas seulement les
// box) : l'auto-limitation vient de webView.pauseTimers() (custom.js ne
// s'exécute que quand l'app est réellement au premier plan) -- même
// mécanisme, aucun cas particulier nécessaire pour distinguer téléphone/box.
// ═══════════════════════════════════════════════════════════════════════════
(function _installRemoteConfigPolling() {
    var POLL_MS = 18000;
    var _lastKnownUpdatedAt = null;
    var _SB_URL = (window.MOSQUE_CONFIG && window.MOSQUE_CONFIG.SUPABASE_URL)
               || 'https://tjmjmlzwzebocfdmifrg.supabase.co';
    var _SB_KEY = (window.MOSQUE_CONFIG && window.MOSQUE_CONFIG.SUPABASE_ANON_KEY)
               || 'sb_publishable_P9MMDcQw_mM4bLqCVCj_3A_tdTK5Tj4';

    function _poll() {
        var mid = (window.MOSQUE_CONFIG && window.MOSQUE_CONFIG.MOSQUE_ID) || '';
        if (!mid) return;
        fetch(_SB_URL + '/rest/v1/mosques?mosque_id=eq.' + encodeURIComponent(mid) + '&select=updated_at',
              { headers: { 'apikey': _SB_KEY, 'Authorization': 'Bearer ' + _SB_KEY } })
        .then(function(r) { return r.json(); })
        .then(function(rows) {
            var row = rows && rows[0];
            if (!row || !row.updated_at) return;
            if (_lastKnownUpdatedAt === null) {
                // Amorçage silencieux : mémorise la valeur courante sans rien
                // déclencher -- évite un reload parasite juste après le
                // chargement (on ne sait pas encore si ça a "changé" depuis).
                _lastKnownUpdatedAt = row.updated_at;
                return;
            }
            if (row.updated_at !== _lastKnownUpdatedAt) {
                _lastKnownUpdatedAt = row.updated_at;
                _L('SYNC', 'POLL_CHANGE_DETECTED', { mosque_id: mid, updated_at: row.updated_at });
                if (typeof window._ucSyncFromSupabase === 'function') window._ucSyncFromSupabase(mid, true);
            }
        })
        .catch(function() {}); // silencieux -- prochain cycle réessaiera
    }

    setTimeout(_poll, 5000);
    setInterval(_poll, POLL_MS);

    _L('CUSTOM', 'INIT', { item: 'remoteConfigPolling' });
})();

(function _installAdminBtnTooltips() {
    var LANG = _ucLang();

    var TIPS = {
        ucPinChangeBtn: {
            AR: 'تغيير رمز PIN للوحة الإدارية',
            FR: 'Modifier le code PIN du panneau administrateur',
            EN: 'Change the admin panel PIN code',
            TR: 'Yönetici paneli PIN kodunu değiştir',
            ID: 'Ubah kode PIN panel admin',
        },
        ucMsgBtn: {
            AR: 'إرسال رسالة مخصصة إلى المصلين عبر إشعار',
            FR: 'Envoyer un message personnalisé aux fidèles par notification',
            EN: 'Send a custom message to followers via notification',
            TR: 'Cemaate kişisel mesaj gönder',
            ID: 'Kirim pesan khusus ke jamaah via notifikasi',
        },
        ucNotifierBtn: {
            AR: 'إرسال إشعار بتحديث أوقات الصلاة إلى المصلين',
            FR: "Notifier les fidèles d'une mise à jour des horaires de prière",
            EN: 'Notify followers of a prayer schedule update',
            TR: 'Cemaatı namaz vakitleri güncellemesi hakkında bildir',
            ID: 'Beritahu jamaah tentang pembaruan jadwal shalat',
        },
        ucMaJBtn: {
            AR: 'تنزيل آخر تحديث للأوقات من المشرف',
            FR: "Récupérer la dernière mise à jour des horaires envoyée par l'administrateur",
            EN: 'Download the latest schedule update from the administrator',
            TR: "Yöneticinin gönderdiği en son takvim güncellemesini indir",
            ID: 'Unduh pembaruan jadwal terbaru dari administrator',
        },
        ucJanazaBtn: {
            AR: 'إعلان جنازة جديدة',
            FR: "Publier un avis de décès et l'heure de la prière de Janaza",
            EN: "Publish a funeral notice and Janaza prayer time",
        },
        ucHistoryBtn: {
            AR: 'عرض آخر 5 رسائل مرسلة',
            FR: "Consulter les 5 derniers messages envoyés",
            EN: "View the last 5 messages sent",
        },
    };

    /* Tooltip DOM element (single shared, positioned via fixed) */
    var tip = document.createElement('div');
    tip.id = 'ucAdminTooltip';
    document.body.appendChild(tip);

    var _showTimer = null;
    var _hideTimer = null;

    function _show(btn) {
        var msgs = TIPS[btn.id];
        if (!msgs) return;
        clearTimeout(_hideTimer);
        tip.textContent = msgs[LANG] || msgs.EN;
        var r    = btn.getBoundingClientRect();
        var tw   = tip.offsetWidth  || 230;
        var th   = tip.offsetHeight || 42;
        var left = r.left + r.width / 2 - tw / 2;
        var top  = r.top - th - 10;
        left = Math.max(8, Math.min(left, window.innerWidth - tw - 8));
        if (top < 8) top = r.bottom + 10;
        tip.style.left = left + 'px';
        tip.style.top  = top  + 'px';
        tip.classList.add('ucAdminTooltip--visible');
        console.log('[TOOLTIP] show', btn.id, 'at', left.toFixed(0), top.toFixed(0), 'tw=', tw, 'th=', th, 'rect=', r.top.toFixed(0), r.left.toFixed(0));
        _hideTimer = setTimeout(_hide, 4000);
    }

    function _hide() {
        clearTimeout(_showTimer);
        clearTimeout(_hideTimer);
        tip.classList.remove('ucAdminTooltip--visible');
    }

    var _foundCount = 0;
    Object.keys(TIPS).forEach(function(id) {
        var btn = document.getElementById(id);
        if (!btn) { console.warn('[TOOLTIP] btn not found:', id); return; }
        _foundCount++;

        /* Desktop : hover with 400 ms delay */
        btn.addEventListener('mouseenter', function() {
            clearTimeout(_showTimer);
            var self = this;
            _showTimer = setTimeout(function() { _show(self); }, 400);
        });
        btn.addEventListener('mouseleave', _hide);

        /* Touch / Android : long-press 700 ms */
        btn.addEventListener('touchstart', function() {
            clearTimeout(_showTimer);
            var self = this;
            _showTimer = setTimeout(function() { _show(self); }, 700);
        }, { passive: true });
        btn.addEventListener('touchend',  _hide);
        btn.addEventListener('touchmove', _hide);
    });

    console.log('[TOOLTIP] init, buttons found:', _foundCount);
    _L('CUSTOM', 'INIT', { item: 'adminBtnTooltips' });
})();

// ── Désactivation de tvPointerImage sur téléphone Android ───────────────────
// tvPointerImage (souris virtuelle pilotée au D-pad : flèches pour la
// déplacer, Entrée pour cliquer — cf. rootElement.onkeydown, m2body.js
// ~8561) est une fonctionnalité 100% core, pensée pour les boîtiers TV
// pilotés à la télécommande. Sur un téléphone Android (écran tactile), elle
// n'a pas lieu d'être et doit rester désactivée — mais elle doit continuer à
// fonctionner normalement sur tout autre environnement (boîtier TV,
// navigateur Windows/PC, etc.). On ne désactive donc QUE si le bridge natif
// confirme explicitement "téléphone" (isAndroidTv() === false) ; en
// l'absence du bridge (navigateur, PC — pas d'app Android du tout), on ne
// touche à rien et le comportement core reste actif.
(function _disableTvPointerOnPhone() {
    var isPhone = !!(window.AndroidMobile && typeof window.AndroidMobile.isAndroidTv === 'function'
        && !window.AndroidMobile.isAndroidTv());
    if (!isPhone) return;

    // rootElement (m1prime.js ~ligne 6) === document.documentElement : on
    // intercepte ici l'unique point d'entrée du mécanisme
    // (rootElement.onkeydown, m2body.js) sans jamais éditer les fichiers
    // core. Flèches (37-40) + Entrée (13) sont les seules touches qui
    // activent/déplacent/valident le pointeur (cf. commentaire du fix
    // suivant) — on les avale silencieusement ; toute autre touche continue
    // de suivre le comportement core normalement.
    var _origOnKeyDown = document.documentElement.onkeydown;
    document.documentElement.onkeydown = function(e) {
        var code = e.keyCode;
        if (code === 37 || code === 38 || code === 39 || code === 40 || code === 13) return;
        if (typeof _origOnKeyDown === 'function') return _origOnKeyDown.call(this, e);
    };

    // Le pointeur est déjà masqué par défaut (visibility:hidden, cf.
    // style1/2.css) et ne peut plus être révélé par le handler ci-dessus :
    // on force quand même l'état par sécurité (ex. appui survenu avant
    // l'exécution de ce script).
    var tvImg = document.getElementById('tvPointerImage');
    if (tvImg) tvImg.style.visibility = 'hidden';

    _L('CUSTOM', 'INIT', { item: 'disableTvPointerOnPhone' });
})();

// ── Fix compatibilité tvPointerImage ─────────────────────────────────────────
// Problème : simulateClick() appelle elementFromPoint() puis .click() sur le
// résultat. Si le pointeur atterrit sur un espace vide entre deux boutons
// (aucun handler de clic), rien ne se passe.
// Solution : délégation sur chaque conteneur de boutons admin — tout clic qui
// bulle depuis un élément non-bouton est redirigé vers le bouton le plus
// proche (distance horizontale du centre). Seuil 80 px pour éviter les faux
// positifs. Deux conteneurs distincts depuis la réorganisation en 5 lignes :
// #ucAdminAlwaysRow (ligne 1, sans code PIN) et #ucAdminBtnRow (lignes 3/4/5,
// protégées par le cadenas).
(function _fixAdminBtnTvPointer() {
    function _wire(container, btnIds) {
        if (!container) return;
        container.addEventListener('click', function(e) {
            // Si le clic vient directement d'un bouton, laisser son handler gérer
            if (btnIds.indexOf(e.target.id) !== -1) return;

            // Trouver le bouton le plus proche par distance horizontale du centre
            var x = e.clientX;
            var nearest = null;
            var minD = Infinity;
            btnIds.forEach(function(id) {
                var btn = document.getElementById(id);
                if (!btn) return;
                var r = btn.getBoundingClientRect();
                var d = Math.abs(x - (r.left + r.width / 2));
                if (d < minD) { minD = d; nearest = btn; }
            });

            // Déléguer seulement si on est à moins de 80 px d'un bouton
            if (nearest && minD < 80) {
                e.stopPropagation();
                nearest.click();
            }
        });
    }
    _wire(document.getElementById('ucAdminAlwaysRow'), ['ucMaJBtn']);
    _wire(document.getElementById('ucAdminBtnRow'),    ['ucPinChangeBtn', 'ucMsgBtn', 'ucNotifierBtn', 'ucJanazaBtn', 'ucHistoryBtn']);

    _L('CUSTOM', 'INIT', { item: 'adminBtnTvPointerFix' });
})();

// ── Verrou d'accès admin : rangée masquée par défaut, cadenas discret ──────
// (sécurité : l'APK est installé chez tout le monde, mais seule une
// population restreinte doit accéder à l'administration — une rangée de
// boutons toujours visible incite à tenter de deviner le PIN). Le cadenas
// remplace #ucAdminBtnRow tant que l'app n'est pas déverrouillée sur CET
// écran. Déverrouillage manuel uniquement : reste actif jusqu'au clic sur
// "Verrouiller" ou au redémarrage de l'app (rien n'est persisté).
// #ucAdminBtnRow/#ucAdminLockBtn sont relocalisés (une seule fois, par
// _relocateAdminRow dans _installMosqueInfoModal) dans
// #ucMosqueInfoAdminSection dès la première ouverture de cette modale — ce
// sont alors les MÊMES éléments DOM (pas une copie), donc cette bascule
// continue de s'appliquer normalement où qu'ils vivent.
(function _installAdminBtnLockGate() {
    var row = document.getElementById('ucAdminBtnRow');
    if (!row) return;

    window._ucAdminUnlocked = false;

    // ── Cadenas : remplace visuellement la rangée tant que verrouillé ──────
    var lockBtn = document.createElement('span');
    lockBtn.id        = 'ucAdminLockBtn';
    lockBtn.className = 'clickableWhiteClass';
    lockBtn.textContent = '🔒'; // 🔒
    lockBtn.setAttribute('role', 'button');
    row.parentNode.insertBefore(lockBtn, row);
    // Filet de sécurité : row (donc lockBtn, son voisin direct) est déjà
    // rattachée à #ucMosqueInfoAdminSection à ce stade (cf.
    // _installAdminNotifyPanel plus haut) ; on rappelle quand même
    // _ucRelocateAdminRow() pour couvrir le cas de repli où elle ne l'aurait
    // exceptionnellement pas été.
    if (typeof window._ucRelocateAdminRow === 'function') window._ucRelocateAdminRow();

    // ── Overlay de déverrouillage (mêmes styles que les autres overlays PIN) ──
    // z-index volontairement au-delà de tout le reste (cf. #ucAdminTooltip,
    // même valeur max) : ce prompt PIN est désormais aussi déclenché DEPUIS
    // #ucBoxAdminOverlay (mode box horizontal, cf. _installBoxHorizontalAdminAccess
    // plus bas) -- à z-index égal (999999 des deux côtés), l'ordre DOM faisait
    // gagner #ucBoxAdminOverlay (ajouté après <body> dans <html>), cachant le
    // prompt PIN DERRIÈRE la boîte qui vient pourtant de le déclencher (retour
    // utilisateur 29/07/2026). Un prompt PIN doit toujours pouvoir passer
    // au-dessus de N'IMPORTE QUEL overlay admin, quel qu'il soit.
    var OV  = 'display:none;position:fixed;inset:0;background:rgba(0,0,0,0.78);'
            + 'z-index:2147483647;align-items:center;justify-content:center;';
    var BOX = 'background:#1a1a2e;border:1px solid #555;border-radius:10px;'
            + 'padding:24px;min-width:270px;text-align:center;color:#fff;'
            + 'font-family:inherit;box-sizing:border-box;';
    var INP = 'width:220px;padding:8px;font-size:1.25em;letter-spacing:0.18em;'
            + 'text-align:center;background:#0d0d1a;border:1px solid #888;'
            + 'color:#fff;border-radius:6px;box-sizing:border-box;margin:0 auto;display:block;';
    var ERR = 'color:#ff4444;font-size:0.85em;min-height:1.2em;margin:8px 0 0;';
    var BRW = 'display:flex;gap:10px;justify-content:center;margin-top:14px;';

    var ov = document.createElement('div');
    ov.id = 'ucAdminUnlockOverlay';
    ov.style.cssText = OV;
    ov.innerHTML = [
        '<div style="' + BOX + '">',
        '<p id="ucAdminUnlockTitle" style="margin:0 0 14px;font-size:1.1em;">Code PIN administrateur</p>',
        '<input id="ucAdminUnlockInput" type="password" maxlength="8" inputmode="numeric" style="' + INP + '"/>',
        '<p id="ucAdminUnlockErr" style="' + ERR + '"></p>',
        '<div style="' + BRW + '">',
        '<span id="ucAdminUnlockCancel" class="ucModalBtn ucModalBtn--secondary">Annuler</span>',
        '<span id="ucAdminUnlockOk"     class="ucModalBtn ucModalBtn--primary">OK</span>',
        '</div></div>'
    ].join('');
    document.body.appendChild(ov);

    function _el(id) { return document.getElementById(id); }

    // ── Rafraîchit l'affichage (Réglages + miroir modale) selon l'état partagé ──
    function _refreshUI() {
        var unlocked = !!window._ucAdminUnlocked;
        row.style.display   = unlocked ? 'flex' : 'none';
        lockBtn.textContent  = unlocked ? '🔓' : '🔒'; // 🔓 / 🔒
        lockBtn.title        = unlocked
            ? ((window._ucAdminMsg && window._ucAdminMsg.lockBtn) || 'Verrouiller')
            : '';
        // lightProgrammingButton + menuFooterLinks suivent EXACTEMENT la même
        // règle de visibilité que ucMosqueProfileEditBtn (_mosqueProfileCanEdit,
        // _installMosqueInfoModal) : mosquée anonyme (pas de vrai propriétaire
        // à protéger) OU admin déverrouillé — plus de prompt PIN à chaque clic
        // pour lightProgrammingButton, l'accès est désormais conditionné à
        // l'état global déjà déverrouillé ailleurs (calcul inline, pas d'appel
        // à _mosqueProfileCanEdit : IIFE différente, cf. convention "eager-safe"
        // déjà utilisée dans ce fichier).
        var _mid = ''; try { _mid = localStorage.getItem('UC_MOSQUE_ID') || ''; } catch (e) {}
        var _isAnon = (!_mid || _mid === 'anonymous.generic');
        var _canSee = _isAnon || unlocked;
        var lightBtn = document.getElementById('lightProgrammingButton');
        if (lightBtn) lightBtn.style.display = _canSee ? '' : 'none';
        var footerLinks = document.getElementById('menuFooterLinks');
        if (footerLinks) footerLinks.style.display = _canSee ? '' : 'none';
    }
    window._ucRefreshAdminBtnLock = _refreshUI;

    window._ucOpenAdminUnlockOverlay = function() {
        _el('ucAdminUnlockInput').value     = '';
        _el('ucAdminUnlockErr').textContent = '';
        ov.style.display = 'flex';
        _el('ucAdminUnlockInput').focus();
    };
    // ── Bascule partagée : appelée par le cadenas (Réglages ET miroir modale) ──
    window._ucToggleAdminLock = function() {
        if (window._ucAdminUnlocked) {
            window._ucAdminUnlocked = false;
            _refreshUI();
        } else {
            window._ucOpenAdminUnlockOverlay();
        }
    };

    lockBtn.addEventListener('click', function() { window._ucToggleAdminLock(); });
    _el('ucAdminUnlockCancel').addEventListener('click', function() { ov.style.display = 'none'; });
    _el('ucAdminUnlockOk').addEventListener('click', function() {
        var errEl = _el('ucAdminUnlockErr');
        if (window._ucPinGuard && window._ucPinGuard.check(errEl)) return;
        var pin = (typeof JS_CUSTOM !== 'undefined' && JS_CUSTOM.ucAdminPin) || _ucDefaultAdminPin();
        if (_el('ucAdminUnlockInput').value !== pin) {
            window._ucPinGuard && window._ucPinGuard.fail();
            errEl.textContent = (window._ucAdminMsg && window._ucAdminMsg.pinErr) || 'Code PIN incorrect';
            _el('ucAdminUnlockInput').select();
            return;
        }
        window._ucPinGuard && window._ucPinGuard.success();
        window._ucAdminUnlocked = true;
        ov.style.display = 'none';
        _refreshUI();
    });
    _el('ucAdminUnlockInput').addEventListener('keydown', function(e) {
        if (e.key === 'Enter') _el('ucAdminUnlockOk').click();
    });

    _refreshUI();
    if (typeof _updateAdminLabels === 'function') _updateAdminLabels();
    _L('CUSTOM', 'INIT', { item: 'adminBtnLockGate' });
})();

// ══════════════════════════════════════════════════════════════════════════
// ── ACCÈS ADMIN DÉDIÉ — MODE BOX HORIZONTAL ─────────────────────────────────
// window._ucOpenMosqueInfoModal (plus haut, _installMosqueInfoModal) refuse
// explicitement de s'ouvrir en mode horizontal ("if (isHorizontalOrientation)
// return;") -- ce comportement reste INCHANGÉ (la mise en page de cette
// modale n'est pas adaptée à un grand écran horizontal). Or c'est l'unique
// point d'entrée vers le cadenas admin (PIN, Notifier, Message, Janaza,
// Historique) : sur une box, ni le nom de la mosquée (zone parfois occupée
// par un logo), ni l'affichage jomoaa n'offrent d'autre déclencheur --
// l'administrateur de la box n'a donc AUCUN moyen d'y accéder (retour
// utilisateur 29/07/2026).
//
// Solution : un nouvel élément de menu séparé, sous "locationSettingsButton",
// visible UNIQUEMENT en mode horizontal, qui ouvre un mini-overlay dédié au
// gabarit adapté (largeur bornée, comme #ucBoxControlModal). Il réutilise les
// VRAIS éléments admin (#ucAdminAlwaysRow/#ucAdminLockBtn/#ucAdminBtnRow,
// créés par _installAdminNotifyPanel/_installAdminBtnLockGate) en les
// déplaçant temporairement (appendChild déplace, ne copie pas -- mêmes
// écouteurs, même état de verrouillage partagé) et les restaure dans
// #ucMosqueInfoAdminSection à la fermeture via window._ucRelocateAdminRow
// (déjà exposé pour ce genre de filet de sécurité). Aucune duplication de
// logique PIN/Notifier/Message/Janaza, aucun changement du comportement
// existant en vertical.
// ══════════════════════════════════════════════════════════════════════════
(function _installBoxHorizontalAdminAccess() {
    var locBtn    = document.getElementById('locationSettingsButton');
    var container = document.getElementById('menuSectionsContainer');
    if (!locBtn || !container) return;

    var L_BA = {
        menuLabel: { AR: 'إدارة المسجد', FR: 'Administration mosquée', EN: 'Mosque administration' }
    };
    function _baT(key) { return (L_BA[key] && (L_BA[key][_ucLang()] || L_BA[key].EN)) || key; }
    function _isHR() { return (typeof isHorizontalOrientation !== 'undefined') && isHorizontalOrientation; }

    // ── Bouton de menu, juste après "locationSettingsButton" ───────────────
    var menuBtn = document.createElement('div');
    menuBtn.id = 'ucBoxAdminMenuButton';
    menuBtn.innerHTML = (typeof bulletPointSymbol !== 'undefined' ? bulletPointSymbol : '') + '&#128274; ' + _baT('menuLabel');
    if (locBtn.nextSibling) container.insertBefore(menuBtn, locBtn.nextSibling);
    else container.appendChild(menuBtn);

    function _syncMenuBtnVisibility() {
        menuBtn.style.display = _isHR() ? '' : 'none';
    }
    _syncMenuBtnVisibility();
    window.addEventListener('resize', function () {
        if (typeof detectOrientationFunction === 'function') detectOrientationFunction();
        _syncMenuBtnVisibility();
    });

    // ── Overlay dédié (gabarit borné, cf. #ucBoxControlModal) ───────────────
    var overlay = document.createElement('div');
    overlay.id = 'ucBoxAdminOverlay';
    overlay.innerHTML =
        '<div id="ucBoxAdminModal">' +
            '<div id="ucBoxAdminHeader">' +
                '<span id="ucBoxAdminTitle">&#128274; ' + _baT('menuLabel') + '</span>' +
                '<span id="ucBoxAdminClose">&#10006;</span>' +
            '</div>' +
            '<div id="ucBoxAdminBody"></div>' +
        '</div>';
    document.documentElement.appendChild(overlay);
    overlay.addEventListener('click', function (e) { if (e.target === overlay) _close(); });
    document.getElementById('ucBoxAdminClose').addEventListener('click', _close);

    function _open() {
        if (typeof closeMenuFunction === 'function') closeMenuFunction();
        var body      = document.getElementById('ucBoxAdminBody');
        var alwaysRow = document.getElementById('ucAdminAlwaysRow');
        var title     = document.getElementById('ucMosqueInfoAdminSectionTitle');
        var lockBtn   = document.getElementById('ucAdminLockBtn');
        var btnRow    = document.getElementById('ucAdminBtnRow');
        if (alwaysRow) body.appendChild(alwaysRow);
        if (title)     body.appendChild(title);
        if (lockBtn)   body.appendChild(lockBtn);
        if (btnRow)    body.appendChild(btnRow);
        overlay.classList.add('ucBoxAdminOpen');
    }
    function _close() {
        overlay.classList.remove('ucBoxAdminOpen');
        // Remet les MÊMES noeuds DOM à leur emplacement d'origine (modale
        // "Infos mosquée", mode vertical) -- écouteurs et état de
        // verrouillage (window._ucAdminUnlocked) intacts et partagés.
        if (typeof window._ucRelocateAdminRow === 'function') window._ucRelocateAdminRow();
    }
    menuBtn.addEventListener('click', _open);

    _L('CUSTOM', 'INIT', { item: 'boxHorizontalAdminAccess' });
})();

// ==========================================================================
// -- TOUR D'AIDE AU PREMIER LANCEMENT (ONBOARDING) --------------------------
//  Au premier démarrage de l'application, une bulle d'aide guide
//  l'utilisateur étape par étape vers les éléments-clés de l'écran : menu,
//  nom de la mosquée, date/calendrier hijri, nom de la prochaine prière,
//  verset coranique aléatoire, haut-parleur d'activation de l'Adhan, icône
//  du lecteur Coran, nom de la prière Fajr (changement de thème) et heure
//  de l'Adhan du Fajr (retour au thème précédent). Navigation Précédent/
//  Suivant, abandon possible à tout moment via "Passer". Lancement
//  automatique une seule fois (flag localStorage UC_ONBOARDING_DONE),
//  relançable depuis le menu via le lien injecté dans #menuFooterLinks
//  (même pattern que CONTRÔLE BOX plus haut).
// ==========================================================================
(function _installOnboardingTour() {

    var UC_TOUR_DONE_KEY = 'UC_ONBOARDING_DONE';

    function _tourLang()  { return _ucLang(); }
    function _tourIsRtl(lang) { return (lang === 'AR' || lang === 'UR' || lang === 'FA' || lang === 'KU'); }
    function _tourIsHR()  { return (typeof isHorizontalOrientation !== 'undefined') && isHorizontalOrientation; }

    function _tourIsDone() {
        try { return localStorage.getItem(UC_TOUR_DONE_KEY) === '1'; } catch (e) { return false; }
    }
    function _tourMarkDone() {
        try { localStorage.setItem(UC_TOUR_DONE_KEY, '1'); } catch (e) {}
    }

    // ── Libellés multilingues de l'interface du tour (AR/FR/EN/TR/ID, repli FR) ──
    var L_NEXT = { AR:'التالي',  FR:'Suivant',   EN:'Next', TR:'İleri', ID:'Lanjut'  };
    var L_DONE = { AR:'تم',      FR:'Terminé',   EN:'Done', TR:'Bitti', ID:'Selesai' };
    var L_PREV = { AR:'السابق',  FR:'Précédent', EN:'Back', TR:'Geri',  ID:'Kembali' };
    var L_SKIP = { AR:'تجاوز',   FR:'Passer',    EN:'Skip', TR:'Geç',   ID:'Lewati' };
    var L_LINK = {
        AR:'❓ إعادة شرح الواجهة', FR:"❓ Revoir l'aide", EN:'❓ Replay the tour',
        TR:'❓ Turu tekrar oynat', ID:'❓ Putar ulang tur'
    };

    // ── Textes dépendant du mode vertical/horizontal : recalculés à chaque
    //    rendu d'étape (et non figés à la construction des étapes), pour
    //    rester corrects même si l'orientation change pendant le tour ──────
    function _tourMosqueText() {
        if (_tourIsHR()) {
            // mosqueNameDisplayHorizontal n'ouvre PAS la modale info-mosquée
            // (seul _bindTrigger() sur la variante Vertical le fait) : son
            // onclick natif appelle toggleDatePositionFunction().
            return {
                AR: 'اسم المسجد الحالي. اضغط لتبديل موضع عرض التاريخ (أعلى يمين أو الوضع العادي).',
                FR: 'Nom de la mosquée actuelle. Appuyez pour déplacer la date en haut à droite (ou revenir à sa position normale).',
                EN: 'Current mosque name. Tap to move the date display to the top-right (or back to its normal position).',
                TR: 'Geçerli caminin adı. Tarih görünümünü sağ üste taşımak (veya normal konuma döndürmek) için dokunun.',
                ID: 'Nama masjid saat ini. Ketuk untuk memindahkan tampilan tanggal ke kanan atas (atau kembali ke posisi normal).'
            };
        }
        return {
            AR: 'اسم المسجد الحالي. اضغط عليه لعرض معلوماته وأخباره وتقويم مواقيته.',
            FR: 'Nom de la mosquée actuelle. Appuyez pour voir ses infos, actualités et calendrier.',
            EN: 'Current mosque name. Tap to see its info, news and calendar.',
            TR: 'Geçerli caminin adı. Bilgilerini, haberlerini ve takvimini görmek için dokunun.',
            ID: 'Nama masjid saat ini. Ketuk untuk melihat info, berita, dan kalendernya.'
        };
    }

    function _tourDateText() {
        return {
            AR: 'تاريخ اليوم. اضغط لتصحيح التقويم الهجري يدويًا (من -3 إلى +3 أيام). يصبح رقم اليوم الهجري أحمر عند تفعيل تصحيح يدوي، وأخضر عند تأكيد المزامنة التلقائية دون أي تصحيح.',
            FR: "Date du jour. Appuyez pour corriger manuellement le calendrier hijri (de -3 à +3 jours). Le chiffre du jour hijri devient rouge si une correction manuelle est active, vert si la synchronisation automatique l'a confirmée sans correction.",
            EN: "Today's date. Tap to manually correct the Hijri calendar (-3 to +3 days). The Hijri day number turns red when a manual correction is active, green when automatic sync confirmed it with no correction.",
            TR: 'Bugünün tarihi. Hicri takvimi elle düzeltmek için dokunun (-3 ile +3 gün arası). Elle düzeltme etkinken hicri gün rakamı kırmızı, otomatik senkronizasyon düzeltmesiz onayladığında yeşil olur.',
            ID: 'Tanggal hari ini. Ketuk untuk mengoreksi kalender Hijriah secara manual (-3 hingga +3 hari). Angka hari Hijriah menjadi merah saat koreksi manual aktif, hijau saat sinkronisasi otomatis mengonfirmasi tanpa koreksi.'
        };
    }

    function _tourNextPrayerText() {
        if (_tourIsHR()) {
            // toggleHrNamesMiddleFunction() : inactif si le grand compteur
            // (isBigCounterActive) est affiché, contrairement à la variante
            // verticale qui n'a pas cette garde.
            return {
                AR: 'اضغط لتوسيط أسماء الصلوات في وسط الشاشة (أو الرجوع للوضع العادي). غير متاح عند تفعيل العداد الكبير.',
                FR: "Appuyez pour centrer les noms des prières au milieu de l'écran (ou revenir à la position normale). Indisponible si le grand compteur est actif.",
                EN: 'Tap to center the prayer names in the middle of the screen (or return to normal position). Unavailable while the big counter is active.',
                TR: 'Namaz adlarını ekranın ortasına almak (veya normal konuma döndürmek) için dokunun. Büyük sayaç etkinken kullanılamaz.',
                ID: 'Ketuk untuk menengahkan nama-nama shalat di tengah layar (atau kembali ke posisi normal). Tidak tersedia saat penghitung besar aktif.'
            };
        }
        return {
            AR: 'اضغط لتوسيط أسماء الصلوات في وسط الشاشة (أو الرجوع للوضع العادي).',
            FR: "Appuyez pour centrer les noms des prières au milieu de l'écran (ou revenir à la position normale).",
            EN: 'Tap to center the prayer names in the middle of the screen (or return to normal position).',
            TR: 'Namaz adlarını ekranın ortasına almak (veya normal konuma döndürmek) için dokunun.',
            ID: 'Ketuk untuk menengahkan nama-nama shalat di tengah layar (atau kembali ke posisi normal).'
        };
    }

    // ── Étapes : élément cible (résolu à l'exécution selon l'orientation
    //    courante) + texte d'aide multilingue (statique via "text", ou
    //    dépendant du mode via "getText") ───────────────────────────────────
    function _buildSteps() {
        return [
            {
                getEl: function() { return document.getElementById(_tourIsHR() ? 'menuToggleButtonHorizontal' : 'menuToggleButton'); },
                text: {
                    AR: 'اضغط هنا لفتح القائمة الرئيسية: الإعدادات، الموقع، الأصوات، الشاشة السوداء، وغيرها.',
                    FR: 'Ouvre le menu principal : réglages, position, sons, écran noir, et plus encore.',
                    EN: 'Opens the main menu: settings, location, sounds, black screen, and more.',
                    TR: 'Ana menüyü açar: ayarlar, konum, sesler, kara ekran ve daha fazlası.',
                    ID: 'Membuka menu utama: pengaturan, lokasi, suara, layar hitam, dan lainnya.'
                }
            },
            {
                getEl: function() { return document.getElementById(_tourIsHR() ? 'mosqueNameDisplayHorizontal' : 'mosqueNameDisplayVertical'); },
                getText: _tourMosqueText
            },
            {
                getEl: function() { return document.getElementById(_tourIsHR() ? 'dateDisplayHorizontal' : 'dateDisplayVertical'); },
                getText: _tourDateText
            },
            {
                getEl: function() { return document.getElementById(_tourIsHR() ? 'nextPrayerTimeDisplayHorizontal' : 'nextPrayerTimeDisplayVertical'); },
                getText: _tourNextPrayerText
            },
            {
                getEl: function() { return document.getElementById(_tourIsHR() ? 'ayaTextDisplayHorizontal' : 'ayaTextDisplayVertical'); },
                text: {
                    AR: 'آية قرآنية تُعرض عشوائيًا. اضغط لعرض آية أخرى عشوائيًا.',
                    FR: 'Verset coranique affiché aléatoirement. Appuyez pour en afficher un autre au hasard.',
                    EN: 'Randomly displayed Quranic verse. Tap to show another one at random.',
                    TR: 'Rastgele gösterilen bir Kur’an ayeti. Başka bir ayeti rastgele görmek için dokunun.',
                    ID: 'Ayat Al-Quran yang ditampilkan secara acak. Ketuk untuk menampilkan ayat lain secara acak.'
                }
            },
            {
                getEl: function() { return document.getElementById('customSpeakerIcon'); },
                text: {
                    AR: 'هذا الزر يفعّل أو يوقف صوت الأذان في هذه الشاشة.',
                    FR: "Active ou coupe l'annonce sonore de l'Adhan sur cet écran.",
                    EN: 'Turns the Adhan sound announcement on this screen on or off.',
                    TR: 'Bu ekranda Ezan sesini açar veya kapatır.',
                    ID: 'Mengaktifkan atau mematikan suara Adzan di layar ini.'
                }
            },
            {
                getEl: function() { return document.getElementById('customQuranIcon'); },
                text: {
                    AR: 'يفتح مشغّل تلاوة القرآن الكريم.',
                    FR: 'Ouvre le lecteur de récitation du Coran.',
                    EN: 'Opens the Quran recitation player.',
                    TR: 'Kur’an tilaveti çalarını açar.',
                    ID: 'Membuka pemutar bacaan Al-Quran.'
                }
            },
            {
                getEl: function() {
                    return document.getElementById('prayerNameFajr' + (_tourIsHR() ? 'Horizontal' : 'Vertical'));
                },
                text: {
                    AR: 'اسم صلاة الفجر. اضغط لتغيير سمة ألوان التطبيق.',
                    FR: 'Nom de la prière Fajr. Appuyez pour changer le thème de couleur de l\'application.',
                    EN: "Name of the Fajr prayer. Tap to change the app's color theme.",
                    TR: 'Fecir namazının adı. Uygulamanın renk temasını değiştirmek için dokunun.',
                    ID: 'Nama shalat Subuh. Ketuk untuk mengubah tema warna aplikasi.'
                }
            },
            {
                getEl: function() {
                    return document.getElementById('azanTimeFajr' + (_tourIsHR() ? 'Horizontal' : 'Vertical'));
                },
                text: {
                    AR: 'وقت أذان الفجر. اضغط للرجوع إلى سمة الألوان السابقة.',
                    FR: "Heure de l'Adhan du Fajr. Appuyez pour revenir au thème de couleur précédent.",
                    EN: 'Fajr Adhan time. Tap to go back to the previous color theme.',
                    TR: 'Fecir ezanı vakti. Önceki renk temasına dönmek için dokunun.',
                    ID: 'Waktu Adzan Subuh. Ketuk untuk kembali ke tema warna sebelumnya.'
                }
            }
        ];
    }

    var STEPS           = null;
    var _tourIdx        = 0;
    var _tourActive     = false;
    var _tourRetryTimer = null;

    // ── Injection DOM (une seule fois) ─────────────────────────────────────
    // Ajoutés à document.documentElement (PAS document.body) : même raison
    // que quranPlayerOverlay/ucLogoQuickBarOverlay/mapLocatorOverlay/etc.
    // (cf. leurs commentaires "immune à la rotation du body") — sur un
    // boîtier utilisant applyForcedVerticalClass() (m2body.js, classe
    // vrRIGHT/vrLEFT = transform:rotate() sur <body>), tout position:fixed
    // enfant de <body> se positionne par rapport à la boîte pivotée au lieu
    // du vrai écran. Bug corrigé ici : la bulle du tuto (Précédent/Suivant/
    // Passer) était injectée dans <body> et devenait donc injouable
    // (visuellement présente mais zone cliquable décalée/pivotée) sur ces
    // boîtiers — cf. retour utilisateur "impossible de fermer/naviguer".
    var catcher = document.createElement('div');
    catcher.id  = 'ucTourClickCatcher';
    document.documentElement.appendChild(catcher);

    var spotlight = document.createElement('div');
    spotlight.id  = 'ucTourSpotlight';
    document.documentElement.appendChild(spotlight);

    var bubble = document.createElement('div');
    bubble.id  = 'ucTourBubble';
    bubble.innerHTML =
        '<div id="ucTourStepCount"></div>' +
        '<div id="ucTourText"></div>' +
        '<div id="ucTourBtnRow">' +
        '<span class="ucTourBtn ucTourBtnSkip" id="ucTourSkipBtn"></span>' +
        '<span class="ucTourBtn" id="ucTourPrevBtn"></span>' +
        '<span class="ucTourBtn ucTourBtnPrimary" id="ucTourNextBtn"></span>' +
        '</div>';
    document.documentElement.appendChild(bubble);

    var stepCountEl = document.getElementById('ucTourStepCount');
    var textEl      = document.getElementById('ucTourText');
    var prevBtn     = document.getElementById('ucTourPrevBtn');
    var nextBtn     = document.getElementById('ucTourNextBtn');
    var skipBtn     = document.getElementById('ucTourSkipBtn');

    // ── Positionnement (spotlight = anneau collé à l'élément ; bulle =
    //    sous l'élément si la place le permet, sinon au-dessus, sinon
    //    centrée verticalement) ───────────────────────────────────────────
    function _tourPlaceSpotlight(r) {
        var pad = 6;
        spotlight.style.left   = (r.left - pad) + 'px';
        spotlight.style.top    = (r.top  - pad) + 'px';
        spotlight.style.width  = (r.width  + pad * 2) + 'px';
        spotlight.style.height = (r.height + pad * 2) + 'px';
    }
    function _tourPlaceBubble(r) {
        var margin = 14;
        var vw = window.innerWidth, vh = window.innerHeight;
        var bw = bubble.offsetWidth, bh = bubble.offsetHeight;
        var top;
        if (r.bottom + margin + bh < vh - 8)      top = r.bottom + margin;
        else if (r.top - margin - bh > 8)         top = r.top - margin - bh;
        else                                       top = Math.max(8, (vh - bh) / 2);
        var left = r.left + r.width / 2 - bw / 2;
        left = Math.max(8, Math.min(left, vw - bw - 8));
        bubble.style.top  = top + 'px';
        bubble.style.left = left + 'px';
    }
    function _tourReposition() {
        if (!_tourActive) return;
        var step = STEPS[_tourIdx];
        if (!step) return;
        var el = step.getEl();
        // Garde : élément absent ou pas encore positionné (ex. customSpeakerIcon/
        // customQuranIcon sont placés de façon asynchrone par positionCustomIcons()
        // — voir createCustomSideIcons() plus haut) → on réessaie.
        if (!el) { _tourRetryTimer = setTimeout(_tourReposition, 200); return; }
        var r = el.getBoundingClientRect();
        if (r.width === 0 && r.height === 0) { _tourRetryTimer = setTimeout(_tourReposition, 200); return; }
        _tourPlaceSpotlight(r);
        _tourPlaceBubble(r);
    }

    function _tourRenderStep() {
        if (_tourRetryTimer) { clearTimeout(_tourRetryTimer); _tourRetryTimer = null; }
        var lang = _tourLang();
        var rtl  = _tourIsRtl(lang);
        bubble.style.direction = rtl ? 'rtl' : 'ltr';
        bubble.style.textAlign = rtl ? 'right' : 'left';

        var step     = STEPS[_tourIdx];
        var total    = STEPS.length;
        var stepText = step.getText ? step.getText() : step.text;
        stepCountEl.textContent = (_tourIdx + 1) + ' / ' + total;
        textEl.textContent      = stepText[lang] || stepText.EN;
        prevBtn.style.visibility = (_tourIdx === 0) ? 'hidden' : 'visible';
        nextBtn.textContent = (_tourIdx === total - 1) ? (L_DONE[lang] || L_DONE.EN) : (L_NEXT[lang] || L_NEXT.EN);
        prevBtn.textContent = L_PREV[lang] || L_PREV.EN;
        skipBtn.textContent = L_SKIP[lang] || L_SKIP.EN;

        _tourReposition();
    }

    function _tourNext() {
        if (_tourIdx >= STEPS.length - 1) { _tourFinish(); return; }
        _tourIdx++;
        _tourRenderStep();
    }
    function _tourPrev() {
        if (_tourIdx <= 0) return;
        _tourIdx--;
        _tourRenderStep();
    }
    function _tourFinish() {
        _tourActive = false;
        if (_tourRetryTimer) { clearTimeout(_tourRetryTimer); _tourRetryTimer = null; }
        catcher.classList.remove('ucTourActive');
        spotlight.classList.remove('ucTourActive');
        bubble.classList.remove('ucTourActive');
        _tourMarkDone();
        _L('TOUR', 'FINISH', { lastStep: _tourIdx + 1, total: STEPS.length });
    }

    // Point d'entrée public : lancement initial ET relance manuelle
    // partagent exactement le même chemin de code.
    window._ucStartOnboardingTour = function() {
        STEPS    = _buildSteps();
        _tourIdx = 0;
        _tourActive = true;
        catcher.classList.add('ucTourActive');
        spotlight.classList.add('ucTourActive');
        bubble.classList.add('ucTourActive');
        _tourRenderStep();
        _L('TOUR', 'START', { totalSteps: STEPS.length });
    };

    nextBtn.addEventListener('click', _tourNext);
    prevBtn.addEventListener('click', _tourPrev);
    skipBtn.addEventListener('click', _tourFinish);

    // Réaction au changement d'orientation / redimensionnement pendant le
    // tour : on rafraîchit isHorizontalOrientation nous-mêmes (même garde
    // que _bindMenuToggleClose plus haut) puis on repositionne sur la
    // nouvelle cible (l'ID de l'élément change parfois entre Vertical/
    // Horizontal — getEl() le résout dynamiquement à chaque appel).
    window.addEventListener('resize', function() {
        if (!_tourActive) return;
        if (typeof detectOrientationFunction === 'function') detectOrientationFunction();
        _tourReposition();
    });

    // ── Lancement automatique unique, au premier démarrage uniquement ──────
    // Délai de 1.5s pour laisser le temps à createCustomSideIcons() de
    // positionner customSpeakerIcon/customQuranIcon (sinon la 1ère tentative
    // de repositionnement boucle inutilement sur le garde-fou ci-dessus).
    function _tourAutoStart() {
        if (_tourIsDone()) return;
        // Ne pas amorcer le tour tant qu'aucune mosquee n'est choisie (etat
        // MOSQUE_CONFIG._NO_MOSQUE_SELECTED, pose par spec/mosquee.js) :
        // plusieurs etapes ciblent des elements/textes lies a la mosquee
        // (nom, infos...) qui n'ont pas de sens avant ce choix. Verifie
        // directement window.MOSQUE_CONFIG plutot que via _isAndroidBoxMode()
        // (meme condition) : cette derniere est une fonction PRIVEE a la
        // fermeture de injectTechOptionsUI (pas exposee sur window), donc
        // invisible ici -- un premier essai basé dessus (typeof === 'function')
        // echouait silencieusement et laissait le tour demarrer quand meme.
        // Pas besoin de retenter plus tard : choisir une mosquee declenche
        // toujours un location.reload() (_installMosqueSelector), qui relance
        // cette meme verification au prochain chargement, mosquee choisie.
        if (!window.MOSQUE_CONFIG || window.MOSQUE_CONFIG._NO_MOSQUE_SELECTED) return;
        setTimeout(function() { window._ucStartOnboardingTour(); }, 1500);
    }
    if (document.readyState === 'complete') _tourAutoStart();
    else window.addEventListener('load', _tourAutoStart);

    // ── Lien "Revoir l'aide" — injecté en haut du menu via le conteneur
    // partagé #ucTopMenuLinks (cf. _ucPrependTopMenuLink ci-dessus), au lieu
    // de #menuFooterLinks tout en bas.
    (function _injectTourLink() {
        if (document.getElementById('ucTourRelaunchLink')) return; // déjà injecté
        var a  = document.createElement('a');
        a.href = '#';
        a.id   = 'ucTourRelaunchLink';
        var lang = _tourLang();
        a.innerHTML = L_LINK[lang] || L_LINK.EN;
        a.onclick = function(e) {
            e.preventDefault();
            if (typeof closeMenuFunction === 'function') closeMenuFunction();
            window._ucStartOnboardingTour();
        };
        _ucPrependTopMenuLink(a);
    })();

    _L('CUSTOM', 'INIT', { item: 'onboardingTour' });

})();

// Langue courante de l'UI (JS_DATA.ucLangNOW, ex. 'AR'/'FR'/'EN') — utilisée
// par les liens de menu ci-dessous pour n'afficher qu'une seule langue au lieu
// d'un libellé bilingue figé "AR | EN".
function _ucMenuLinkLang() {
    return _ucLang();
}

// ── Conteneur des liens de menu "prioritaires" ──────────────────────────────
// Injecté comme tout premier enfant de #languageSelectionContainer (donc
// au-dessus de la liste des langues et de #menuFooterLinks) pour les liens
// ucCheckUpdateMenuLink / ucQrCodeMenuLink / ucTourRelaunchLink, qui doivent
// rester visibles en haut du menu plutôt que noyés tout en bas.
function _ucGetTopMenuLinksContainer() {
    var container = document.getElementById('ucTopMenuLinks');
    if (container) return container;
    var langSection = document.getElementById('languageSelectionContainer');
    if (!langSection) return null;
    container = document.createElement('div');
    container.id = 'ucTopMenuLinks';
    langSection.insertBefore(container, langSection.firstChild);
    return container;
}

// Insère `a` (+ un <br> qui le suit) tout en haut du conteneur partagé
// ci-dessus, c.-à-d. avant tout ce qui s'y trouve déjà. Les 3 injecteurs
// s'exécutant dans l'ordre tour -> qr -> update, ce "prepend" systématique
// produit l'ordre final voulu : update, qr, tour (le dernier exécuté finit
// en tête).
function _ucPrependTopMenuLink(a) {
    var container = _ucGetTopMenuLinksContainer();
    if (!container) return false;
    var br = document.createElement('br');
    var firstChild = container.firstChild;
    if (firstChild) {
        container.insertBefore(a, firstChild);
        container.insertBefore(br, firstChild);
    } else {
        container.appendChild(a);
        container.appendChild(br);
    }
    return true;
}

// ── Lien "Afficher le QR Code" — remplace #qrFlagCheckbox (masqué dans la
// section "QR CODE" plus haut) — injecté en haut du menu via le conteneur
// partagé #ucTopMenuLinks (cf. _ucPrependTopMenuLink), au-dessus de
// #ucTourRelaunchLink. Ouvre exactement la même modale que le simple
// clic/tap sur #psFlagImageVertical.
(function _injectQrMenuLink() {
    var L_QR = {
        AR: 'إظهار رمز QR للمسجد', FR: 'Afficher le QR code de la mosquée', EN: 'Show mosque QR code',
        ES: 'Mostrar el código QR de la mezquita', DE: 'Moschee-QR-Code anzeigen'
    };
    var SVG_QR_ICON =
        '<svg viewBox="0 0 24 24" width="1em" height="1em" ' +
             'style="vertical-align:-0.15em;margin-left:6px;" fill="currentColor">' +
            '<path d="M3 3h7v7H3V3zm2 2v3h3V5H5zm-2 9h7v7H3v-7zm2 2v3h3v-3H5zm9-13h7v7h-7V3zm2 2v3h3V5h-3z' +
                  'M13 13h2v2h-2v-2zm4 0h2v2h-2v-2zm-4 4h2v2h-2v-2zm4 0h2v2h-2v-2zm2-4h2v2h-2v-2zm0 4h2v2h-2v-2z"/>' +
        '</svg>';

    function _bind() {
        if (!document.getElementById('languageSelectionContainer')) return false;
        if (document.getElementById('ucQrCodeMenuLink')) return true; // déjà injecté

        var a  = document.createElement('a');
        a.href = '#';
        a.id   = 'ucQrCodeMenuLink';
        a.innerHTML = SVG_QR_ICON + (L_QR[_ucMenuLinkLang()] || L_QR.EN);
        a.onclick = function (e) {
            e.preventDefault();
            if (typeof closeMenuFunction === 'function') closeMenuFunction();
            if (typeof window.openQrCodeModal === 'function') window.openQrCodeModal();
        };
        _ucPrependTopMenuLink(a);
        return true;
    }
    if (!_bind()) {
        document.addEventListener('DOMContentLoaded', function () {
            if (!_bind()) setTimeout(_bind, 300);
        });
    }

    _L('CUSTOM', 'INIT', { item: 'qrCodeMenuLink' });
})();

